INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12226, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12226, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "边界层指流体（如空气或水）流经固体表面时，在紧贴表面处形成的流速变化很大的薄层。", "primary_collocate": null, "pronunciation": "biān jiè céng", "ipa": "pjɛn˥ tɕjɛ˥˩ tsʰɤŋ˧˥", "syllable_count": 3, "sentences": [{"text": "研究人员在风洞里观察紧贴机翼的边界层。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机飞行时，机翼表面会形成一层边界层。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边界层很薄，但是它会影响飞机的阻力。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气流过机翼时，边界层里的速度变化很大。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风吹过大楼的墙面，墙边有一层边界层。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水流过船底，船底附近也有边界层。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边界层越厚，空气流动就越不稳定。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在测量机翼上边界层的厚度。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车跑得很快，车身表面有一层边界层。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个实验是为了研究管道里的边界层。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "邊界層", "label": "繁体"}, {"form": "层流边界层", "label": "复合"}, {"form": "湍流边界层", "label": "复合"}], "register": "书面语", "sense_fingerprint": "流体流过固体表面时紧贴表面、流速变化大的薄层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b777eb8-5c72-40a7-b82c-0975259d6e64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12226, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "边界层", "is_correct": true, "explanation": "“边界层”指紧贴固体表面的流体薄层，此处指紧贴机翼的那层气流，句意通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是大气现象，不是紧贴机翼的薄层，句子说不通。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：“行李”不是流体，不能紧贴机翼表面，句子说不通。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是人，不是流体，不能紧贴机翼表面，句子说不通。"}], "explanations": {"边界层": "“边界层”指紧贴固体表面的流体薄层，此处指紧贴机翼的那层气流，句意通顺。", "天气": "语义：“天气”是大气现象，不是紧贴机翼的薄层，句子说不通。", "行李": "搭配：“行李”不是流体，不能紧贴机翼表面，句子说不通。", "乘客": "语义：乘客是人，不是流体，不能紧贴机翼表面，句子说不通。"}, "sentence_index": 0, "correct_answer": "边界层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个软件的边界层很漂亮。", "explanation": "这里应该用〈界面〉。界面指软件或设备供人操作和观看的部分，边界层指流体紧贴固体表面的薄层，不能用来形容软件外观。"}, {"text": "两国之间的边界层很清楚。", "explanation": "这里应该用〈边界〉。边界指两个地区之间的分界线，边界层指流体紧贴固体表面的薄层，不指国界。"}, {"text": "机翼表面有一条边界层。", "explanation": "这里的量词“条”用于细长的东西，如绳子、河流，不能用于边界层。边界层是紧贴表面的薄层，应该用量词“层”，说“一层边界层”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12226, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "边界层", "is_correct": true, "explanation": "“边界层”指紧贴物体表面的流体薄层，“越厚，空气流动就越不稳定”说的正是它。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包的厚薄与空气流动的稳定性没有关系，句子说不通。"}, {"text": "书本", "is_correct": false, "explanation": "语义：书本的厚薄不会影响空气流动，句子说不通。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“石头”可以说厚，但“越厚……空气流动越不稳定”里的因果不能由石头的厚度来承担。"}], "explanations": {"边界层": "“边界层”指紧贴物体表面的流体薄层，“越厚，空气流动就越不稳定”说的正是它。", "面包": "语义：面包的厚薄与空气流动的稳定性没有关系，句子说不通。", "书本": "语义：书本的厚薄不会影响空气流动，句子说不通。", "石头": "搭配：“石头”可以说厚，但“越厚……空气流动越不稳定”里的因果不能由石头的厚度来承担。"}, "sentence_index": 6, "correct_answer": "边界层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "土壤的边界层很肥沃。", "explanation": "这里应该用〈表层〉。表层指地表或土壤最外面的一层，边界层指流体紧贴固体表面的薄层，不指土壤。"}, {"text": "这个柜子的边界层可以放书。", "explanation": "这里应该用〈隔板〉。隔板指柜子内部分隔空间的板，可以放东西。边界层是流体紧贴固体表面的薄层，不能用来放书。"}, {"text": "这里的边界层很厚，有很多化石。", "explanation": "这里应该用〈地层〉。地层指地壳中成层的岩石，可以含有化石；边界层是流体的薄层，不是岩层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12226, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "薄薄的一条边界层紧贴着机翼表面。", "corrected_sentence": "薄薄的一层边界层紧贴着机翼表面。", "error_description": "量词错误：“边界层”应使用量词“层”，说“一层边界层”，不能说“一条边界层”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12226, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "管道内壁附近常常有一个很薄的边界层。", "corrected_sentence": "管道内壁附近常常有一层很薄的边界层。", "error_description": "量词错误：“边界层”应使用量词“层”，说“一层很薄的边界层”，不能说“一个很薄的边界层”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12227, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "呼出", "is_correct": true, "explanation": "“呼出”指把气体从体内排出，与“吸入”把气体吸进体内正相反。"}, {"text": "演奏", "is_correct": false, "explanation": "“演奏”指表演乐器或乐曲，与“吸入”没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "“修理”指使损坏的东西恢复正常，与“吸入”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”指随意走动，与“吸入”没有反义关系。"}], "correct_answer": "呼出", "explanations": {"呼出": "“呼出”指把气体从体内排出，与“吸入”把气体吸进体内正相反。", "演奏": "“演奏”指表演乐器或乐曲，与“吸入”没有反义关系。", "修理": "“修理”指使损坏的东西恢复正常，与“吸入”没有反义关系。", "散步": "“散步”指随意走动，与“吸入”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12227, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "呼出", "is_correct": true, "explanation": "“呼出”指把气体从体内排出，与“吸入”把气体吸进体内正相反。"}, {"text": "擦拭", "is_correct": false, "explanation": "“擦拭”指擦掉表面的污物，与“吸入”没有反义关系。"}, {"text": "编织", "is_correct": false, "explanation": "“编织”指把线或条状物交错组合，与“吸入”没有反义关系。"}, {"text": "投掷", "is_correct": false, "explanation": "“投掷”指把东西用力扔出去，与“吸入”没有反义关系。"}], "correct_answer": "呼出", "explanations": {"呼出": "“呼出”指把气体从体内排出，与“吸入”把气体吸进体内正相反。", "擦拭": "“擦拭”指擦掉表面的污物，与“吸入”没有反义关系。", "编织": "“编织”指把线或条状物交错组合，与“吸入”没有反义关系。", "投掷": "“投掷”指把东西用力扔出去，与“吸入”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12227, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过呼吸将气体或细小颗粒物从外部引入体内。", "primary_collocate": null, "pronunciation": "xī rù", "ipa": "ɕi˥ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "他戴着口罩走进车间，尽量少吸入粉尘。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心吸入了很多烟。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人吸入灰尘太多，开始咳嗽。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火灾时，人们容易吸入有毒的烟雾。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请戴上口罩，不要吸入脏空气。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他吸入了一些化学气体。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子吸入花粉后，一直打喷嚏。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吸入太多灰尘对肺不好。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "潜水员在水下要吸入压缩空气。", "target_word": "吸入", "complexity_tier": "T3", "furigana": "qián shuǐ yuán zài shuǐ xià yào xī rù yā suō kōng qì", "sentence_source": "generated"}, {"text": "他吸入了一口冷空气，咳了起来。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吸入了", "label": "体标"}, {"form": "吸入过", "label": "体标"}, {"form": "吸入量", "label": "复合"}], "register": "书面语", "sense_fingerprint": "经呼吸把气体、粉尘等从外面吸进体内", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b777eb8-5c72-40a7-b82c-0975259d6e64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12227, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吸入", "is_correct": true, "explanation": "“吸入”指经呼吸把粉尘等颗粒吸进体内，“尽量少吸入粉尘”句意通顺。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指送入口中咽下，与经呼吸吸入粉尘的动作不符，句子说不通。"}, {"text": "读", "is_correct": false, "explanation": "语义：“读”的对象是文字，粉尘不能被“读”，句子说不通。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：“拍”不能与“粉尘”搭配，句子说不通。"}], "explanations": {"吸入": "“吸入”指经呼吸把粉尘等颗粒吸进体内，“尽量少吸入粉尘”句意通顺。", "吃": "语义：“吃”指送入口中咽下，与经呼吸吸入粉尘的动作不符，句子说不通。", "读": "语义：“读”的对象是文字，粉尘不能被“读”，句子说不通。", "拍": "搭配：“拍”不能与“粉尘”搭配，句子说不通。"}, "sentence_index": 0, "correct_answer": "吸入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人体通过肠道吸入营养。", "explanation": "这里应该用〈吸收〉。吸收指从外界获取营养或水分，吸入指经呼吸把气体吸进体内，不能用于肠道获取营养。"}, {"text": "他渴了，吸入了一杯水。", "explanation": "这里应该用〈喝〉。喝指把液体送入口中咽下，吸入指经呼吸把气体吸进体内，不能用于水。"}, {"text": "磁铁能吸入铁钉。", "explanation": "这里应该用〈吸附〉。吸附指物体靠引力附着在另一物体上，吸入指经呼吸把气体或颗粒吸进体内。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12227, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吸入", "is_correct": true, "explanation": "“吸入”指经呼吸把花粉等颗粒吸进体内，与“打喷嚏”的句意相符。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”不能与“花粉”构成吸入的动作，句子说不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“花粉”作宾语。"}, {"text": "穿", "is_correct": false, "explanation": "语义：花粉是颗粒，不能被“穿”，句子说不通。"}], "explanations": {"吸入": "“吸入”指经呼吸把花粉等颗粒吸进体内，与“打喷嚏”的句意相符。", "写": "语义：“写”不能与“花粉”构成吸入的动作，句子说不通。", "唱": "搭配：“唱”不能带“花粉”作宾语。", "穿": "语义：花粉是颗粒，不能被“穿”，句子说不通。"}, "sentence_index": 6, "correct_answer": "吸入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个节目吸入了很多观众。", "explanation": "这里应该用〈吸引〉。吸引指使人注意或喜爱，吸入指把气体吸进体内，不能用于观众。"}, {"text": "他慢慢吸入着面包。", "explanation": "这里应该用〈嚼〉。嚼指咀嚼食物，吸入指经呼吸把气体吸进身体，不能用于固体食物。"}, {"text": "他认真吸入比赛。", "explanation": "这里应该用〈观看〉。观看指用眼睛看，吸入指经呼吸把气体吸进体内，不能用于比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12227, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "沙尘暴来的时候，人们应该避免吸入了尘土。", "corrected_sentence": "沙尘暴来的时候，人们应该避免吸入尘土。", "error_description": "“了”误用：“避免”针对的是还没有发生的动作，“吸入”后不能加“了”，应说“避免吸入尘土”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12227, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没有吸入了这么冷的空气。", "corrected_sentence": "他从来没有吸入过这么冷的空气。", "error_description": "“了”误用：“从来没有”后表示经历要用“过”，应说“没有吸入过”，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
