INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12229, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12229, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "流体从窄口或小孔中高速喷出的现象或物质流。", "primary_collocate": null, "pronunciation": "shè liú", "ipa": "ʂɤ⁵¹ ljoʊ³⁵", "syllable_count": 2, "sentences": [{"text": "此外，主动流动控制技术，如边界层吸入或合成射流，正在被探索用于实时调节气流分离，进一步延展飞行包线。", "target_word": "射流", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "水从小孔里喷出来，形成一股射流。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "射流的速度很快，可以切开很硬的东西。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火箭发动机后面喷出一道长长的射流。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水枪喷出的射流可以打到十米远。", "target_word": "射流", "complexity_tier": "T3", "furigana": "shuǐ qiāng pēn chū de shè liú kě yǐ dǎ dào shí mǐ yuǎn.", "sentence_source": "generated"}, {"text": "工人用高压射流清洗墙上的脏东西。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管子很细，所以射流的力量特别大。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手指放在水管口，射流立刻变小了。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里的射流是用一台小泵产生的。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机发动机的射流会发出很大的声音。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "水射流", "label": "复合"}, {"form": "射流泵", "label": "复合"}], "register": "专业", "sense_fingerprint": "射流：流体从窄口或小孔高速喷出的现象或物质流", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24631489-7be5-43ad-b7ec-de458e1dff98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12229, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "射流", "is_correct": true, "explanation": "“射流”指流体从窄口高速喷出的流，可用于调节气流分离，符合句意。"}, {"text": "电流", "is_correct": false, "explanation": "搭配：“合成”一般不与“电流”搭配，电流也不能直接调节气流分离。"}, {"text": "机翼", "is_correct": false, "explanation": "语义：机翼是飞机的承力部件，不是可以“合成”的流动控制手段，与“调节气流分离”不符。"}, {"text": "蛋白质", "is_correct": false, "explanation": "语义：蛋白质与气流无关，不能用来调节气流分离，与句中的技术语境矛盾。"}], "explanations": {"射流": "“射流”指流体从窄口高速喷出的流，可用于调节气流分离，符合句意。", "电流": "搭配：“合成”一般不与“电流”搭配，电流也不能直接调节气流分离。", "机翼": "语义：机翼是飞机的承力部件，不是可以“合成”的流动控制手段，与“调节气流分离”不符。", "蛋白质": "语义：蛋白质与气流无关，不能用来调节气流分离，与句中的技术语境矛盾。"}, "sentence_index": 0, "correct_answer": "射流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "河里的射流很慢，一点儿也不急。", "explanation": "这里应该用〈水流〉。射流指从窄口或小孔高速喷出的流，缓慢流动的河水要用〈水流〉。"}, {"text": "春天的风带来了一股暖暖的射流。", "explanation": "这里应该用〈气流〉。射流是高速从窄口喷出的流，温和的春风要用〈气流〉。"}, {"text": "我看见墙角有一只射流。", "explanation": "这里应该用〈股〉。射流的量词是“股”或“道”，不用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12229, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "射流", "is_correct": true, "explanation": "“射流”是细而快速喷出的流，细管子里喷出的射流力量大，符合句意。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流宽阔，不可能从很细的管子里产生，与“管子很细”矛盾。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：海浪由风和潮汐形成，与“管子很细”的线索相矛盾。"}, {"text": "电压", "is_correct": false, "explanation": "搭配：形容电压一般说“高”或“低”，不说“力量特别大”。"}], "explanations": {"射流": "“射流”是细而快速喷出的流，细管子里喷出的射流力量大，符合句意。", "河流": "语义：河流宽阔，不可能从很细的管子里产生，与“管子很细”矛盾。", "海浪": "语义：海浪由风和潮汐形成，与“管子很细”的线索相矛盾。", "电压": "搭配：形容电压一般说“高”或“低”，不说“力量特别大”。"}, "sentence_index": 6, "correct_answer": "射流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山谷里的射流又宽又平，静静地铺在石头上。", "explanation": "这里应该用〈湖水〉。射流细而急，从窄口高速喷出，不能形容又宽又平、静静铺开的水面。"}, {"text": "山间的射流慢慢冒出来，清凉可口。", "explanation": "这里应该用〈泉水〉。射流是高速喷出的，不会慢慢冒出；缓缓涌出的清泉要用〈泉水〉。"}, {"text": "喷雾器轻轻喷出一股射流，很柔和。", "explanation": "这里应该用〈细雾〉。射流是高速喷出的强流，“轻轻”“很柔和”的喷出物要用〈细雾〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12229, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一座有力的射流从小孔里喷了出来。", "corrected_sentence": "一股有力的射流从小孔里喷了出来。", "error_description": "错误：“一座”。正确：“一股”。“座”用于山、建筑等大型固定之物，射流是流动的流体，应用“股”或“道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12229, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一块射流从管口喷了出来。", "corrected_sentence": "一道射流从管口喷了出来。", "error_description": "“一块射流”错，应为“一道射流”。“块”用于成块的固体，射流是喷出的流体，要用“道”“股”等量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12231, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "结合", "is_correct": true, "explanation": "结合：与“分离”相反，指把东西合在一起，是“分离”的反义词。"}, {"text": "保存", "is_correct": false, "explanation": "保存：指留存不失，与“分离”没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "观察：指仔细看，与“分离”没有反义关系。"}, {"text": "加热", "is_correct": false, "explanation": "加热：指使东西温度升高，与“分离”没有反义关系。"}], "correct_answer": "结合", "explanations": {"结合": "结合：与“分离”相反，指把东西合在一起，是“分离”的反义词。", "保存": "保存：指留存不失，与“分离”没有反义关系。", "观察": "观察：指仔细看，与“分离”没有反义关系。", "加热": "加热：指使东西温度升高，与“分离”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12231, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "结合", "is_correct": true, "explanation": "结合：与“分离”相反，指把东西合在一起，是“分离”的反义词。"}, {"text": "布置", "is_correct": false, "explanation": "布置：指安排、摆设，与“分离”没有反义关系。"}, {"text": "寻找", "is_correct": false, "explanation": "寻找：指设法找到，与“分离”没有反义关系。"}, {"text": "记录", "is_correct": false, "explanation": "记录：指把内容写下来，与“分离”没有反义关系。"}], "correct_answer": "结合", "explanations": {"结合": "结合：与“分离”相反，指把东西合在一起，是“分离”的反义词。", "布置": "布置：指安排、摆设，与“分离”没有反义关系。", "寻找": "寻找：指设法找到，与“分离”没有反义关系。", "记录": "记录：指把内容写下来，与“分离”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12231, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "分开；使分开。", "primary_collocate": null, "pronunciation": "fēn lí", "ipa": "fən˥ li˧˥", "syllable_count": 2, "sentences": [{"text": "离心机转动后，血液里的血浆和血细胞会分离。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室用机器把血液里的细胞分离出来。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "油和水不能混在一起，很容易分离。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家想把盐从海水中分离出来。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种机器可以分离牛奶和奶油。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水和沙子放久了就会分离。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用过滤的方法分离泥沙和水。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "试管里的液体已经分离成两层。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把铁和石头分离开。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把蛋黄和蛋白分离，需要一点技巧。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分離", "label": "繁体"}, {"form": "分离了", "label": "体标"}, {"form": "分离出来", "label": "复合"}, {"form": "分离器", "label": "复合"}], "register": "书面语", "sense_fingerprint": "把混合或连在一起的东西分开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b777eb8-5c72-40a7-b82c-0975259d6e64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12231, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分离", "is_correct": true, "explanation": "与听到的读音一致，fēn lí，意思是分开、使分开。"}, {"text": "奋力", "is_correct": false, "explanation": "fèn lì（第四声）与 fēn lí 的声调不同，意思是尽力、用力。"}, {"text": "分立", "is_correct": false, "explanation": "fēn lì（第四声）与 fēn lí 的 lí（第二声）声调不同，意思是分开设立、彼此独立。"}, {"text": "分理", "is_correct": false, "explanation": "fēn lǐ（第三声）与 fēn lí 的 lí 声调不同，意思是条理，较少用。"}], "explanations": {"分离": "与听到的读音一致，fēn lí，意思是分开、使分开。", "奋力": "fèn lì（第四声）与 fēn lí 的声调不同，意思是尽力、用力。", "分立": "fēn lì（第四声）与 fēn lí 的 lí（第二声）声调不同，意思是分开设立、彼此独立。", "分理": "fēn lǐ（第三声）与 fēn lí 的 lí 声调不同，意思是条理，较少用。"}, "sentence_index": null, "correct_answer": "分离"}, "level_3": {"options": [{"text": "分离", "is_correct": true, "explanation": "分离：指血浆与血细胞被离心后分开，与“离心机转动后”的句意相符。"}, {"text": "爆炸", "is_correct": false, "explanation": "语义：“爆炸”指突然炸开，血浆和血细胞不会爆炸，句子说不通。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指固体遇热变成液体，血浆和血细胞不会融化，句子说不通。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：“烧毁”指用火使东西毁坏，与离心后分开的过程无关，句子说不通。"}], "explanations": {"分离": "分离：指血浆与血细胞被离心后分开，与“离心机转动后”的句意相符。", "爆炸": "语义：“爆炸”指突然炸开，血浆和血细胞不会爆炸，句子说不通。", "融化": "语义：“融化”指固体遇热变成液体，血浆和血细胞不会融化，句子说不通。", "烧毁": "语义：“烧毁”指用火使东西毁坏，与离心后分开的过程无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "分离"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "用一道墙把两个房间分离开。", "explanation": "这里应该用〈分隔〉。分离多指把混合或连在一起的东西拆开，用墙划分空间要用分隔。"}, {"text": "我们认真分离了这次事故的原因。", "explanation": "这里应该用〈分析〉。分离指把混合或连在一起的东西拆开，研究事故的原因要用分析。"}, {"text": "我把钱分离给了孩子。", "explanation": "这里应该用〈分给〉。分离是把混合或连着的东西拆开，分钱给孩子要用分给。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12231, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分离", "is_correct": true, "explanation": "分离：把混合物按成分分开，与“用过滤的方法”一致。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：“烧毁”指用火使东西毁坏，与过滤的分离方法无关，句意不通。"}, {"text": "粉碎", "is_correct": false, "explanation": "搭配：“粉碎”的对象是固体，水不能被粉碎，不能与“和水”搭配。"}, {"text": "收割", "is_correct": false, "explanation": "语义：“收割”指割取庄稼，泥沙和水不能被收割，句意不通。"}], "explanations": {"分离": "分离：把混合物按成分分开，与“用过滤的方法”一致。", "烧毁": "语义：“烧毁”指用火使东西毁坏，与过滤的分离方法无关，句意不通。", "粉碎": "搭配：“粉碎”的对象是固体，水不能被粉碎，不能与“和水”搭配。", "收割": "语义：“收割”指割取庄稼，泥沙和水不能被收割，句意不通。"}, "sentence_index": 6, "correct_answer": "分离"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一起分离了快乐。", "explanation": "这里应该用〈分享〉。分离指拆开或不再在一起，分享快乐要用分享。"}, {"text": "我们要分离真假。", "explanation": "这里应该用〈分辨〉。分离强调拆开，分清真假要用分辨。"}, {"text": "我们一起分离家务。", "explanation": "这里应该用〈分担〉。分离不表示共同承担，分担家务才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12231, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂用离心机把油从水里被分离出来。", "corrected_sentence": "工厂用离心机把油从水里分离出来。", "error_description": "“把”字句与“被”字句混用：“把”和“被”不能同时用在同一谓语前，应删去“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12231, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "用分液漏斗把油和水分离了开。", "corrected_sentence": "用分液漏斗把油和水分离开了。", "error_description": "“了”的位置错误：“了”应放在补语“开”之后，写成“分离了开”是错误的，应为“分离开了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
