INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12232, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "包线指包裹在电线或电缆外部的绝缘保护层。", "primary_collocate": null, "pronunciation": "bāo xiàn", "ipa": "pɑʊ̯˥ ɕi̯ɛn˥˩", "syllable_count": 2, "sentences": [{"text": "电工用胶带把破损的包线缠好，防止漏电。", "target_word": "包线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根电线的包线破了，里面的铜丝露了出来。", "target_word": "包线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电工用刀小心地剥开了电缆的包线。", "target_word": "包线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "包线老化以后，电线容易漏电。", "target_word": "包线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的包线可以防水，也能防止触电。", "target_word": "包线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条电缆的包线是黑色的，很厚。", "target_word": "包线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子咬坏了充电线的包线，太危险了。", "target_word": "包线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先检查包线有没有裂开，再通电。", "target_word": "包线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅把电缆两端的包线剥掉了两厘米。", "target_word": "包线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "包线外面印着电缆的型号和长度。", "target_word": "包线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一根包线", "label": "量词"}, {"form": "包線", "label": "繁体"}], "register": "中性", "sense_fingerprint": "电线电缆外层的绝缘保护层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b777eb8-5c72-40a7-b82c-0975259d6e64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12232, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "包线", "is_correct": true, "explanation": "包线：指电线外的绝缘保护层，破损后要缠好，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是实物，不能用胶带缠好，句子说不通。"}, {"text": "亮度", "is_correct": false, "explanation": "搭配：“亮度”是属性，不能被胶带缠绕，句子说不通。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不是实物，不能用胶带缠好，句子说不通。"}], "explanations": {"包线": "包线：指电线外的绝缘保护层，破损后要缠好，与句意相符。", "颜色": "语义：颜色不是实物，不能用胶带缠好，句子说不通。", "亮度": "搭配：“亮度”是属性，不能被胶带缠绕，句子说不通。", "时间": "语义：时间不是实物，不能用胶带缠好，句子说不通。"}, "sentence_index": 0, "correct_answer": "包线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电线里面的包线是铜做的。", "explanation": "这里应该用〈导线〉。导线是传导电流的金属线，包线是绝缘外层，不是铜做的。"}, {"text": "他把包线插进了插座。", "explanation": "这里应该用〈插头〉。插头是插进插座的部件，包线只是电线外的绝缘层，不能插进插座。"}, {"text": "用包线把破的地方缠好。", "explanation": "这里应该用〈绝缘胶〉。绝缘胶用来缠绕破损处，包线是电线外层，不是用来缠绕的材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12232, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "包线", "is_correct": true, "explanation": "包线：充电线外面的绝缘层，咬坏后会有触电的危险，符合句意。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”是抽象感受，不是实物，不能被咬坏，句意不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”看不见摸不着，不能被咬坏，句意不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”是听觉感受，不能被咬坏，句意不通。"}], "explanations": {"包线": "包线：充电线外面的绝缘层，咬坏后会有触电的危险，符合句意。", "心情": "语义：“心情”是抽象感受，不是实物，不能被咬坏，句意不通。", "空气": "语义：“空气”看不见摸不着，不能被咬坏，句意不通。", "声音": "语义：“声音”是听觉感受，不能被咬坏，句意不通。"}, "sentence_index": 6, "correct_answer": "包线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根电线的包线能导电。", "explanation": "这里应该用〈线芯〉。线芯才是导电的部分，包线是绝缘层，不导电。"}, {"text": "我剪下了一片包线。", "explanation": "量词错误：这里应该用〈段〉。包线呈细长线状，“片”用于平面的东西，不用于包线。"}, {"text": "我们在包线里装了一些水果。", "explanation": "这里应该用〈包装〉。包装指包裹商品的外层，包线是电线的绝缘层，不能用来装水果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12232, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电工剪下一个包线。", "corrected_sentence": "电工剪下一段包线。", "error_description": "量词错误：包线是细长的线状物，量词应用“段”，用“个”不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12232, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把包线剥掉了一片，露出了里面的铜丝。", "corrected_sentence": "工人把包线剥掉了一段，露出了里面的铜丝。", "error_description": "量词错误：包线是细长的线状物，量词应用“段”，用“片”不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
