INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12233, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指处于发展最前端、具有创新性和领先性的技术。", "primary_collocate": null, "pronunciation": "qián yán jì shù", "ipa": "t͡ɕʰi̯ɛn˧˥ i̯ɛn˧˥ t͡ɕi˥˩ ʂu˥˩", "syllable_count": 4, "sentences": [{"text": "这些前沿技术的背后，是对纳维-斯托克斯方程组的深入求解，其非线性特性使得湍流建模至今仍是物理学界未完全攻克的难题。", "target_word": "前沿技术", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司每年都投入很多资金研究前沿技术。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学的实验室专门研究前沿技术。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人工智能是现在最受关注的前沿技术之一。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想学习前沿技术，所以去国外读书了。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前沿技术改变了我们的生活方式。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项前沿技术还没有走进普通人的家里。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览会上展示了许多国家的前沿技术。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "掌握前沿技术的人才非常受欢迎。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者采访了几位研究前沿技术的科学家。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项前沿技术", "label": "量词"}, {"form": "前沿技術", "label": "繁体"}], "register": "书面", "sense_fingerprint": "处于发展最前端、有创新性和领先性的技术", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b777eb8-5c72-40a7-b82c-0975259d6e64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12233, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前沿技术", "is_correct": true, "explanation": "正确：句中“背后”指向深入求解方程组、研究湍流建模这类科研工作，“前沿技术”符合这一语境。"}, {"text": "流行时尚", "is_correct": false, "explanation": "语义：“流行时尚”指一时兴起的潮流，与方程组求解、湍流建模的科研内容完全无关。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与这句书面、学术化的叙述风格不协调。"}, {"text": "家常菜", "is_correct": false, "explanation": "语义：“家常菜”是日常饮食，无法说明非线性特性与物理学难题之间的关系。"}], "explanations": {"前沿技术": "正确：句中“背后”指向深入求解方程组、研究湍流建模这类科研工作，“前沿技术”符合这一语境。", "流行时尚": "语义：“流行时尚”指一时兴起的潮流，与方程组求解、湍流建模的科研内容完全无关。", "玩意儿": "语域：“玩意儿”是口语说法，与这句书面、学术化的叙述风格不协调。", "家常菜": "语义：“家常菜”是日常饮食，无法说明非线性特性与物理学难题之间的关系。"}, "sentence_index": 0, "correct_answer": "前沿技术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他掌握了一只前沿技术。", "explanation": "这里应该用〈一项〉。“只”用于动物或单件物品，技术要用“项”或“门”计数，不能说“一只技术”。"}, {"text": "我们家一直用前沿技术做豆腐，这种做法流传了三代人。", "explanation": "这里应该用〈传统工艺〉。“前沿技术”指处于最前端的科技，而祖传的做豆腐方法属于传统工艺，不能用“前沿”来形容。"}, {"text": "我奶奶的前沿技术很好，包的饺子又快又漂亮。", "explanation": "这里的“技术”指个人的手艺，而“前沿技术”指最前端的科技，不能用来说家常包饺子的本领。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12233, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前沿技术", "is_correct": true, "explanation": "正确：“这项”修饰尚未普及的尖端技术，与“还没有走进普通人的家里”的语境相符。"}, {"text": "深海勘探", "is_correct": false, "explanation": "语义：深海勘探发生在海底，与“走进普通人的家里”的语境不符。"}, {"text": "远古化石", "is_correct": false, "explanation": "搭配：量词“项”多用于技术、工程、计划，不能用来计量化石。"}, {"text": "宇宙飞船", "is_correct": false, "explanation": "搭配：飞船应以“艘”计量，而且飞船也不会“走进普通人的家里”。"}], "explanations": {"前沿技术": "正确：“这项”修饰尚未普及的尖端技术，与“还没有走进普通人的家里”的语境相符。", "深海勘探": "语义：深海勘探发生在海底，与“走进普通人的家里”的语境不符。", "远古化石": "搭配：量词“项”多用于技术、工程、计划，不能用来计量化石。", "宇宙飞船": "搭配：飞船应以“艘”计量，而且飞船也不会“走进普通人的家里”。"}, "sentence_index": 6, "correct_answer": "前沿技术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这项前沿技术就是国境线上的那片哨所，由武警日夜守卫。", "explanation": "这里的“前沿技术”指最前端的科技，不能指国境线上的哨所，句子把科技说成了一座建筑，属于指称错误。"}, {"text": "这家工厂引进了一台前沿技术。", "explanation": "这里应该用〈一项〉。“台”用于机器、设备，技术不是具体的机器，要用“项”或“门”计数。"}, {"text": "他去市场买了两斤前沿技术。", "explanation": "“斤”是重量单位，只用于可以称重的东西；技术没有重量，不能用“斤”计量，这里应该用〈一项〉或〈一门〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12233, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司引进了一本前沿技术。", "corrected_sentence": "我们公司引进了一项前沿技术。", "error_description": "错误形式“一本前沿技术”，正确形式“一项前沿技术”。“本”用于书籍、册子，技术不是可以翻阅的书，应改用“项”计数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12233, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们已经学完前沿技术着。", "corrected_sentence": "我们已经学完前沿技术了。", "error_description": "体标错误：“学完”表示动作已经完成，句末应用“了”，用“着”不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
