INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12236, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由两个或两个以上的方程联立而成的一组方程，通常需要同时求解。", "primary_collocate": null, "pronunciation": "fāng chéng zǔ", "ipa": "faŋ˥ ʈʂʰɤŋ˧˥ tsu˨˩˦", "syllable_count": 3, "sentences": [{"text": "这些前沿技术的背后，是对一个耦合偏微分方程组的深入求解，其非线性特性使得湍流建模至今仍是物理学界未完全攻克的难题。", "target_word": "方程组", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这个方程组有两个未知数。", "target_word": "方程组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们解这个方程组。", "target_word": "方程组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "解方程组需要先消去一个未知数。", "target_word": "方程组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师用计算机求解这个方程组。", "target_word": "方程组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方程组只有一组解。", "target_word": "方程组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她列出了一个二元方程组。", "target_word": "方程组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方程组无解，因为两个方程互相矛盾。", "target_word": "方程组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把方程组写在黑板上。", "target_word": "方程组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题要先建立方程组再求解。", "target_word": "方程组", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "方程組", "label": "繁体"}], "register": "专业", "sense_fingerprint": "数学术语：由多个方程联立、需同时求解的一组方程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7c84d0d-b658-4011-a3cd-9d3d112aea10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12236, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方程组", "is_correct": true, "explanation": "正确：偏微分方程组是由多个方程联立而成的一组方程，需要同时求解，与“深入求解”搭配。"}, {"text": "绘画", "is_correct": false, "explanation": "搭配：“求解”的对象是方程或方程组，绘画不能被求解。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：乐谱是音乐记号，与流体力学中的方程无关，不能对它进行求解。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱是烹饪指南，与物理学界的数学难题无关。"}], "explanations": {"方程组": "正确：偏微分方程组是由多个方程联立而成的一组方程，需要同时求解，与“深入求解”搭配。", "绘画": "搭配：“求解”的对象是方程或方程组，绘画不能被求解。", "乐谱": "语义：乐谱是音乐记号，与流体力学中的方程无关，不能对它进行求解。", "食谱": "语义：食谱是烹饪指南，与物理学界的数学难题无关。"}, "sentence_index": 0, "correct_answer": "方程组"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "勾股定理的方程组是 a²+b²=c²。", "explanation": "这里应该用〈公式〉。方程组指由几个方程联立而成的一组方程，单个等式不能叫方程组。"}, {"text": "我在黑板上写了一个方程组，它只有一个等式。", "explanation": "这里应该用〈方程〉。方程组由两个或两个以上的方程联立而成，只有一个等式时应说方程，不能说方程组。"}, {"text": "我在黑板上写了一把方程组。", "explanation": "这里应该用〈个〉。量词「把」用于有柄的器具，方程组应配「个」或「组」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12236, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方程组", "is_correct": true, "explanation": "正确：二元方程组指含两个未知数的方程组，与「二元」相合。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：「二元」是数学或计算概念，菜单不能是二元的。"}, {"text": "歌词", "is_correct": false, "explanation": "语义：歌词是文字作品，不能用「二元」修饰，也与「列出」的数学语境不符。"}, {"text": "词汇", "is_correct": false, "explanation": "搭配：「二元」限定数学或计算对象，不能修饰词汇。"}], "explanations": {"方程组": "正确：二元方程组指含两个未知数的方程组，与「二元」相合。", "菜单": "语义：「二元」是数学或计算概念，菜单不能是二元的。", "歌词": "语义：歌词是文字作品，不能用「二元」修饰，也与「列出」的数学语境不符。", "词汇": "搭配：「二元」限定数学或计算对象，不能修饰词汇。"}, "sentence_index": 6, "correct_answer": "方程组"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题的方程组是 x=3。", "explanation": "这里应该用〈答案〉。方程组是一组方程，不是求出的结果，x=3 才是答案。"}, {"text": "这个方程组的解是 x>3。", "explanation": "这里应该用〈不等式〉。方程组的解是确定的数值，x>3 这样的取值范围属于不等式的解。"}, {"text": "程序里用方程组保存数据。", "explanation": "这里应该用〈数组〉。方程组是一组方程，不能用来保存数据。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12236, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "课堂上老师要我们解一张方程组。", "corrected_sentence": "课堂上老师要我们解一个方程组。", "error_description": "量词错误：「张」用于纸张、桌子等扁平物，方程组应说「个」或「组」，不能说「张」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12236, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这道题要先建立方程组们，然后求解。", "corrected_sentence": "这道题要先建立方程组，然后求解。", "error_description": "名词错误：「们」一般只用于指人，方程组是无生命的事物，不能加「们」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
