INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12238, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "求出方程、数学问题等的解。", "primary_collocate": null, "pronunciation": "qiú jiě", "ipa": "tɕʰjoʊ˧˥ tɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这些前沿技术的背后，是对纳维-斯托克斯方程组的深入求解，其非线性特性使得湍流建模至今仍是物理学界未完全攻克的难题。", "target_word": "求解", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "老师让我们求解这个方程。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道方程题很难求解。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用新方法求解了这个方程组。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先列出方程，再求解。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方程有两个根，要怎么求解呢？", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑可以很快求解复杂的方程。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们正在黑板前求解方程。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "求解这个不等式需要一点时间。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她已经求解过这类方程了。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "求解了", "label": "完成体"}, {"form": "求解过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "求出方程或数学问题的解", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24631489-7be5-43ad-b7ec-de458e1dff98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12238, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "求解", "is_correct": true, "explanation": "“深入求解”指对方程组做深入的求解工作，与“方程组”和“非线性特性”的语境一致。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”指创造新事物，方程组不是被发明的对象，“深入发明方程组”不成立。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“深入”一般不与“翻译”搭配，方程组也不需要翻译。"}, {"text": "测量", "is_correct": false, "explanation": "语义：“测量”针对可度量的物理量，方程组本身不能被测量，与句中语境矛盾。"}], "explanations": {"求解": "“深入求解”指对方程组做深入的求解工作，与“方程组”和“非线性特性”的语境一致。", "发明": "语义：“发明”指创造新事物，方程组不是被发明的对象，“深入发明方程组”不成立。", "翻译": "搭配：“深入”一般不与“翻译”搭配，方程组也不需要翻译。", "测量": "语义：“测量”针对可度量的物理量，方程组本身不能被测量，与句中语境矛盾。"}, "sentence_index": 0, "correct_answer": "求解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师当场求解了学生的疑问。", "explanation": "这里应该用〈解答〉。求解只用于方程、数学题等有确定答案的题目，学生的疑问要用〈解答〉。"}, {"text": "他花了很久，终于把那个绳结求解了。", "explanation": "这里应该用〈解开〉。求解指求数学题等的解，绳结要用〈解开〉。"}, {"text": "他认真求解了这篇文章。", "explanation": "这里应该用〈解读〉。求解只用于数学问题，文章的意思要用〈解读〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12238, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "求解", "is_correct": true, "explanation": "“求解”指求出方程的解，电脑很快求解复杂的方程，符合句意。"}, {"text": "喝", "is_correct": false, "explanation": "语义：方程是抽象的式子，不能被“喝”，与电脑的运算语境完全不符。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：方程是抽象的式子，不能被搬运，与电脑的运算功能不符。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：方程不能被点燃，句子与电脑运算的语境完全不符。"}], "explanations": {"求解": "“求解”指求出方程的解，电脑很快求解复杂的方程，符合句意。", "喝": "语义：方程是抽象的式子，不能被“喝”，与电脑的运算语境完全不符。", "搬运": "语义：方程是抽象的式子，不能被搬运，与电脑的运算功能不符。", "点燃": "语义：方程不能被点燃，句子与电脑运算的语境完全不符。"}, "sentence_index": 6, "correct_answer": "求解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师耐心地求解了这个概念。", "explanation": "这里应该用〈解释〉。求解用于方程、数学题，概念要用〈解释〉。"}, {"text": "消防员把被困的人求解出来了。", "explanation": "这里应该用〈解救〉。求解只用于数学问题，把被困的人救出来要用〈解救〉。"}, {"text": "政府终于求解了这项禁令。", "explanation": "这里应该用〈解除〉。求解用于数学问题，禁令要用〈解除〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12238, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他两个小时就求解了过这道题。", "corrected_sentence": "他两个小时就求解了这道题。", "error_description": "“求解了过”错，应为“求解了”。“了”和“过”不能同时用在同一个动词后面，这里只用“了”表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12238, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们正在黑板前认真求解过题目。", "corrected_sentence": "同学们正在黑板前认真求解题目。", "error_description": "“求解过”错，应为“求解”。“正在”表示动作正在进行，而“过”表示经历过的动作，两者不能搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
