INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12240, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指流体（如水流、气流）中不规则的、混乱的流动状态，常伴有漩涡和速度变化。", "primary_collocate": null, "pronunciation": "tuān liú", "ipa": "tʰwan˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "这些前沿技术的背后，是对纳维-斯托克斯方程组的深入求解，其非线性特性使得湍流的数值模拟至今仍是物理学界未完全攻克的难题。", "target_word": "湍流", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "飞机遇到湍流，开始上下晃动。", "target_word": "湍流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机穿过湍流时，乘客要系好安全带。", "target_word": "湍流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水在桥下形成了湍流。", "target_word": "湍流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湍流会让飞机剧烈颠簸。", "target_word": "湍流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用计算机模拟湍流。", "target_word": "湍流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水流速度越快，越容易出现湍流。", "target_word": "湍流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湍流中有很多不规则的漩涡。", "target_word": "湍流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海洋里的湍流会带走热量。", "target_word": "湍流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位研究者一直在研究湍流。", "target_word": "湍流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "股", "label": "量词"}], "register": "专业", "sense_fingerprint": "流体力学术语：流体不规则、混乱并带漩涡的流动状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7c84d0d-b658-4011-a3cd-9d3d112aea10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12240, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "湍流", "is_correct": true, "explanation": "正确：湍流是流体中不规则、混乱的流动，其数值模拟是流体力学的难题。"}, {"text": "食品", "is_correct": false, "explanation": "语义：食品与流体力学无关，「食品的数值模拟」无法对应「物理学界的难题」。"}, {"text": "诗歌", "is_correct": false, "explanation": "语域：诗歌属文学语体，不用于描述物理学中的数值模拟。"}, {"text": "爱情", "is_correct": false, "explanation": "语义：爱情不是流体运动，与「非线性特性」和物理学难题不相符。"}], "explanations": {"湍流": "正确：湍流是流体中不规则、混乱的流动，其数值模拟是流体力学的难题。", "食品": "语义：食品与流体力学无关，「食品的数值模拟」无法对应「物理学界的难题」。", "诗歌": "语域：诗歌属文学语体，不用于描述物理学中的数值模拟。", "爱情": "语义：爱情不是流体运动，与「非线性特性」和物理学难题不相符。"}, "sentence_index": 0, "correct_answer": "湍流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "湍流中心的水流很平稳。", "explanation": "这里应该用〈漩涡〉。漩涡中心常有相对平稳的水，湍流是不规则混乱的流动，没有稳定的中心。"}, {"text": "管道里的湍流速度很稳定。", "explanation": "这里应该用〈层流〉。层流速度稳定，湍流速度起伏不定，不能说稳定。"}, {"text": "河面上有一根湍流。", "explanation": "这里应该用〈股〉。「根」用于细长的条状物，湍流应用「股」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12240, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "湍流", "is_correct": true, "explanation": "正确：流速快时水流容易变得不规则，形成湍流。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：水流速度与冰块形成无关，「越快越容易出现冰块」不合事实。"}, {"text": "路线", "is_correct": false, "explanation": "搭配：「出现」多接现象或问题，不宜接路线这类路径名词。"}, {"text": "光线", "is_correct": false, "explanation": "语义：光线不是由水流速度引起的现象。"}], "explanations": {"湍流": "正确：流速快时水流容易变得不规则，形成湍流。", "冰块": "语义：水流速度与冰块形成无关，「越快越容易出现冰块」不合事实。", "路线": "搭配：「出现」多接现象或问题，不宜接路线这类路径名词。", "光线": "语义：光线不是由水流速度引起的现象。"}, "sentence_index": 6, "correct_answer": "湍流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海上的湍流有规律地起伏。", "explanation": "这里应该用〈波浪〉。湍流是不规则、混乱的流动，不能用「有规律地起伏」形容。"}, {"text": "这股湍流很平缓。", "explanation": "这里应该用〈水流〉。湍流混乱急促，不能用「平缓」形容。"}, {"text": "湖面上有一圈圈的湍流。", "explanation": "这里应该用〈涟漪〉。涟漪是水面的小波纹，湍流是混乱的流动，不呈一圈圈的形状。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12240, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "渡船刚出港就遇到一座湍流。", "corrected_sentence": "渡船刚出港就遇到一股湍流。", "error_description": "量词错误：湍流应用「股」，「座」用于山、桥、建筑等大型固定物，不能用于湍流。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12240, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究人员在水槽里观察到一颗湍流。", "corrected_sentence": "研究人员在水槽里观察到一股湍流。", "error_description": "量词错误：湍流应用「股」，「颗」用于小而圆的物体，不能用于湍流。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
