INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12241, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "建立模型，比如用数学或电脑做出一个东西的样子来研究。", "primary_collocate": null, "pronunciation": "jiàn mó", "ipa": "tɕjɛn˥˩ mɔ˧˥", "syllable_count": 2, "sentences": [{"text": "这些前沿技术的背后，是对纳维-斯托克斯方程组的深入求解，其非线性特性使得湍流建模至今仍是物理学界未完全攻克的难题。", "target_word": "建模", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "代理不仅执行任务，还能对自身决策过程进行反思性建模，通过多层级反馈回路调整目标函数。", "target_word": "建模", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他用电脑给新桥建模。", "target_word": "建模", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们先建模，再做实验。", "target_word": "建模", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师教我们怎么建模。", "target_word": "建模", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个软件可以帮你建模。", "target_word": "建模", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师正在给飞机建模。", "target_word": "建模", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生用数学方法给天气建模。", "target_word": "建模", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "建模以前，要先收集数据。", "target_word": "建模", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他建模用了三个小时。", "target_word": "建模", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "建模了", "label": "体标（了）"}, {"form": "建了模", "label": "离合形式"}, {"form": "建模型", "label": "复合词"}, {"form": "数学建模", "label": "复合词"}], "register": "书面", "sense_fingerprint": "用数学或电脑建立模型来研究", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c6fe7c9-33e8-4c2f-b2e6-ccbf82b54954') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12241, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "建模", "is_correct": true, "explanation": "“湍流建模”指用模型研究湍流，符合物理学界研究难题的语境。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”指做饭，“湍流烹饪”无法作为物理学界研究的对象。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”的对象是物品或空间，不能与“湍流”搭配。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清除脏物，与物理学中研究的湍流无关。"}], "explanations": {"建模": "“湍流建模”指用模型研究湍流，符合物理学界研究难题的语境。", "烹饪": "语义：“烹饪”指做饭，“湍流烹饪”无法作为物理学界研究的对象。", "装饰": "搭配：“装饰”的对象是物品或空间，不能与“湍流”搭配。", "打扫": "语义：“打扫”指清除脏物，与物理学中研究的湍流无关。"}, "sentence_index": 0, "correct_answer": "建模"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他建模了一场婚礼。", "explanation": "这里应该用〈策划〉。建模指建立模型来研究，筹办婚礼要用策划。"}, {"text": "孩子建模大人的动作，学得很快。", "explanation": "这里应该用〈模仿〉。建模指建立模型来研究，不能表示照着别人的动作学习。"}, {"text": "我们昨天建模了一顿晚饭。", "explanation": "这里应该用〈做〉。建模指建立模型或三维造型，做饭要用做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12241, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建模", "is_correct": true, "explanation": "“给飞机建模”指为飞机建立模型，符合句意。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”指给动物或人送食物，飞机不能被喂。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能与“飞机”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，“给飞机吃”不成立。"}], "explanations": {"建模": "“给飞机建模”指为飞机建立模型，符合句意。", "喂": "语义：“喂”指给动物或人送食物，飞机不能被喂。", "煮": "搭配：“煮”的对象是食物，不能与“飞机”搭配。", "吃": "搭配：“吃”的对象是食物，“给飞机吃”不成立。"}, "sentence_index": 6, "correct_answer": "建模"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工程师建模了三个小时的午饭。", "explanation": "这里应该用〈做〉。建模指建立模型或三维造型，做饭要用做。"}, {"text": "他建模了一晚上的作文。", "explanation": "这里应该用〈写〉。建模指建立模型，写作文要用写。"}, {"text": "他建模了一本小说。", "explanation": "这里应该用〈翻译〉。建模是建立模型来研究，把小说译成另一种语言要用翻译。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12241, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用电脑建模很仔细。", "corrected_sentence": "他用电脑建模得很仔细。", "error_description": "错误形式“建模很仔细”，正确形式“建模得很仔细”。补语“很仔细”需用结构助词“得”引出，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12241, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她给这座塔建模了过。", "corrected_sentence": "她给这座塔建模了。", "error_description": "错误形式“建模了过”。“了”和“过”不能叠用：表示完成用“了”，不再加“过”，应说“建模了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
