INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12246, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将分散的事物或部分组合成一个整体。", "primary_collocate": null, "pronunciation": "jí chéng", "ipa": "tɕi˧˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "现代风力涡轮机已集成智能控制系统：激光雷达预判风速变化，实时调节桨距角以优化转矩；数字孪生技术则构建虚拟机组模型，实现故障预测性维护。", "target_word": "集成", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "未来能源图景或将超越“发电”本身——建筑幕墙成为透明太阳能收集器，道路涂层集成压电发电单元，甚至人工光合作用系统直接将二氧化碳转化为燃料。", "target_word": "集成", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "值得注意的是，即便在自动驾驶与人工智能高度集成的现代客机中，空气动力学的基本物理规律依然不可违背。", "target_word": "集成", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这款手机集成了很多功能。", "target_word": "集成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师把三个模块集成在一起。", "target_word": "集成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件集成了地图和天气服务。", "target_word": "集成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新系统将各部门的数据集成起来。", "target_word": "集成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司负责把设备集成到平台上。", "target_word": "集成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小程序集成了支付功能。", "target_word": "集成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们想把旧系统和新系统集成。", "target_word": "集成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "集成了", "label": "体标（了）"}, {"form": "集成过", "label": "体标（过）"}, {"form": "集成电路", "label": "复合词"}, {"form": "系统集成", "label": "复合词"}], "register": "书面", "sense_fingerprint": "将分散的部分组合成整体（技术、系统）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c6fe7c9-33e8-4c2f-b2e6-ccbf82b54954') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12246, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "集成", "is_correct": true, "explanation": "正确答案：集成（jí chéng），指把分散的部分组合成一个整体。"}, {"text": "继承", "is_correct": false, "explanation": "声调不同：继承（jì chéng）第一音节为第四声，集成为第二声；意思是承接、传承。"}, {"text": "几成", "is_correct": false, "explanation": "声调不同：几成（jǐ chéng）第一音节为第三声，集成为第二声；意思是十分之几。"}, {"text": "急症", "is_correct": false, "explanation": "声母不同：急症（jí zhèng）第二音节为 zh，集成为 ch，且声调不同；意思是急性病。"}], "explanations": {"集成": "正确答案：集成（jí chéng），指把分散的部分组合成一个整体。", "继承": "声调不同：继承（jì chéng）第一音节为第四声，集成为第二声；意思是承接、传承。", "几成": "声调不同：几成（jǐ chéng）第一音节为第三声，集成为第二声；意思是十分之几。", "急症": "声母不同：急症（jí zhèng）第二音节为 zh，集成为 ch，且声调不同；意思是急性病。"}, "sentence_index": null, "correct_answer": "集成"}, "level_3": {"options": [{"text": "集成", "is_correct": true, "explanation": "正确：“集成”指把部件组合进系统，与“已…智能控制系统”的语境相合。"}, {"text": "焚烧", "is_correct": false, "explanation": "语义：“焚烧”是毁坏，与“智能控制系统”作为组成部分的语境不合。"}, {"text": "切断", "is_correct": false, "explanation": "语义：“切断”指割断或中止联系，与“已…智能控制系统”作为组成部分的意思相反。"}, {"text": "吞噬", "is_correct": false, "explanation": "语义：“吞噬”指吞食，与“智能控制系统”不能搭配，句意不通。"}], "explanations": {"集成": "正确：“集成”指把部件组合进系统，与“已…智能控制系统”的语境相合。", "焚烧": "语义：“焚烧”是毁坏，与“智能控制系统”作为组成部分的语境不合。", "切断": "语义：“切断”指割断或中止联系，与“已…智能控制系统”作为组成部分的意思相反。", "吞噬": "语义：“吞噬”指吞食，与“智能控制系统”不能搭配，句意不通。"}, "sentence_index": 0, "correct_answer": "集成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在海边集成贝壳。", "explanation": "这里应该用〈收集〉。集成是把零件合为整体，不指把分散的物品聚在一起。"}, {"text": "学校今年集成了三百名新生。", "explanation": "这里应该用〈招收〉。集成针对部件或功能，不能用于招收人员。"}, {"text": "同学们在操场集成。", "explanation": "这里应该用〈集合〉。“集合”指人或物聚在一起，“集成”指把部件组成整体，不说“同学们集成”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集成", "is_correct": true, "explanation": "正确：“集成”指把各部门的数据合为一体，与“新系统将…起来”的语境相合。"}, {"text": "粉碎", "is_correct": false, "explanation": "语义：“粉碎”是毁坏，与“新系统”把数据整合起来的意思相反。"}, {"text": "搞砸", "is_correct": false, "explanation": "语域：“搞砸”是口语，意为弄糟，不适合这段书面化的叙述。"}, {"text": "撕碎", "is_correct": false, "explanation": "语义：“撕碎”是撕成碎片，与把数据合为整体的意思相反。"}], "explanations": {"集成": "正确：“集成”指把各部门的数据合为一体，与“新系统将…起来”的语境相合。", "粉碎": "语义：“粉碎”是毁坏，与“新系统”把数据整合起来的意思相反。", "搞砸": "语域：“搞砸”是口语，意为弄糟，不适合这段书面化的叙述。", "撕碎": "语义：“撕碎”是撕成碎片，与把数据合为整体的意思相反。"}, "sentence_index": 6, "correct_answer": "集成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想把房间集成干净。", "explanation": "这里应该用〈收拾〉。集成是把部件组合为整体，不能说“集成干净”。"}, {"text": "妈妈每天集成三次饭。", "explanation": "这里应该用〈煮〉。集成指把零件合为整体，不用于烹饪做饭。"}, {"text": "他集成了一次晚会。", "explanation": "这里应该用〈组织〉。集成指把部件合为整体，不用于组织活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们把新旧系统起来集成了。", "corrected_sentence": "他们把新旧系统集成了。", "error_description": "错误形式“起来集成了”。“起来”作补语只能跟在动词之后，放在动词之前是错误的，应去掉，说“他们把新旧系统集成了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司已经集成了过这个系统。", "corrected_sentence": "我们公司已经集成过这个系统。", "error_description": "“过”表示经历，不能与“了”叠用；应说“集成过”，不说“集成了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
