INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12255, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16db58d5-d28a-4c23-980d-14b2cddee96a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12255, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "航行的物体偏离了原本的航线。", "primary_collocate": null, "pronunciation": "piān háng", "ipa": "pʰiɛn˥ xɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "长途航行中，哪怕只有很小的误差，船只也会慢慢偏航，远离原定路线。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雾中，客机偏航了二十公里。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机偏航后，飞行员马上调整方向。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大风把小船吹得偏航了。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这艘货船偏航，没有按原定航线走。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导航出了问题，飞机才会偏航。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无人机在强风中偏航，操作员及时把它拉了回来。", "target_word": "偏航", "complexity_tier": "T3", "furigana": "piān háng", "sentence_source": "generated"}, {"text": "船长发现船偏航了，马上下令转向。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机一偏航，雷达屏幕上就会报警。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太大，帆船常常偏航，很难直线前进。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "偏航了", "label": "体标（了）"}, {"form": "偏航过", "label": "体标（过）"}, {"form": "偏航角", "label": "复合词"}], "register": "书面", "sense_fingerprint": "飞机、船等偏离原定航线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963f0013-655e-4f45-a7f7-7aacd94fb341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12255, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偏航", "is_correct": true, "explanation": "正确：船只因误差慢慢偏离原定航线，即为偏航。"}, {"text": "充电", "is_correct": false, "explanation": "语义：“充电”是补充电能，与船只慢慢偏离航线无关。"}, {"text": "降落", "is_correct": false, "explanation": "语义：“降落”指飞机落地，船只不说降落，与句中偏离航线的意思不符。"}, {"text": "停靠", "is_correct": false, "explanation": "搭配：“停靠”指船只靠岸或停在站点，不能说船只慢慢停靠而远离原定路线。"}], "explanations": {"偏航": "正确：船只因误差慢慢偏离原定航线，即为偏航。", "充电": "语义：“充电”是补充电能，与船只慢慢偏离航线无关。", "降落": "语义：“降落”指飞机落地，船只不说降落，与句中偏离航线的意思不符。", "停靠": "搭配：“停靠”指船只靠岸或停在站点，不能说船只慢慢停靠而远离原定路线。"}, "sentence_index": 0, "correct_answer": "偏航"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "树叶在风中慢慢偏航到地上。", "explanation": "这里应该用〈飘落〉。偏航只指航行的船、飞机偏离航线，树叶随风落下应说飘落。"}, {"text": "这辆公交车在路上偏航了，司机赶紧停车。", "explanation": "这里应该用〈跑偏〉。偏航只用于航行的船只、飞机，公交车在路上走偏不说偏航。"}, {"text": "他在路上偏航，迷了方向。", "explanation": "这里应该用〈迷路〉。偏航只用于飞机、船只等航行器偏离航线，人走错路说迷路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16db58d5-d28a-4c23-980d-14b2cddee96a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12255, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偏航", "is_correct": true, "explanation": "正确：无人机被强风吹离航线，操作员及时纠正。"}, {"text": "充电", "is_correct": false, "explanation": "语义：“充电”与强风中偏离航线的情境无关。"}, {"text": "喷漆", "is_correct": false, "explanation": "语义：“喷漆”是给表面上色，与航向问题无关。"}, {"text": "降温", "is_correct": false, "explanation": "搭配：“降温”用于环境或物体的温度，不能说无人机在强风中降温。"}], "explanations": {"偏航": "正确：无人机被强风吹离航线，操作员及时纠正。", "充电": "语义：“充电”与强风中偏离航线的情境无关。", "喷漆": "语义：“喷漆”是给表面上色，与航向问题无关。", "降温": "搭配：“降温”用于环境或物体的温度，不能说无人机在强风中降温。"}, "sentence_index": 6, "correct_answer": "偏航"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "赛车在弯道上偏航，车身向内倾斜。", "explanation": "这里应该用〈转弯〉。偏航指航行器偏离航线，赛车过弯用转弯。"}, {"text": "货轮在港口偏航，等待卸货。", "explanation": "这里应该用〈停泊〉。偏航指航行中偏离航线，停在港口不说偏航。"}, {"text": "小狗跑丢了，偏航到了别的街区。", "explanation": "这里应该用〈跑错〉。偏航只用于航行器，小狗跑错路不说偏航。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16db58d5-d28a-4c23-980d-14b2cddee96a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12255, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "客机因为大雾偏航着二十公里，机长通知了乘客。", "corrected_sentence": "客机因为大雾偏航了二十公里，机长通知了乘客。", "error_description": "错误：“着”表示持续状态，描述已经发生的偏离；正确：“偏航了”，表示偏离已经完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16db58d5-d28a-4c23-980d-14b2cddee96a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12255, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大风把帆船吹地偏航了，船员赶紧收帆。", "corrected_sentence": "大风把帆船吹得偏航了，船员赶紧收帆。", "error_description": "错误：补语标记用了“地”；正确：“得”。“吹得偏航”中“得”引出补语，“地”只用于状语，不能接在动词后作补语标记。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16db58d5-d28a-4c23-980d-14b2cddee96a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
