INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12259, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "物体从空中向下落。", "primary_collocate": null, "pronunciation": "jiàng luò", "ipa": "tɕjaŋ⁵¹ lwo⁵¹", "syllable_count": 2, "sentences": [{"text": "飞机在不同飞行阶段（如起飞、巡航、降落）所面临的气动挑战各异，要求机翼形态（如襟翼与缝翼的展开）能够动态适应。", "target_word": "降落", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "飞机慢慢降落，轮子碰到了跑道。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞船降落在月球表面，航天员走了出来。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跳伞员从空中安全降落到草地上。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机降落前，空姐请大家坐好。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "返回舱降落在大海里，船马上过去接它。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直升机降落时，风把地上的草吹弯了。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无人机慢慢降落在桌子上。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气球在空中飘了很久，最后降落在山脚下。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太差，飞机不能在这里降落。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "降落了", "label": "体标"}, {"form": "降落过", "label": "体标"}, {"form": "降落伞", "label": "复合"}], "register": "通用", "sense_fingerprint": "飞机、飞船、跳伞者等从空中向下落到地面或水面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963f0013-655e-4f45-a7f7-7aacd94fb341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12259, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "降落", "is_correct": true, "explanation": "正确：“降落”是飞机从空中落到地面的阶段，与“起飞、巡航”并列。"}, {"text": "下潜", "is_correct": false, "explanation": "搭配：“下潜”用于潜水艇、潜水员，不用来说飞机的飞行阶段。"}, {"text": "停泊", "is_correct": false, "explanation": "搭配：“停泊”指船只停靠在水面，飞机不说停泊。"}, {"text": "沉没", "is_correct": false, "explanation": "语义：“沉没”指沉入水中，不是飞机的飞行阶段。"}], "explanations": {"降落": "正确：“降落”是飞机从空中落到地面的阶段，与“起飞、巡航”并列。", "下潜": "搭配：“下潜”用于潜水艇、潜水员，不用来说飞机的飞行阶段。", "停泊": "搭配：“停泊”指船只停靠在水面，飞机不说停泊。", "沉没": "语义：“沉没”指沉入水中，不是飞机的飞行阶段。"}, "sentence_index": 0, "correct_answer": "降落"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电梯降落到一楼。", "explanation": "这里应该用〈下降〉。降落指从空中落到地面，电梯垂直向下运行要说下降。"}, {"text": "轮船降落在码头。", "explanation": "这里应该用〈停靠〉。降落指从空中落向地面，船只靠岸要说停靠。"}, {"text": "他在比赛中降落了。", "explanation": "这里应该用〈落后〉。降落只表示从空中落下，比赛中处于劣势要说落后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16db58d5-d28a-4c23-980d-14b2cddee96a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12259, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降落", "is_correct": true, "explanation": "正确：直升机从空中落到地面，风把草吹弯，与“降落”的含义相符。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“吃饭”只用于人或动物，直升机不吃饭。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“唱歌”只用于人，直升机不能唱歌。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：“熄灭”指火或灯灭掉，与直升机的动作不符。"}], "explanations": {"降落": "正确：直升机从空中落到地面，风把草吹弯，与“降落”的含义相符。", "吃饭": "搭配：“吃饭”只用于人或动物，直升机不吃饭。", "唱歌": "搭配：“唱歌”只用于人，直升机不能唱歌。", "熄灭": "语义：“熄灭”指火或灯灭掉，与直升机的动作不符。"}, "sentence_index": 6, "correct_answer": "降落"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车在门口降落。", "explanation": "这里应该用〈停车〉。降落指从空中落到地面，车辆停下要说停车。"}, {"text": "火车明天降落在北京。", "explanation": "这里应该用〈抵达〉。降落指从空中落下，火车到站要说抵达。"}, {"text": "学生们下午就降落了。", "explanation": "这里应该用〈下课〉。降落指物体从空中向下落，学校结束上课要说下课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16db58d5-d28a-4c23-980d-14b2cddee96a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12259, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "直升机从屋顶降落的很慢。", "corrected_sentence": "直升机从屋顶降落得很慢。", "error_description": "错误：补语标记用了“的”（降落的很慢）；正确：“得”。“得”引出动词后的状态补语，“的”不能直接接在动词之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16db58d5-d28a-4c23-980d-14b2cddee96a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12259, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "飞机昨晚降落地很平稳，乘客都很安全。", "corrected_sentence": "飞机昨晚降落得很平稳，乘客都很安全。", "error_description": "错误：补语标记用了“地”（降落地很平稳）；正确：“得”。“地”是动词前的状语标记，动词后引出补语要用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16db58d5-d28a-4c23-980d-14b2cddee96a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
