INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12262, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "缝翼是飞机机翼前缘的一种可动翼面，在起飞和降落时伸出，增加升力，提高飞行安全性。", "primary_collocate": null, "pronunciation": "fèng yì", "ipa": "fɤŋ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "飞机在不同飞行阶段（如起飞、巡航、降落）所面临的气动挑战各异，要求机翼形态（如襟翼与缝翼的展开）能够动态适应。", "target_word": "缝翼", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "起飞时，缝翼从机翼前面伸出来。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "缝翼在机翼前缘，能增加升力。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "降落前，飞行员打开了缝翼。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "缝翼和襟翼都是机翼上的活动部分。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "缝翼伸出后，飞机能飞得更稳。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师发现左边的缝翼坏了。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机翼前缘的缝翼可以提高飞行安全性。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机慢慢降落，缝翼已经完全伸出了。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块缝翼是用轻金属做的。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一对缝翼", "label": "量词"}, {"form": "縫翼", "label": "繁体"}, {"form": "前缘缝翼", "label": "复合"}], "register": "专业", "sense_fingerprint": "机翼前缘可动翼面，起降时伸出增加升力，航空术语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecb8803a-6dd5-492a-a974-71a190af6a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12262, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "缝翼", "is_correct": true, "explanation": "正确答案。缝翼（fèng yì）指机翼前缘起降时伸出的可动翼面。"}, {"text": "风衣", "is_correct": false, "explanation": "两个音节声调都不同：fēng（第一声）与 fèng（第四声），yī（第一声）与 yì（第四声）。意思是风衣。"}, {"text": "缝衣", "is_correct": false, "explanation": "第一个音节相同，第二个音节 yī（第一声）与 yì（第四声）声调不同。意思是缝衣服。"}, {"text": "缝隙", "is_correct": false, "explanation": "第二个音节声母不同：xì 与 yì。意思是缝隙。"}, {"text": "风谊", "is_correct": false, "explanation": "声调混淆：fēng 与 fèng 只差声调（第一声与第四声），yì 相同。意思是朋友之间的情谊。"}, {"text": "凤仪", "is_correct": false, "explanation": "声调混淆：fèng 相同，yí 与 yì 只差声调（第二声与第四声）。意思是凤凰的仪态。"}], "explanations": {"缝翼": "正确答案。缝翼（fèng yì）指机翼前缘起降时伸出的可动翼面。", "风衣": "两个音节声调都不同：fēng（第一声）与 fèng（第四声），yī（第一声）与 yì（第四声）。意思是风衣。", "缝衣": "第一个音节相同，第二个音节 yī（第一声）与 yì（第四声）声调不同。意思是缝衣服。", "缝隙": "第二个音节声母不同：xì 与 yì。意思是缝隙。", "风谊": "声调混淆：fēng 与 fèng 只差声调（第一声与第四声），yì 相同。意思是朋友之间的情谊。", "凤仪": "声调混淆：fèng 相同，yí 与 yì 只差声调（第二声与第四声）。意思是凤凰的仪态。"}, "sentence_index": null, "correct_answer": "缝翼"}, "level_3": {"options": [{"text": "缝翼", "is_correct": true, "explanation": "缝翼与襟翼并列，都是起降时展开的可动翼面，符合“展开”的语境。"}, {"text": "机身", "is_correct": false, "explanation": "语义：机身是飞机的主体，不是可以展开的翼面。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“展开”不说窗户，窗户一般说打开。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李是装物品的箱包，不能作为可展开的部件。"}], "explanations": {"缝翼": "缝翼与襟翼并列，都是起降时展开的可动翼面，符合“展开”的语境。", "机身": "语义：机身是飞机的主体，不是可以展开的翼面。", "窗户": "搭配：“展开”不说窗户，窗户一般说打开。", "行李": "语义：行李是装物品的箱包，不能作为可展开的部件。"}, "sentence_index": 0, "correct_answer": "缝翼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "降落时，缝翼从机翼后缘放下来。", "explanation": "这里应该用〈襟翼〉。缝翼位于机翼前缘，襟翼才在后缘放下。"}, {"text": "飞机的翼尖装着缝翼，能够减少飞行阻力。", "explanation": "这里应该用〈翼梢小翼〉。翼梢小翼装在翼尖，用于减少阻力；缝翼位于机翼前缘，不装在翼尖。"}, {"text": "妈妈用缝翼把破衣服缝好了。", "explanation": "缝翼是飞机机翼前缘的可动部件，不是缝纫用具，这句把它当成了缝纫工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缝翼", "is_correct": true, "explanation": "正确答案。缝翼是有形的机械部件，“坏了”可以用来说它。"}, {"text": "感情", "is_correct": false, "explanation": "语义：感情是抽象的情绪，不是有形的东西，不能说坏了。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间是抽象概念，“左边的时间”与“坏了”都说不通。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“坏了”一般用于器物、机器，不用于名字。"}], "explanations": {"缝翼": "正确答案。缝翼是有形的机械部件，“坏了”可以用来说它。", "感情": "语义：感情是抽象的情绪，不是有形的东西，不能说坏了。", "时间": "语义：时间是抽象概念，“左边的时间”与“坏了”都说不通。", "名字": "搭配：“坏了”一般用于器物、机器，不用于名字。"}, "sentence_index": 6, "correct_answer": "缝翼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "飞机转弯时，靠缝翼来控制滚转。", "explanation": "这里应该用〈副翼〉。副翼负责控制滚转，缝翼只在起降时伸出、增加升力。"}, {"text": "飞机在地面转向时，靠缝翼来调整方向。", "explanation": "这里应该用〈方向舵〉。方向舵负责调整方向，缝翼不承担这个作用。"}, {"text": "飞机降落时，缝翼竖起来减速。", "explanation": "这里应该用〈扰流板〉。扰流板竖起来破坏气流、帮助减速；缝翼在前缘伸出以增加升力，不起减速作用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工程师修好了那台缝翼。", "corrected_sentence": "工程师修好了那对缝翼。", "error_description": "量词错误：“缝翼”是成对的机翼部件，应用量词“对”，说“那对缝翼”；“台”用于机器整体，不能用来数缝翼。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工程师把左边的缝翼修了好。", "corrected_sentence": "工程师把左边的缝翼修好了。", "error_description": "补语位置错误：“修好”是动补结构，“了”应放在句末，“修了好”应改为“修好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12263, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合拢", "is_correct": true, "explanation": "正确答案。“展开”由卷曲或合拢的状态变为张开，“合拢”与之相反。"}, {"text": "搬运", "is_correct": false, "explanation": "“搬运”指把东西从一处运到另一处，与“展开”没有相反关系。"}, {"text": "观看", "is_correct": false, "explanation": "“观看”指看，与“展开”没有反义关系。"}, {"text": "保存", "is_correct": false, "explanation": "“保存”指留存、收藏，与“展开”没有反义关系。"}], "correct_answer": "合拢", "explanations": {"合拢": "正确答案。“展开”由卷曲或合拢的状态变为张开，“合拢”与之相反。", "搬运": "“搬运”指把东西从一处运到另一处，与“展开”没有相反关系。", "观看": "“观看”指看，与“展开”没有反义关系。", "保存": "“保存”指留存、收藏，与“展开”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12263, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "折叠", "is_correct": true, "explanation": "正确答案。“折叠”是把展开的东西叠起来，与“展开”互为反义。"}, {"text": "清洗", "is_correct": false, "explanation": "“清洗”指洗干净，与“展开”没有反义关系。"}, {"text": "讲解", "is_correct": false, "explanation": "“讲解”指解释说明，与“展开”没有反义关系。"}, {"text": "运输", "is_correct": false, "explanation": "“运输”指把物品从一处运到另一处，与“展开”没有反义关系。"}], "correct_answer": "折叠", "explanations": {"折叠": "正确答案。“折叠”是把展开的东西叠起来，与“展开”互为反义。", "清洗": "“清洗”指洗干净，与“展开”没有反义关系。", "讲解": "“讲解”指解释说明，与“展开”没有反义关系。", "运输": "“运输”指把物品从一处运到另一处，与“展开”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12263, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "由卷曲或合拢的状态变为张开或铺开。", "primary_collocate": null, "pronunciation": "zhǎn kāi", "ipa": "ʈʂan˨˩˦ kʰaɪ˥˥", "syllable_count": 2, "sentences": [{"text": "他把地图展开了。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶慢慢展开那张旧报纸。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟展开翅膀飞走了。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把那幅画展开给大家看。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把毛巾展开晾在外面。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈展开信纸，读了起来。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他展开手里的纸，看了一眼。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，旗子就展开了。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这块布展开，放在桌子上。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把卷着的海报展开了。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "展开了", "label": "完成体"}, {"form": "展开着", "label": "持续体"}, {"form": "展开过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "把卷着、叠着的东西(纸、地图、翅膀)铺开或张开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecb8803a-6dd5-492a-a974-71a190af6a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12263, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "展开", "is_correct": true, "explanation": "正确答案。展开指把卷起或折叠的东西铺开，与“地图”搭配。"}, {"text": "安慰", "is_correct": false, "explanation": "语义：“安慰”的对象是人，不能用于地图。"}, {"text": "叹息", "is_correct": false, "explanation": "配价：“叹息”不及物，不能带“地图”作宾语。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：“咳嗽”不及物，也不能带“地图”作宾语。"}], "explanations": {"展开": "正确答案。展开指把卷起或折叠的东西铺开，与“地图”搭配。", "安慰": "语义：“安慰”的对象是人，不能用于地图。", "叹息": "配价：“叹息”不及物，不能带“地图”作宾语。", "咳嗽": "配价：“咳嗽”不及物，也不能带“地图”作宾语。"}, "sentence_index": 0, "correct_answer": "展开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一早就展开了眼睛。", "explanation": "这里应该用〈睁开〉。展开用于卷起、折叠的东西，睁眼要用睁开。"}, {"text": "他展开了衬衫的扣子。", "explanation": "这里应该用〈解开〉。扣子要说解开，展开不用于纽扣。"}, {"text": "他展开了房门，走了进去。", "explanation": "这里应该用〈打开〉。门要说打开，展开用于可以铺平的卷起、折叠之物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12263, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "展开", "is_correct": true, "explanation": "正确答案。“展开手里的纸”指把纸摊开来看，符合语境。"}, {"text": "思念", "is_correct": false, "explanation": "语义：“思念”的对象是人或往事，不能用于手里的纸。"}, {"text": "微笑", "is_correct": false, "explanation": "配价：“微笑”不带宾语，不能带“手里的纸”。"}, {"text": "叹气", "is_correct": false, "explanation": "配价：“叹气”不及物，不能带“手里的纸”作宾语。"}], "explanations": {"展开": "正确答案。“展开手里的纸”指把纸摊开来看，符合语境。", "思念": "语义：“思念”的对象是人或往事，不能用于手里的纸。", "微笑": "配价：“微笑”不带宾语，不能带“手里的纸”。", "叹气": "配价：“叹气”不及物，不能带“手里的纸”作宾语。"}, "sentence_index": 6, "correct_answer": "展开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他展开嘴，想说点什么。", "explanation": "这里应该用〈张开〉。展开指卷起或折叠的东西铺开，嘴要用张开。"}, {"text": "妈妈把橘子展开，分给大家。", "explanation": "这里应该用〈剥开〉。剥橘子要说剥开，展开用于纸张、布料等可以铺平的东西。"}, {"text": "妈妈展开锅盖看了看。", "explanation": "这里应该用〈掀开〉。掀锅盖要说掀开，展开不用于这个动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12263, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶把那张纸把展开了。", "corrected_sentence": "奶奶把那张纸展开了。", "error_description": "错误：“把”多用了一次。“把那张纸展开了”只需一个“把”，应删去多余的“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12263, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "帐篷展开了着，等待客人。", "corrected_sentence": "帐篷展开着，等待客人。", "error_description": "体标错误：“展开着”表示持续，“了”不能与“着”同用，应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
