INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12268, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指将内在的思想、情感或特质通过外在的形式或行为表现出来。", "primary_collocate": null, "pronunciation": "wài huà", "ipa": "wai̯˥˩ xu̯a˥˩", "syllable_count": 2, "sentences": [{"text": "由此观之，航空工程不仅是技术的集合体，更是人类对自然法则深刻理解的外化表现。", "target_word": "外化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他把心里的感动外化成了一首歌。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家用颜色把内心的痛苦外化出来。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好演员能把人物的性格外化为动作。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种文化精神外化为古老的建筑。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的善良外化为每一个小小的举动。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不会说话，只能把情绪外化成哭闹。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写日记是把想法外化的好办法。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的自信外化为一种从容的态度。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诗人把对故乡的思念外化为文字。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外化了", "label": "完成体"}], "register": "书面语", "sense_fingerprint": "把内在的思想、情感、特质通过外在形式或行为表现出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '115bc740-bf98-4386-b8ea-52b5ee7d6f17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12268, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "外化", "is_correct": true, "explanation": "正确：外化（wài huà）指把内在的思想、情感或特质表现到外部。"}, {"text": "外挂", "is_correct": false, "explanation": "h（huà）与 g（guà）声母不同，外挂指游戏或软件的插件，意思不同。"}, {"text": "外汇", "is_correct": false, "explanation": "huà 与 huì 韵母不同（a 与 i），外汇指不同国家货币之间的兑换。"}, {"text": "外患", "is_correct": false, "explanation": "huàn 比 huà 多了韵尾 n，外患指来自外部的祸患。"}], "explanations": {"外化": "正确：外化（wài huà）指把内在的思想、情感或特质表现到外部。", "外挂": "h（huà）与 g（guà）声母不同，外挂指游戏或软件的插件，意思不同。", "外汇": "huà 与 huì 韵母不同（a 与 i），外汇指不同国家货币之间的兑换。", "外患": "huàn 比 huà 多了韵尾 n，外患指来自外部的祸患。"}, "sentence_index": null, "correct_answer": "外化"}, "level_3": {"options": [{"text": "外化", "is_correct": true, "explanation": "正确：“外化表现”指内在的理解通过外显形式呈现出来，与“深刻理解”的内在性相符。"}, {"text": "无意识", "is_correct": false, "explanation": "语义：“无意识”指不自觉的状态，与“深刻理解”的自觉性相反，“无意识表现”句意矛盾。"}, {"text": "肤浅", "is_correct": false, "explanation": "语义：“肤浅”与“深刻理解”直接对立，句意自相矛盾。"}, {"text": "片面", "is_correct": false, "explanation": "搭配：“片面”多修饰“理解、看法”，不说“片面表现”，与“深刻理解”也互相矛盾。"}], "explanations": {"外化": "正确：“外化表现”指内在的理解通过外显形式呈现出来，与“深刻理解”的内在性相符。", "无意识": "语义：“无意识”指不自觉的状态，与“深刻理解”的自觉性相反，“无意识表现”句意矛盾。", "肤浅": "语义：“肤浅”与“深刻理解”直接对立，句意自相矛盾。", "片面": "搭配：“片面”多修饰“理解、看法”，不说“片面表现”，与“深刻理解”也互相矛盾。"}, "sentence_index": 0, "correct_answer": "外化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把书桌外化，然后搬到了客厅。", "explanation": "这里误把“外化”当成〈移动〉的意思，把实物挪到别处。“外化”只指把内在的思想、情感表现于外，书桌不属于这一范畴。"}, {"text": "他把那根木头外化成了一把椅子。", "explanation": "这里误把“外化”当成〈制作〉的意思。外化指把内在的思想、情感表现于外，木头加工成椅子不属于这一范畴。"}, {"text": "下雨后，他把地上的湿气外化出来。", "explanation": "这里误把“外化”当成〈散发〉的意思（湿气从地面散发出来）。“外化”指思想、情感由内向外表现，湿气是自然现象，不适用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12268, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "外化", "is_correct": true, "explanation": "正确：外化（wài huà）指把内在的思想、情感或特质表现到外部。"}, {"text": "外环", "is_correct": false, "explanation": "huán 与 huà 韵母不同（an 与 a），外环指城市外围的环形道路。"}, {"text": "坏话", "is_correct": false, "explanation": "huài 比 wài 多了声母 h，坏话指不好听的话，意思不同。"}, {"text": "怪话", "is_correct": false, "explanation": "guài 比 wài 多了声母 g，怪话指奇怪、不中听的话。"}], "explanations": {"外化": "正确：外化（wài huà）指把内在的思想、情感或特质表现到外部。", "外环": "huán 与 huà 韵母不同（an 与 a），外环指城市外围的环形道路。", "坏话": "huài 比 wài 多了声母 h，坏话指不好听的话，意思不同。", "怪话": "guài 比 wài 多了声母 g，怪话指奇怪、不中听的话。"}, "sentence_index": null, "correct_answer": "外化"}, "level_3": {"options": [{"text": "外化", "is_correct": true, "explanation": "正确：“外化成哭闹”表示情绪由内向外显露，与“只能”的语境相符。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：“隐藏”与“哭闹”相反，哭闹是把情绪显露出来。"}, {"text": "压抑", "is_correct": false, "explanation": "搭配：“压抑”指压制，不能以“哭闹”作为结果，搭配不当。"}, {"text": "掩盖", "is_correct": false, "explanation": "语义：“掩盖”与“哭闹”的显露方向相反，句意矛盾。"}], "explanations": {"外化": "正确：“外化成哭闹”表示情绪由内向外显露，与“只能”的语境相符。", "隐藏": "语义：“隐藏”与“哭闹”相反，哭闹是把情绪显露出来。", "压抑": "搭配：“压抑”指压制，不能以“哭闹”作为结果，搭配不当。", "掩盖": "语义：“掩盖”与“哭闹”的显露方向相反，句意矛盾。"}, "sentence_index": 6, "correct_answer": "外化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把文字外化为对故乡的思念。", "explanation": "这里误把“外化”当成〈内化〉的意思，方向说反了。“外化”是由内向外表现，而这句是从外在的文字转为内在的思念。"}, {"text": "他把对故乡的思念外化在心里，从不说出口。", "explanation": "这里误把“外化”当成〈隐藏〉的意思（藏在心里）。“外化”是把内在的东西表现于外，与“在心里”“从不说出口”相矛盾。"}, {"text": "他把弟弟外化成了一个玩具。", "explanation": "这里误把“外化”当成〈变成〉的意思，把人说成了玩具。“外化”的对象是思想、情感等内在的东西，不能用于指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把心里的愤怒被外化出来了。", "corrected_sentence": "她把心里的愤怒外化出来了。", "error_description": "错误：“把”与“被”同用，构成“把……被……”的双重标记，应删去“被”，写作“她把心里的愤怒外化出来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的委屈很快外化了成眼泪。", "corrected_sentence": "她的委屈很快外化成了眼泪。", "error_description": "“了”的位置错误：完成体“了”应放在补语“成”之后，正确说法是“外化成了”，“外化了成”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12269, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12269, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12269, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人或事物在活动中显示出来的行为、态度或成绩。", "primary_collocate": null, "pronunciation": "biǎo xiàn", "ipa": "piɑʊ˨˩˦ ɕiɛn˥˩", "syllable_count": 2, "sentences": [{"text": "期末考试结束后，老师认真地评价了每个人的表现。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在舞台上的表现很自然。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天在课上的表现很好。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师夸她这次考试的表现不错。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在学校的表现让老师很满意。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她最近在工作中的表现越来越好。", "target_word": "表现", "complexity_tier": "T3", "furigana": "tā zuìjìn zài gōngzuò zhōng de biǎoxiàn yuè lái yuè hǎo", "sentence_source": "generated"}, {"text": "比赛中，他的表现让大家很吃惊。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的好表现得到了经理的表扬。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱帮助别人是善良的表现。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你最近的表现很让我放心。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "表现力", "label": "复合词"}, {"form": "表現", "label": "繁体"}], "register": "中性", "sense_fingerprint": "表现:名词:人或事物在活动中显示出的行为、态度或成绩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68807ff3-eb58-4d1c-ba43-2ad750765589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12269, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "表现", "is_correct": true, "explanation": "正确：表现 biǎo xiàn，指人或事物在活动中显示出的行为、态度或成绩。"}, {"text": "表面", "is_correct": false, "explanation": "表面 biǎomiàn 与 表现 biǎoxiàn 只有第二音节声母不同（m 与 x），意思是物体的外层。"}, {"text": "标线", "is_correct": false, "explanation": "标线 biāoxiàn 与 表现 biǎoxiàn 第一音节声调不同（第一声与第三声），意思是道路上的标记线。"}, {"text": "表象", "is_correct": false, "explanation": "表象 biǎoxiàng 与 表现 biǎoxiàn 只有第二音节韵母不同（ang 与 an），意思是事物表面的现象。"}], "explanations": {"表现": "正确：表现 biǎo xiàn，指人或事物在活动中显示出的行为、态度或成绩。", "表面": "表面 biǎomiàn 与 表现 biǎoxiàn 只有第二音节声母不同（m 与 x），意思是物体的外层。", "标线": "标线 biāoxiàn 与 表现 biǎoxiàn 第一音节声调不同（第一声与第三声），意思是道路上的标记线。", "表象": "表象 biǎoxiàng 与 表现 biǎoxiàn 只有第二音节韵母不同（ang 与 an），意思是事物表面的现象。"}, "sentence_index": null, "correct_answer": "表现"}, "level_3": {"options": [{"text": "表现", "is_correct": true, "explanation": "正确：“评价了每个人的表现”指人在考试中显示出的行为或成绩，这里应填“表现”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然状况，不是人在考试中显示出的行为或成绩，“评价天气”句意不通。"}, {"text": "门票", "is_correct": false, "explanation": "语义：门票是入场凭证，与人的表现无关，“评价门票”句意不通。"}, {"text": "墙壁", "is_correct": false, "explanation": "语义：墙壁是建筑部件，与人的表现无关，“评价墙壁”句意不通。"}], "explanations": {"表现": "正确：“评价了每个人的表现”指人在考试中显示出的行为或成绩，这里应填“表现”。", "天气": "语义：天气是自然状况，不是人在考试中显示出的行为或成绩，“评价天气”句意不通。", "门票": "语义：门票是入场凭证，与人的表现无关，“评价门票”句意不通。", "墙壁": "语义：墙壁是建筑部件，与人的表现无关，“评价墙壁”句意不通。"}, "sentence_index": 0, "correct_answer": "表现"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师当众表现了他。", "explanation": "这里应该用〈表扬〉。当众赞许某人要说“表扬”，表现指人或事物在活动中显示出的行为、态度或成绩，不表示赞扬别人。"}, {"text": "他向老师表现了原因。", "explanation": "这里应该用〈解释〉。说明原因要说“解释”，表现不表示说明道理。"}, {"text": "桌子的表现很光滑。", "explanation": "这里应该用〈表面〉。形容物体外层光滑要说“表面”，表现不能指物体的外层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12269, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表现", "is_correct": true, "explanation": "正确：“比赛中，他的表现让大家很吃惊”中，表现指他在比赛中显示出的行为或成绩。"}, {"text": "轮胎", "is_correct": false, "explanation": "语义：轮胎是车辆部件，与人在比赛中显示的行为或成绩无关，“他的轮胎让大家很吃惊”句意不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，与比赛中的行为或成绩无关，“他的冰箱让大家很吃惊”句意不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁用具，与比赛中的行为或成绩无关，“他的钥匙让大家很吃惊”句意不通。"}], "explanations": {"表现": "正确：“比赛中，他的表现让大家很吃惊”中，表现指他在比赛中显示出的行为或成绩。", "轮胎": "语义：轮胎是车辆部件，与人在比赛中显示的行为或成绩无关，“他的轮胎让大家很吃惊”句意不通。", "冰箱": "语义：冰箱是家电，与比赛中的行为或成绩无关，“他的冰箱让大家很吃惊”句意不通。", "钥匙": "语义：钥匙是开锁用具，与比赛中的行为或成绩无关，“他的钥匙让大家很吃惊”句意不通。"}, "sentence_index": 6, "correct_answer": "表现"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的表现很苗条。", "explanation": "这里应该用〈身材〉。形容体型要说“身材”，表现指行为、态度或成绩，不能形容人的体型。"}, {"text": "这块蛋糕的表现很甜。", "explanation": "这里应该用〈味道〉。形容食物的甜要说“味道”，表现不能用来描述食物的味道。"}, {"text": "这朵花的表现很香。", "explanation": "这里应该用〈气味〉。形容花的香要说“气味”，表现不能用来描述气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12269, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次演出中，他的一只表现很精彩。", "corrected_sentence": "这次演出中，他的一次表现很精彩。", "error_description": "量词错误：“表现”作名词时应用量词“次”，“只”只用于动物等个体，不能用来计量表现。正确应为“一次表现”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12269, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子的表现的很稳定，大家都很放心。", "corrected_sentence": "这个孩子的表现很稳定，大家都很放心。", "error_description": "多出“的”：“表现”后直接接谓语“很稳定”，不需要“的”。“这个孩子的表现的很稳定”应删去“表现”后的“的”，正确为“这个孩子的表现很稳定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12270, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12270, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "动荡", "is_correct": true, "explanation": "正确：“动荡”指局势不安定，与“平稳”构成反义，可用于句中的“局势”。"}, {"text": "高兴", "is_correct": false, "explanation": "高兴形容心里愉快，与“平稳”没有反义关系，句中说的是局势。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线充足或颜色鲜亮，与“平稳”不构成反义。"}, {"text": "清爽", "is_correct": false, "explanation": "清爽形容舒适、干净的感觉，与“平稳”不构成反义。"}], "correct_answer": "动荡", "explanations": {"动荡": "正确：“动荡”指局势不安定，与“平稳”构成反义，可用于句中的“局势”。", "高兴": "高兴形容心里愉快，与“平稳”没有反义关系，句中说的是局势。", "明亮": "明亮形容光线充足或颜色鲜亮，与“平稳”不构成反义。", "清爽": "清爽形容舒适、干净的感觉，与“平稳”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12270, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指物体或状态稳定、不晃动；也可形容局势、心情等平静、没有波动。", "primary_collocate": null, "pronunciation": "píng wěn", "ipa": "pʰiŋ˧˥ wən˨˩˦", "syllable_count": 2, "sentences": [{"text": "每一次平稳起降，都是对物理定律严谨遵循的结果，也彰显了工程智慧在复杂系统中实现可控性的卓越能力。", "target_word": "平稳", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "飞机在高空飞得很平稳。", "target_word": "平稳", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火车开得很平稳，我在车上睡着了。", "target_word": "平稳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听完音乐，她的心情慢慢平稳了。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船在海上走得很平稳，没有一点晃动。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几年，城市的物价一直很平稳。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把杯子平稳地放在桌子上。", "target_word": "平稳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，病人的呼吸已经平稳了。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑自行车时，要让车身保持平稳。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家的局势终于平稳下来了。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "物体运行稳定不晃动；局势、心情、数值平静无波动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4770717-0209-4e9c-bf03-9225dfd413b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12270, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平稳", "is_correct": true, "explanation": "正确：“平稳”形容飞机起降时不晃动，与句中“严谨遵循物理定律”的意思一致。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，不能用来形容飞机起降的状态。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面喧哗，与起降时稳定的状态不符。"}, {"text": "甜美", "is_correct": false, "explanation": "搭配：“甜美”多形容味道、声音或面容，不能修饰“起降”。"}], "explanations": {"平稳": "正确：“平稳”形容飞机起降时不晃动，与句中“严谨遵循物理定律”的意思一致。", "清脆": "语义：“清脆”形容声音，不能用来形容飞机起降的状态。", "热闹": "语义：“热闹”形容场面喧哗，与起降时稳定的状态不符。", "甜美": "搭配：“甜美”多形容味道、声音或面容，不能修饰“起降”。"}, "sentence_index": 0, "correct_answer": "平稳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "图书馆里很平稳，大家都在看书。", "explanation": "这里应该用〈安静〉。“平稳”说的是不晃动或没有波动，图书馆里没有声音应说“安静”。"}, {"text": "街上很平稳，大家都在买东西。", "explanation": "这里应该用〈热闹〉。“平稳”说的是没有波动，人多、声音大的景象应说“热闹”。"}, {"text": "这排树的颜色很平稳，看起来很好看。", "explanation": "这里应该用〈均匀〉。“平稳”说的是不晃动或没有波动，颜色的一致应说“均匀”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12270, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平稳", "is_correct": true, "explanation": "正确：“平稳地放”说放置时杯子不晃动，符合句意。"}, {"text": "热烈", "is_correct": false, "explanation": "语义：“热烈”形容情绪或场面高涨，不能用来形容放置杯子的动作。"}, {"text": "腼腆", "is_correct": false, "explanation": "语义：“腼腆”形容人的性格，杯子不能腼腆地放在桌上。"}, {"text": "丰盛", "is_correct": false, "explanation": "搭配：“丰盛”修饰饭菜，不能修饰“放”这个动作。"}], "explanations": {"平稳": "正确：“平稳地放”说放置时杯子不晃动，符合句意。", "热烈": "语义：“热烈”形容情绪或场面高涨，不能用来形容放置杯子的动作。", "腼腆": "语义：“腼腆”形容人的性格，杯子不能腼腆地放在桌上。", "丰盛": "搭配：“丰盛”修饰饭菜，不能修饰“放”这个动作。"}, "sentence_index": 6, "correct_answer": "平稳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天天空平稳，万里无云。", "explanation": "这里应该用〈晴朗〉。“平稳”说的是状态没有波动，天空的样子应说“晴朗”。"}, {"text": "这间屋子的味道很平稳，闻起来很舒服。", "explanation": "这里应该用〈清新〉。“平稳”说的是不晃动或没有波动，气味的清爽应说“清新”。"}, {"text": "今天的晚饭很平稳，桌上摆满了菜。", "explanation": "这里应该用〈丰盛〉。“平稳”说的是没有波动，饭菜的种类和数量多应说“丰盛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖面终于平稳出来了。", "corrected_sentence": "湖面终于平稳下来了。", "error_description": "补语错误：表示状态变得平稳应用趋向补语「下来」，应说「平稳下来」，「平稳出来」不符合说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆车开地很平稳。", "corrected_sentence": "这辆车开得很平稳。", "error_description": "结构助词错误：动词「开」后接补语，结构助词应用「得」，应说「开得很平稳」，不能用「地」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
