INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12271, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指飞机起飞和降落的过程。", "primary_collocate": null, "pronunciation": "qǐ jiàng", "ipa": "t͡ɕʰi˨˩˦ t͡ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "每一次平稳起降，都是对物理定律严谨遵循的结果，也彰显了工程智慧在复杂系统中实现可控性的卓越能力。", "target_word": "起降", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个机场每天有上百次飞机起降。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雾天气，飞机起降会受到影响。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员正在练习夜间起降。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条跑道是供飞机起降的。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下大雪，今天机场暂停了起降。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小型飞机起降不需要很长的跑道。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太大时，飞机起降很危险。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在塔台指挥飞机起降。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座岛上的机场只能起降小飞机。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "起降了", "label": "完成体"}], "register": "书面语", "sense_fingerprint": "飞机起飞和降落的整个过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '115bc740-bf98-4386-b8ea-52b5ee7d6f17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12271, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起降", "is_correct": true, "explanation": "正确：“平稳起降”指飞机平稳地起飞和降落，与“可控性”的语境相符。"}, {"text": "颠簸", "is_correct": false, "explanation": "语义：“颠簸”与“平稳”相反，句意自相矛盾。"}, {"text": "失控", "is_correct": false, "explanation": "语义：“失控”与“可控性”相反，与“严谨遵循”的语境矛盾。"}, {"text": "坠落", "is_correct": false, "explanation": "搭配：“平稳”不修饰“坠落”，“平稳坠落”自相矛盾。"}], "explanations": {"起降": "正确：“平稳起降”指飞机平稳地起飞和降落，与“可控性”的语境相符。", "颠簸": "语义：“颠簸”与“平稳”相反，句意自相矛盾。", "失控": "语义：“失控”与“可控性”相反，与“严谨遵循”的语境矛盾。", "坠落": "搭配：“平稳”不修饰“坠落”，“平稳坠落”自相矛盾。"}, "sentence_index": 0, "correct_answer": "起降"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天骑自行车练习起降。", "explanation": "这里误把“起降”当成〈起落〉的意思（车轮上下起落）。“起降”专指飞机的起飞和降落，自行车不能起降。"}, {"text": "这个湖的水位每天都在起降。", "explanation": "这里误把“起降”当成〈涨落〉的意思（水位的上下变化）。“起降”专指飞机的起飞和降落，不能用于水位。"}, {"text": "电梯每天在楼层之间起降。", "explanation": "这里应该用〈升降〉。升降可用于电梯、温度、水位等，起降专指飞机的起飞和降落。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12271, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起降", "is_correct": true, "explanation": "正确：小型飞机的起飞和降落需要跑道，句意成立。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：“喂养”的对象是动物或婴幼儿，不能用于飞机，句意不通。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指转换语言，与飞机的跑道需求无关，句意不通。"}, {"text": "哭泣", "is_correct": false, "explanation": "搭配：“飞机哭泣”不是合理的搭配，飞机不会哭泣，与句意无关。"}], "explanations": {"起降": "正确：小型飞机的起飞和降落需要跑道，句意成立。", "喂养": "搭配：“喂养”的对象是动物或婴幼儿，不能用于飞机，句意不通。", "翻译": "语义：“翻译”指转换语言，与飞机的跑道需求无关，句意不通。", "哭泣": "搭配：“飞机哭泣”不是合理的搭配，飞机不会哭泣，与句意无关。"}, "sentence_index": 6, "correct_answer": "起降"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月的物价又起降了一次。", "explanation": "“起降”只指飞机的起飞和降落，物价的涨落不能说“起降”。"}, {"text": "他的情绪在这座岛上起降不定。", "explanation": "“起降”不用于情绪的起伏，情绪的变化不能用“起降”。"}, {"text": "这座岛上的机场只能起降一座大楼。", "explanation": "这里误把“起降”当成〈吊运〉的意思（把大楼吊起、放下）。“起降”专指飞机的起飞和降落，大楼不是飞机，不能起降。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12271, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那架飞机今天在这里起降的。", "corrected_sentence": "那架飞机今天在这里起降了。", "error_description": "助词错误：完成体“了”应放在“起降”之后，这里把“了”换成了“的”。“起降的”后面没有中心语，句子不完整，应说“那架飞机今天在这里起降了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12271, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小型飞机在这里安全地起降地。", "corrected_sentence": "小型飞机在这里安全地起降。", "error_description": "结构错误：“地”用来把修饰语连到动词上，只能接在修饰成分之后，不能接在动词“起降”之后；“起降地”不成词，整句不通。状语“安全地”应保留在动词前，正确说法是“安全地起降”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12272, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "马虎", "is_correct": true, "explanation": "反义：「马虎」指做事粗略、不细致，与「严谨」周密相反。"}, {"text": "遥远", "is_correct": false, "explanation": "与「严谨」没有反义关系，形容距离长。"}, {"text": "热烈", "is_correct": false, "explanation": "与「严谨」没有反义关系，形容情绪高涨。"}, {"text": "简单", "is_correct": false, "explanation": "与「严谨」没有反义关系，形容不复杂。"}], "correct_answer": "马虎", "explanations": {"马虎": "反义：「马虎」指做事粗略、不细致，与「严谨」周密相反。", "遥远": "与「严谨」没有反义关系，形容距离长。", "热烈": "与「严谨」没有反义关系，形容情绪高涨。", "简单": "与「严谨」没有反义关系，形容不复杂。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12272, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "草率", "is_correct": true, "explanation": "反义：「草率」指做事随便、不周密，与「严谨」相反。"}, {"text": "灵巧", "is_correct": false, "explanation": "与「严谨」没有反义关系，形容动作或手艺灵活。"}, {"text": "沉重", "is_correct": false, "explanation": "与「严谨」没有反义关系，形容分量大或心情压抑。"}, {"text": "响亮", "is_correct": false, "explanation": "与「严谨」没有反义关系，形容声音洪亮。"}], "correct_answer": "草率", "explanations": {"草率": "反义：「草率」指做事随便、不周密，与「严谨」相反。", "灵巧": "与「严谨」没有反义关系，形容动作或手艺灵活。", "沉重": "与「严谨」没有反义关系，形容分量大或心情压抑。", "响亮": "与「严谨」没有反义关系，形容声音洪亮。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12272, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容态度严肃谨慎，做事细致周密，没有疏漏。", "primary_collocate": null, "pronunciation": "yán jǐn", "ipa": "jɛn˧˥ tɕin˨˩˦", "syllable_count": 2, "sentences": [{"text": "每一次平稳起降，都是对物理定律严谨遵循的结果，也彰显了工程智慧在复杂系统中实现可控性的卓越能力。", "target_word": "严谨", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "王老师做事很严谨，从不出错。", "target_word": "严谨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她处理这件事很严谨，每一步都认真考虑。", "target_word": "严谨", "complexity_tier": "T3", "furigana": "tā chǔlǐ zhè jiàn shì hěn yánjǐn, měi yí bù dōu rènzhēn kǎolǜ", "sentence_source": "generated"}, {"text": "医生检查得很严谨，一点问题也没放过。", "target_word": "严谨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对数据的态度十分严谨。", "target_word": "严谨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学研究需要严谨的态度。", "target_word": "严谨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位律师说话严谨，每个字都想过。", "target_word": "严谨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师严谨地检查了每一个零件。", "target_word": "严谨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他核对每一笔账都非常严谨。", "target_word": "严谨", "complexity_tier": "T3", "furigana": "tā héduì měi yì bǐ zhàng dōu fēicháng yánjǐn", "sentence_source": "generated"}, {"text": "德国人给我的印象是工作严谨。", "target_word": "严谨", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "态度严肃谨慎，做事、文章、论证周密无疏漏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4770717-0209-4e9c-bf03-9225dfd413b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12272, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "严谨", "is_correct": true, "explanation": "严谨：严格周密地遵循规律，与「物理定律」「结果」的语境相符，是唯一能填入空位的词。"}, {"text": "松散", "is_correct": false, "explanation": "语义：松散指结构不紧凑、约束少，与「严格遵循物理定律」的意思相反，读来不通。"}, {"text": "随意", "is_correct": false, "explanation": "搭配：「遵循」的对象是规律，「随意」不能修饰对规律的遵循。"}, {"text": "草率", "is_correct": false, "explanation": "语义：草率指做事粗疏、不周密，与「卓越能力」及严格遵循的语境相反。"}], "explanations": {"严谨": "严谨：严格周密地遵循规律，与「物理定律」「结果」的语境相符，是唯一能填入空位的词。", "松散": "语义：松散指结构不紧凑、约束少，与「严格遵循物理定律」的意思相反，读来不通。", "随意": "搭配：「遵循」的对象是规律，「随意」不能修饰对规律的遵循。", "草率": "语义：草率指做事粗疏、不周密，与「卓越能力」及严格遵循的语境相反。"}, "sentence_index": 0, "correct_answer": "严谨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋楼的门窗很严谨，一丝风都透不进来。", "explanation": "这里应该用〈严密〉。严密形容物体封闭、没有缝隙；严谨形容人做事认真细致，不用于门窗。"}, {"text": "他的表情很严谨。", "explanation": "这里应该用〈严肃〉。严肃形容表情、气氛；严谨形容做事周密，不形容表情。"}, {"text": "他的声音很严谨。", "explanation": "这里应该用〈严厉〉。严厉形容言语、神情的苛刻；严谨形容做事周密，不用于描述声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12272, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "严谨", "is_correct": true, "explanation": "严谨：形容说话周密、字斟句酌，与「每个字都想过」的语境相符。"}, {"text": "懒散", "is_correct": false, "explanation": "语义：懒散指松懈、不认真，与「每个字都想过」矛盾。"}, {"text": "粗心", "is_correct": false, "explanation": "搭配：「粗心」多修饰人或做事，不说「说话粗心」，且与「每个字都想过」矛盾。"}, {"text": "轻率", "is_correct": false, "explanation": "语义：轻率指随便、不慎重，与「每个字都想过」矛盾。"}], "explanations": {"严谨": "严谨：形容说话周密、字斟句酌，与「每个字都想过」的语境相符。", "懒散": "语义：懒散指松懈、不认真，与「每个字都想过」矛盾。", "粗心": "搭配：「粗心」多修饰人或做事，不说「说话粗心」，且与「每个字都想过」矛盾。", "轻率": "语义：轻率指随便、不慎重，与「每个字都想过」矛盾。"}, "sentence_index": 6, "correct_answer": "严谨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对客人照顾得很严谨。", "explanation": "这里应该用〈周到〉。周到形容照顾、服务的细致；严谨形容做事、治学的周密，不用于照顾别人。"}, {"text": "他对朋友很严谨。", "explanation": "这里应该用〈严格〉。严格形容对人、对要求的苛刻；严谨形容做事周密，不用于描述对朋友的相处。"}, {"text": "他明知有危险，仍然冲进了火场，非常严谨。", "explanation": "这里应该用〈勇敢〉。勇敢形容不怕危险的品质和行动；严谨形容做事周密，不用于描述冲进火场的胆量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她写报告写地很严谨，没有错字。", "corrected_sentence": "她写报告写得很严谨，没有错字。", "error_description": "「写地很严谨」应为「写得很严谨」：「严谨」作动词「写」的程度补语，补语前要用「得」，「地」只用于状语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位医生是个严谨地人，诊断从没失误。", "corrected_sentence": "这位医生是个严谨的人，诊断从没失误。", "error_description": "「严谨地人」应为「严谨的人」：「严谨」修饰名词「人」作定语，要用「的」，「地」只修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
