INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12273, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12273, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指事物或特点表现得非常清楚，使人容易看见或了解。", "primary_collocate": null, "pronunciation": "zhāng xiǎn", "ipa": "ʈ͡ʂɑŋ˥ ɕjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "每一次平稳起降，都是对物理定律严谨遵循的结果，也彰显了工程智慧在复杂系统中实现可控性的卓越能力。", "target_word": "彰显", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这件礼服彰显了她的好品味。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古城的老街彰显着历史的魅力。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的善良在小事中彰显出来。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色的旗袍彰显了东方的美。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛彰显了球队的实力。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "简单的设计彰显出品牌的个性。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "困难面前，最能彰显一个人的品格。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宏伟的大楼彰显了城市的经济实力。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些作品彰显了作者的才华。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "彰显了", "label": "完成体"}, {"form": "彰显着", "label": "持续体"}], "register": "书面语", "sense_fingerprint": "事物或特点表现得十分清楚，让人容易看出或了解", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '115bc740-bf98-4386-b8ea-52b5ee7d6f17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12273, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "彰显", "is_correct": true, "explanation": "正确：“彰显”表示使工程智慧的卓越能力清楚地表现出来，与“也……了”顺承展示优点的语境相合。"}, {"text": "损害", "is_correct": false, "explanation": "语义：“损害”指伤害、破坏，与“严谨遵循的结果”和“卓越能力”的褒义语境相反。"}, {"text": "掩饰", "is_correct": false, "explanation": "搭配：“掩饰”多接感情、错误、缺点，不说掩饰工程智慧的卓越能力。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：“隐瞒”指刻意不让人知道，与句中“也……了”表示展示优点的语义相反。"}], "explanations": {"彰显": "正确：“彰显”表示使工程智慧的卓越能力清楚地表现出来，与“也……了”顺承展示优点的语境相合。", "损害": "语义：“损害”指伤害、破坏，与“严谨遵循的结果”和“卓越能力”的褒义语境相反。", "掩饰": "搭配：“掩饰”多接感情、错误、缺点，不说掩饰工程智慧的卓越能力。", "隐瞒": "语义：“隐瞒”指刻意不让人知道，与句中“也……了”表示展示优点的语义相反。"}, "sentence_index": 0, "correct_answer": "彰显"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这束花把香味彰显得无影无踪。", "explanation": "这里误用“彰显”的“清楚呈现”义：香味无影无踪与“清楚呈现”矛盾，句意不通。"}, {"text": "厚厚的云彰显了月亮的光芒。", "explanation": "这里应该用〈掩盖〉。彰显是使事物明显地呈现，云层遮住月光要用掩盖，两者意思相反。"}, {"text": "这次实验彰显了问题的原因，却把它藏得严严实实。", "explanation": "“彰显”使原因清楚呈现，与后文“藏得严严实实”互相矛盾，句意不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12273, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "彰显", "is_correct": true, "explanation": "正确：“彰显”表示使品牌个性清楚地显现，与“简单的设计”的语境相合，“出”作结果补语。"}, {"text": "挤出", "is_correct": false, "explanation": "语义：“挤出”指用力使东西从狭小处出来，用于抽象的设计个性不合。"}, {"text": "推出", "is_correct": false, "explanation": "搭配：“推出”多接产品、服务、节目，不说“推出品牌的个性”。"}, {"text": "冒出", "is_correct": false, "explanation": "语义：“冒出”指突然出现，多用于烟、汗、念头，与经过设计体现个性的语境不合。"}], "explanations": {"彰显": "正确：“彰显”表示使品牌个性清楚地显现，与“简单的设计”的语境相合，“出”作结果补语。", "挤出": "语义：“挤出”指用力使东西从狭小处出来，用于抽象的设计个性不合。", "推出": "搭配：“推出”多接产品、服务、节目，不说“推出品牌的个性”。", "冒出": "语义：“冒出”指突然出现，多用于烟、汗、念头，与经过设计体现个性的语境不合。"}, "sentence_index": 6, "correct_answer": "彰显"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把秘密彰显在心里。", "explanation": "这里应该用〈隐藏〉。彰显是让好的品质或特点明显地呈现，秘密藏在心里要用隐藏。"}, {"text": "他的真实年龄被彰显得模糊不清。", "explanation": "这里误用“彰显”：彰显是使事物清楚地呈现，与“模糊不清”的意思相反，句意自相矛盾。"}, {"text": "大雨彰显了路上的脚印。", "explanation": "这里应该用〈抹去〉。彰显是使事物明显地被看见，脚印被雨水冲掉要用抹去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12273, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位设计师的作品很彰显了独特的审美。", "corrected_sentence": "这位设计师的作品彰显了独特的审美。", "error_description": "错误：在“彰显”前加了副词“很”。“很”不能修饰动词“彰显”，应删去，写作“彰显了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12273, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次展览彰显了了城市的文化底蕴。", "corrected_sentence": "这次展览彰显了城市的文化底蕴。", "error_description": "错误：“了”重复。“彰显了”中只需一个“了”，多出的“了”使句子不成立，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
