INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12274, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "可控性指事物或系统能够被有效控制、调节或管理的程度或能力。", "primary_collocate": null, "pronunciation": "kě kòng xìng", "ipa": "kʰɤ˨˩ kʰʊŋ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "每一次平稳起降，都是对物理定律严谨遵循的结果，也彰显了工程智慧在复杂系统中实现可控性的卓越能力。", "target_word": "可控性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这台机器的可控性很高，操作人员可以随时调整速度。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师首先要考虑系统的可控性和安全性。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自动驾驶技术必须保证车辆的可控性。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温度越稳定，实验过程的可控性就越强。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家认为，这项工程的可控性存在不足。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "提高生产线的可控性，可以减少事故。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药物的剂量容易调整，可控性较好。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络安全的关键在于提升系统的可控性。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无人机的可控性会受到强风的影响。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "事物或系统能被有效控制、调节的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '115bc740-bf98-4386-b8ea-52b5ee7d6f17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12274, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可控性", "is_correct": true, "explanation": "正确：“可控性”指能被控制、调节的程度，与“实现……的卓越能力”的语境相合。"}, {"text": "危险性", "is_correct": false, "explanation": "语义：“危险性”指可能造成伤害的性质，与“卓越能力”和“严谨遵循”的正面语境相反。"}, {"text": "偶然性", "is_correct": false, "explanation": "搭配：“实现”接目标、效果、功能，不说实现“偶然性”。"}, {"text": "隐蔽性", "is_correct": false, "explanation": "语义：“隐蔽性”指不易被察觉，与句中“也彰显了”的展示义相反。"}], "explanations": {"可控性": "正确：“可控性”指能被控制、调节的程度，与“实现……的卓越能力”的语境相合。", "危险性": "语义：“危险性”指可能造成伤害的性质，与“卓越能力”和“严谨遵循”的正面语境相反。", "偶然性": "搭配：“实现”接目标、效果、功能，不说实现“偶然性”。", "隐蔽性": "语义：“隐蔽性”指不易被察觉，与句中“也彰显了”的展示义相反。"}, "sentence_index": 0, "correct_answer": "可控性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天下大雨的可控性很大，我们还是带伞吧。", "explanation": "这里应该用〈可能性〉。可控性指能被控制、调节的程度，下雨不受人控制，说“下大雨的可控性很大”不通。"}, {"text": "这座桥的可控性很高，每年有几百万人来看。", "explanation": "这里应该用〈知名度〉。可控性说的是能否被管理，人多来看要用“知名度”，不能说“可控性高”。"}, {"text": "这台仪器的可控性很高，颜色非常漂亮。", "explanation": "这里应该用〈外观〉。可控性说的是能否被控制，颜色好看要用“外观”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12274, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可控性", "is_correct": true, "explanation": "正确：提高“可控性”能减少事故，与“提高生产线的……”的搭配和语境相合。"}, {"text": "故障率", "is_correct": false, "explanation": "语义：提高故障率会增加事故，与“可以减少事故”的语境相反。"}, {"text": "偶发性", "is_correct": false, "explanation": "搭配：“提高”多接水平、质量、效率，不说提高“偶发性”。"}, {"text": "噪音", "is_correct": false, "explanation": "搭配：“提高”不接“噪音”，噪音只说大小、降低或减少。"}], "explanations": {"可控性": "正确：提高“可控性”能减少事故，与“提高生产线的……”的搭配和语境相合。", "故障率": "语义：提高故障率会增加事故，与“可以减少事故”的语境相反。", "偶发性": "搭配：“提高”多接水平、质量、效率，不说提高“偶发性”。", "噪音": "搭配：“提高”不接“噪音”，噪音只说大小、降低或减少。"}, "sentence_index": 6, "correct_answer": "可控性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明天刮大风的可控性很大，我们别出门了。", "explanation": "这里应该用〈可能性〉。风不受人控制，说“刮大风的可控性很大”不通，应表达“可能性”。"}, {"text": "潮水涨落的可控性很高，每天都准时来回。", "explanation": "这里应该用〈规律性〉。潮水不受人控制，说“可控性很高”不通，应表达“规律性”。"}, {"text": "这家公司的可控性很高，员工每天都在唱歌跳舞。", "explanation": "这里应该用〈氛围〉。可控性说的是能否被管理，员工唱歌跳舞说的是氛围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新型无人机很可控性明显提高了。", "corrected_sentence": "新型无人机的可控性明显提高了。", "error_description": "错误：“很”是副词，不能修饰名词“可控性”。修饰名词要用定语标记“的”，应说“新型无人机的可控性明显提高了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套装置地可控性提高了。", "corrected_sentence": "这套装置的可控性提高了。", "error_description": "错误：“地”是状语标记，不能用来修饰名词“可控性”。修饰名词应用定语标记“的”，应说“这套装置的可控性提高了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12275, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平庸", "is_correct": true, "explanation": "平庸指没有突出之处，与“非常优秀，超出一般水平”的卓越意思相反。"}, {"text": "陈旧", "is_correct": false, "explanation": "陈旧指东西旧了、过时了，与卓越的意思没有反义关系。"}, {"text": "清晰", "is_correct": false, "explanation": "清晰指清楚、分明，与卓越在任何义项上都不构成反义关系。"}, {"text": "宽广", "is_correct": false, "explanation": "宽广指面积大或范围广，与卓越的意思没有反义关系。"}], "correct_answer": "平庸", "explanations": {"平庸": "平庸指没有突出之处，与“非常优秀，超出一般水平”的卓越意思相反。", "陈旧": "陈旧指东西旧了、过时了，与卓越的意思没有反义关系。", "清晰": "清晰指清楚、分明，与卓越在任何义项上都不构成反义关系。", "宽广": "宽广指面积大或范围广，与卓越的意思没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12275, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平庸", "is_correct": true, "explanation": "平庸指没有突出之处，与“非常优秀，超出一般水平”的卓越意思相反。"}, {"text": "圆润", "is_correct": false, "explanation": "圆润形容声音或线条柔和饱满，与卓越没有反义关系。"}, {"text": "湿润", "is_correct": false, "explanation": "湿润形容有水分、不干燥，与卓越没有反义关系。"}, {"text": "苍白", "is_correct": false, "explanation": "苍白形容脸色或颜色没有血色，与卓越没有反义关系。"}], "correct_answer": "平庸", "explanations": {"平庸": "平庸指没有突出之处，与“非常优秀，超出一般水平”的卓越意思相反。", "圆润": "圆润形容声音或线条柔和饱满，与卓越没有反义关系。", "湿润": "湿润形容有水分、不干燥，与卓越没有反义关系。", "苍白": "苍白形容脸色或颜色没有血色，与卓越没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12275, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "非常优秀，超出一般水平。", "primary_collocate": null, "pronunciation": "zhuó yuè", "ipa": "ʈʂwɔ˧˥ yɛ˥˩", "syllable_count": 2, "sentences": [{"text": "每一次平稳起降，都是对物理定律严谨遵循的结果，也彰显了工程智慧在复杂系统中实现可控性的卓越能力。", "target_word": "卓越", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这位科学家为国家做出了卓越的贡献。", "target_word": "卓越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她以卓越的成绩考进了这所大学。", "target_word": "卓越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司因卓越的服务赢得了客户的信任。", "target_word": "卓越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的领导才能十分卓越。", "target_word": "卓越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支球队在比赛中表现卓越。", "target_word": "卓越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校培养了许多才华卓越的人才。", "target_word": "卓越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的设计非常卓越，获得了大奖。", "target_word": "卓越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因卓越的研究成果获得了国家奖。", "target_word": "卓越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生们用卓越的技术救了这个病人。", "target_word": "卓越", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "非常优秀，超出一般水平", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '115bc740-bf98-4386-b8ea-52b5ee7d6f17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12275, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "卓越", "is_correct": true, "explanation": "卓越修饰“能力”，表示超出一般的出色程度，与“彰显”搭配，句意通顺。"}, {"text": "平庸", "is_correct": false, "explanation": "语义：“平庸”指没有突出之处，与“彰显”和“卓越”的意思相反，句子不通。"}, {"text": "美丽", "is_correct": false, "explanation": "搭配：“美丽”多描写外貌或景色，一般不修饰“能力”，说“美丽的能力”不自然。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容空气或物体含水多，不能修饰抽象的“能力”。"}], "explanations": {"卓越": "卓越修饰“能力”，表示超出一般的出色程度，与“彰显”搭配，句意通顺。", "平庸": "语义：“平庸”指没有突出之处，与“彰显”和“卓越”的意思相反，句子不通。", "美丽": "搭配：“美丽”多描写外貌或景色，一般不修饰“能力”，说“美丽的能力”不自然。", "潮湿": "搭配：“潮湿”形容空气或物体含水多，不能修饰抽象的“能力”。"}, "sentence_index": 0, "correct_answer": "卓越"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她长得非常卓越，走到哪里都引人注目。", "explanation": "这里应该用〈出众〉。卓越形容能力、成绩等出色的表现，描写外貌要用“出众”，不说“长得卓越”。"}, {"text": "这台冰箱的温度很卓越，食物都不容易坏。", "explanation": "这里应该用〈稳定〉。卓越形容能力或成就超出一般，描述冰箱的温度要用“稳定”，不能说“温度卓越”。"}, {"text": "这间房子的空气卓越，很适合居住。", "explanation": "这里应该用〈清新〉。卓越指能力或成就超出一般，描写空气只能用“清新”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12275, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "卓越", "is_correct": true, "explanation": "卓越修饰“人才”前的“才华”，表示才华超出一般，与“培养”的语境相符。"}, {"text": "迟钝", "is_correct": false, "explanation": "搭配：“迟钝”形容反应慢，一般不说“才华迟钝”，与“才华”搭配不当。"}, {"text": "低劣", "is_correct": false, "explanation": "语义：“低劣”指质量差，与“学校培养”的积极语境相矛盾。"}, {"text": "呆板", "is_correct": false, "explanation": "搭配：“呆板”形容态度或风格生硬，不能修饰“才华”。"}], "explanations": {"卓越": "卓越修饰“人才”前的“才华”，表示才华超出一般，与“培养”的语境相符。", "迟钝": "搭配：“迟钝”形容反应慢，一般不说“才华迟钝”，与“才华”搭配不当。", "低劣": "语义：“低劣”指质量差，与“学校培养”的积极语境相矛盾。", "呆板": "搭配：“呆板”形容态度或风格生硬，不能修饰“才华”。"}, "sentence_index": 6, "correct_answer": "卓越"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老人心地卓越，经常帮助邻居。", "explanation": "这里应该用〈善良〉。卓越形容能力或成就，描写心地、性格要用“善良”。"}, {"text": "这座城市的气温卓越，很适合游玩。", "explanation": "这里应该用〈宜人〉。卓越用于能力或成绩，描写气候要用“宜人”。"}, {"text": "这道菜的颜色卓越，看起来很有食欲。", "explanation": "这里应该用〈鲜艳〉。卓越形容能力或成就，形容颜色要用“鲜艳”，不能说“颜色卓越”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12275, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位工程师为公司做出了卓越地贡献。", "corrected_sentence": "这位工程师为公司做出了卓越的贡献。", "error_description": "错误形式是“卓越地贡献”，正确形式是“卓越的贡献”。“卓越”修饰名词“贡献”时要用“的”，“地”只用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12275, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套系统的运行非常很卓越，客户都很满意。", "corrected_sentence": "这套系统的运行非常卓越，客户都很满意。", "error_description": "错误在于“非常”和“很”重复修饰“卓越”，应删去“很”，改为“非常卓越”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
