INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12279, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "爸爸，指父亲，是子女对男性直系长辈的称呼。", "primary_collocate": null, "pronunciation": "bà ba", "ipa": "pa⁵¹ pa", "syllable_count": 2, "sentences": [{"text": "故事可以从爸爸传到孩子。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我爸爸每天开车送我去学校。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸下班回家，先给妈妈打电话。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末爸爸带我去公园放风筝。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的爸爸在医院工作，他是一名医生。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸笑着说：“你做得很好。”", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，爸爸总是给我讲故事。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的头发白了，但他还是每天跑步。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天是父亲节，我给爸爸买了一份礼物。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸和妈妈结婚二十年了。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "老爸", "label": "口语称呼"}, {"form": "爸爸们", "label": "复数"}, {"form": "一个爸爸", "label": "量词：个"}, {"form": "一位爸爸", "label": "量词：位"}], "register": "口语", "sense_fingerprint": "名词：父亲，子女对父亲的称呼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '477f6bce-3da5-4648-b3b5-63365f3456a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12279, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "爸爸", "is_correct": true, "explanation": "正确答案。bà ba，第二音节为轻声，指父亲。"}, {"text": "巴巴", "is_correct": false, "explanation": "bā ba 与 bà ba 第一音节声调不同（第一声），意思是急切、迫切，与父亲无关。"}, {"text": "把吧", "is_correct": false, "explanation": "bǎ ba 与 bà ba 第一音节声调不同（第三声），“把吧”是口语语气组合，不指称人。"}, {"text": "爸妈", "is_correct": false, "explanation": "bà mā 与 bà ba 第二音节声母不同（b 与 m），声调也改变，意思是父母，指两人。"}], "explanations": {"爸爸": "正确答案。bà ba，第二音节为轻声，指父亲。", "巴巴": "bā ba 与 bà ba 第一音节声调不同（第一声），意思是急切、迫切，与父亲无关。", "把吧": "bǎ ba 与 bà ba 第一音节声调不同（第三声），“把吧”是口语语气组合，不指称人。", "爸妈": "bà mā 与 bà ba 第二音节声母不同（b 与 m），声调也改变，意思是父母，指两人。"}, "sentence_index": null, "correct_answer": "爸爸"}, "level_3": {"options": [{"text": "爸爸", "is_correct": true, "explanation": "爸爸：故事可以由父亲一代代传给孩子，符合句意。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不能把故事传给孩子，故事的传递者必须是有生命的人。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会讲故事，“从……传到孩子”要求一个能传承故事的人作为起点。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“从窗户传到孩子”不成立，“传”的起点应是能传承故事的人，而不是建筑部件。"}], "explanations": {"爸爸": "爸爸：故事可以由父亲一代代传给孩子，符合句意。", "椅子": "语义：椅子不能把故事传给孩子，故事的传递者必须是有生命的人。", "石头": "语义：石头不会讲故事，“从……传到孩子”要求一个能传承故事的人作为起点。", "窗户": "搭配：“从窗户传到孩子”不成立，“传”的起点应是能传承故事的人，而不是建筑部件。"}, "sentence_index": 0, "correct_answer": "爸爸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的爸爸是我妈妈的妈妈，每次来都会给我做好吃的。", "explanation": "这里应该用〈外婆〉。爸爸指男性父亲，不能指母亲的母亲；母亲的母亲应称〈外婆〉。"}, {"text": "爸爸是我爸爸的弟弟。", "explanation": "这里应该用〈叔叔〉。爸爸指父亲，不能指父亲的弟弟；父亲的弟弟应称〈叔叔〉。"}, {"text": "我的爸爸今年八岁，每天背着书包去上学，还很调皮。", "explanation": "这里应该用〈弟弟〉。爸爸指父亲，不能指八岁、背着书包上学的小男孩；这样的小男孩应称〈弟弟〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f752ac-a758-40a7-916c-c404be2f5547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12279, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "爸爸", "is_correct": true, "explanation": "正确答案。bà ba，第二音节为轻声，指父亲。"}, {"text": "叭叭", "is_correct": false, "explanation": "bā ba 与 bà ba 第一音节声调不同（第一声），叭叭是喇叭声的拟声词。"}, {"text": "办吧", "is_correct": false, "explanation": "bàn ba 与 bà ba 韵母不同（多了 n），办吧是口语中表示同意或催促的语气组合，不指父亲。"}, {"text": "棒吧", "is_correct": false, "explanation": "bàng ba 与 bà ba 韵母不同（多了 ng），棒吧是口语中表示赞叹的语气组合，不指父亲。"}], "explanations": {"爸爸": "正确答案。bà ba，第二音节为轻声，指父亲。", "叭叭": "bā ba 与 bà ba 第一音节声调不同（第一声），叭叭是喇叭声的拟声词。", "办吧": "bàn ba 与 bà ba 韵母不同（多了 n），办吧是口语中表示同意或催促的语气组合，不指父亲。", "棒吧": "bàng ba 与 bà ba 韵母不同（多了 ng），棒吧是口语中表示赞叹的语气组合，不指父亲。"}, "sentence_index": null, "correct_answer": "爸爸"}, "level_3": {"options": [{"text": "爸爸", "is_correct": true, "explanation": "爸爸：小时候父亲常给孩子讲故事，符合“小时候”和“讲故事”的语境。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板不会讲故事，“讲故事”的施事必须是人。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“给我讲故事”要求有言语能力的主语，雨伞不能讲故事。"}, {"text": "同事", "is_correct": false, "explanation": "语义：同事一般是成年后认识的人，在“小时候”的语境下不会总是给我讲故事。"}], "explanations": {"爸爸": "爸爸：小时候父亲常给孩子讲故事，符合“小时候”和“讲故事”的语境。", "黑板": "语义：黑板不会讲故事，“讲故事”的施事必须是人。", "雨伞": "搭配：“给我讲故事”要求有言语能力的主语，雨伞不能讲故事。", "同事": "语义：同事一般是成年后认识的人，在“小时候”的语境下不会总是给我讲故事。"}, "sentence_index": 6, "correct_answer": "爸爸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的爸爸今年上小学一年级。", "explanation": "这里应该用〈儿子〉。爸爸是成年父亲，不能指正在上小学的孩子；这句说的应是〈儿子〉。"}, {"text": "我的爸爸比我大两岁，周末常和我一起打篮球。", "explanation": "这里应该用〈哥哥〉。爸爸指父亲，不可能只比孩子大两岁；比我大两岁的男性亲人应称〈哥哥〉。"}, {"text": "刚出生的爸爸还不会说话。", "explanation": "这里应该用〈婴儿〉。爸爸指成年的父亲，刚出生、还不会说话的应是〈婴儿〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f752ac-a758-40a7-916c-c404be2f5547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12279, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "邻居家的一只爸爸正在教孩子骑车。", "corrected_sentence": "邻居家的一位爸爸正在教孩子骑车。", "error_description": "量词错误：“爸爸”指人，应该用量词“位”（或“个”），“只”用于动物，不能说“一只爸爸”。正确说法是“一位爸爸”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f752ac-a758-40a7-916c-c404be2f5547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12279, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的爸爸们今天很忙，没有时间陪我。", "corrected_sentence": "我的爸爸今天很忙，没有时间陪我。", "error_description": "数量不符：句中只指“我”的一位父亲，而“我的爸爸们”指多位父亲，与语境不符，应说“我的爸爸”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f752ac-a758-40a7-916c-c404be2f5547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
