INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12289, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "虚假的，不真实的。", "primary_collocate": null, "pronunciation": "jiǎ", "ipa": "tɕja˨˩˦", "syllable_count": 1, "sentences": [{"text": "故事可以是古代的事，也可以是假的。", "target_word": "假", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个包是假的，不是真的。", "target_word": "假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话是假的，我不信。", "target_word": "假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片看起来很假。", "target_word": "假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息是真的还是假的？", "target_word": "假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那朵花是假的，不用给它浇水。", "target_word": "假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的笑很假，我看得出来。", "target_word": "假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶酒是假的，别喝。", "target_word": "假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说自己生病了，其实是假的。", "target_word": "假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小鸟是假的，它不会飞。", "target_word": "假", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "假话", "label": "复合"}, {"form": "假货", "label": "复合"}], "register": "中性", "sense_fingerprint": "虚假、不真实的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e176a57-3f09-4b1b-b4b5-6e20e7f24a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12289, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "假", "is_correct": true, "explanation": "正确：假（jiǎ）表示虚假、不真实。"}, {"text": "家", "is_correct": false, "explanation": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是家。"}, {"text": "价", "is_correct": false, "explanation": "jià（第四声）与 jiǎ（第三声）声调不同，意思是价格。"}, {"text": "嫁", "is_correct": false, "explanation": "jià（第四声）与 jiǎ（第三声）声调不同，意思是出嫁。"}], "explanations": {"假": "正确：假（jiǎ）表示虚假、不真实。", "家": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是家。", "价": "jià（第四声）与 jiǎ（第三声）声调不同，意思是价格。", "嫁": "jià（第四声）与 jiǎ（第三声）声调不同，意思是出嫁。"}, "sentence_index": null, "correct_answer": "假"}, "level_3": {"options": [{"text": "假", "is_correct": true, "explanation": "正确。假：不真实，指虚构的故事，与“古代的事”并列。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：胖是形体特征，不能用来形容故事，句意不通。"}, {"text": "热", "is_correct": false, "explanation": "语义：热指温度，故事不能是“热的”，句意不通。"}, {"text": "硬", "is_correct": false, "explanation": "语义：硬指质地坚硬，不能用来形容故事，句意不通。"}], "explanations": {"假": "正确。假：不真实，指虚构的故事，与“古代的事”并列。", "胖": "体貌：胖是形体特征，不能用来形容故事，句意不通。", "热": "语义：热指温度，故事不能是“热的”，句意不通。", "硬": "语义：硬指质地坚硬，不能用来形容故事，句意不通。"}, "sentence_index": 0, "correct_answer": "假"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路的距离很假，我走了一个小时才到。", "explanation": "这里应该用〈远〉。“假”指不真实，只用于人、物或说法；路程是客观长短，形容距离要用“远”或“近”。"}, {"text": "今天的天气很假，我们还是去散步吧。", "explanation": "这里应该用〈好〉。“假”指不真实，天气是自然现象，不能说它假；形容天气要用“好”或“坏”。"}, {"text": "这块手表上的时间很假，我们要重新校对。", "explanation": "这里应该用〈准〉。“假”指不真实，时间是客观的；手表走不准要说“不准”，不说“假”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12289, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "假", "is_correct": true, "explanation": "正确：假（jiǎ）表示虚假、不真实。"}, {"text": "加", "is_correct": false, "explanation": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是增加。"}, {"text": "架", "is_correct": false, "explanation": "jià（第四声）与 jiǎ（第三声）声调不同，意思是架子。"}, {"text": "驾", "is_correct": false, "explanation": "jià（第四声）与 jiǎ（第三声）声调不同，意思是驾驶。"}], "explanations": {"假": "正确：假（jiǎ）表示虚假、不真实。", "加": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是增加。", "架": "jià（第四声）与 jiǎ（第三声）声调不同，意思是架子。", "驾": "jià（第四声）与 jiǎ（第三声）声调不同，意思是驾驶。"}, "sentence_index": null, "correct_answer": "假"}, "level_3": {"options": [{"text": "假", "is_correct": true, "explanation": "正确。假：虚假、不真实，形容笑容不真诚。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：瘦是形体特征，不能用来形容笑，句意不通。"}, {"text": "远", "is_correct": false, "explanation": "语义：远指距离，笑没有远近之分，句意不通。"}, {"text": "贵", "is_correct": false, "explanation": "语义：贵指价格高，不能用来形容笑，句意不通。"}], "explanations": {"假": "正确。假：虚假、不真实，形容笑容不真诚。", "瘦": "体貌：瘦是形体特征，不能用来形容笑，句意不通。", "远": "语义：远指距离，笑没有远近之分，句意不通。", "贵": "语义：贵指价格高，不能用来形容笑，句意不通。"}, "sentence_index": 6, "correct_answer": "假"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台秤的重量很假，买东西要重新称一下。", "explanation": "这里应该用〈轻〉。“假”指不真实，重量是测得的数值；说东西轻要用“轻”或“重”，不说“假”。"}, {"text": "今天的温度很假，我们穿厚一点。", "explanation": "这里应该用〈低〉。“假”指不真实，温度是测得的数值；气温低要说“低”或“高”，不说“假”。"}, {"text": "这辆车的速度很假，它其实开得很慢。", "explanation": "这里应该用〈快〉。“假”指不真实，速度是测得的数值；车速要说“快”或“慢”，不说“假”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12289, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他笑很假。", "corrected_sentence": "他笑得很假。", "error_description": "补语错误：“笑”后表示程度的补语要加“得”，应说“笑得很假”，不能说“笑很假”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12289, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张照片假很。", "corrected_sentence": "这张照片很假。", "error_description": "词序错误：程度副词“很”应放在形容词“假”之前，应说“很假”，不能说“假很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
