INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12290, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "书籍的总称，指装订成册的著作。", "primary_collocate": null, "pronunciation": "shū běn", "ipa": "ʂu pən", "syllable_count": 2, "sentences": [{"text": "比如，有些部落没有书本，但他们的祖先是谁、从哪里来，都是通过故事记住的。", "target_word": "书本", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "讲故事是口头传统，不用书本。", "target_word": "书本", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "他背着书本走进了教室。", "target_word": "书本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书本上的知识很有用。", "target_word": "书本", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请把书本放在桌子上。", "target_word": "书本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在课堂上翻开书本。", "target_word": "书本", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "光看书本还不够，还要多练习。", "target_word": "书本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下课了，同学们合上书本回家。", "target_word": "书本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨把书本都淋湿了。", "target_word": "书本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书包里除了书本，还有一个水杯。", "target_word": "书本", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "書本", "label": "繁体"}, {"form": "书本知识", "label": "复合"}], "register": "中性", "sense_fingerprint": "书籍的总称，装订成册的著作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15493912-f1ff-4f6e-a884-3ffcb8e6a4f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12290, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书本", "is_correct": true, "explanation": "正确：“书本”指装订成册的书，与“没有书本”及后文“通过故事记住”相符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：人人都呼吸空气，不会说“没有空气”，与句意不通。"}, {"text": "故事", "is_correct": false, "explanation": "语义：后半句说祖先是“通过故事记住的”，填“故事”则前后自相矛盾。"}, {"text": "太阳", "is_correct": false, "explanation": "搭配：“没有”不能用于太阳，“有些部落没有太阳”不成立。"}], "explanations": {"书本": "正确：“书本”指装订成册的书，与“没有书本”及后文“通过故事记住”相符。", "空气": "语义：人人都呼吸空气，不会说“没有空气”，与句意不通。", "故事": "语义：后半句说祖先是“通过故事记住的”，填“故事”则前后自相矛盾。", "太阳": "搭配：“没有”不能用于太阳，“有些部落没有太阳”不成立。"}, "sentence_index": 0, "correct_answer": "书本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只书本。", "explanation": "这里不能用〈只〉。〈只〉多用于动物，书本的量词应该是〈摞〉或〈套〉。"}, {"text": "这个书本有五层，每层都摆满了书。", "explanation": "这里说的是书架，应该用〈书架〉。〈层〉用于书架这类有格层的家具，书本本身没有层。"}, {"text": "他买了一辆书本，放进了书包。", "explanation": "这里不能用〈辆〉。〈辆〉用于车，书本可用〈本〉〈摞〉〈套〉等量词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12290, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书本", "is_correct": true, "explanation": "正确：“书本”指可供学习的书，与“光看……还不够，还要多练习”相符。"}, {"text": "食物", "is_correct": false, "explanation": "搭配：“光看”后接的应是可以学习的内容，“光看食物”说不通。"}, {"text": "电流", "is_correct": false, "explanation": "语义：电流看不见，也无法通过看来练习，“光看电流”不成立。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水是自然现象，“光看雨水还不够，还要多练习”没有意义。"}], "explanations": {"书本": "正确：“书本”指可供学习的书，与“光看……还不够，还要多练习”相符。", "食物": "搭配：“光看”后接的应是可以学习的内容，“光看食物”说不通。", "电流": "语义：电流看不见，也无法通过看来练习，“光看电流”不成立。", "雨水": "语义：雨水是自然现象，“光看雨水还不够，还要多练习”没有意义。"}, "sentence_index": 6, "correct_answer": "书本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他送我一朵书本。", "explanation": "这里不能用〈朵〉。〈朵〉用于花，书本的量词应该是〈摞〉或〈套〉。"}, {"text": "这个书本的门打不开，里面放满了书。", "explanation": "这里说的是书柜，应该用〈书柜〉。〈门〉是书柜、衣柜这类家具的部件，书本没有门。"}, {"text": "书包里装着一位书本。", "explanation": "这里不能用〈位〉。〈位〉用于人，书本的量词应该是〈摞〉或〈套〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那场大雨把我的书本们全淋湿了。", "corrected_sentence": "那场大雨把我的书本全淋湿了。", "error_description": "“书本”是泛称，不能加“们”表示复数，应去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的书本们都放在书架上。", "corrected_sentence": "我们的书本都放在书架上。", "error_description": "“书本”是泛称，不能加“们”表示复数，应去掉“们”，说“书本都放在书架上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
