INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12292, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或鼓槌敲击鼓面使其发声；也比喻心里紧张、不安。", "primary_collocate": null, "pronunciation": "dǎ gǔ", "ipa": "ta˨˩˦ ku˨˩˦", "syllable_count": 2, "sentences": [{"text": "有的地方打鼓讲故事，有的地方跳舞讲故事。", "target_word": "打鼓", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他每天晚上在家打鼓，邻居都睡不着。", "target_word": "打鼓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天要考试，我心里直打鼓。", "target_word": "打鼓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明会打鼓，也会唱歌。", "target_word": "打鼓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过节的时候，大家一边打鼓一边跳舞。", "target_word": "打鼓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次上台，心里有点儿打鼓。", "target_word": "打鼓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道他会不会来，心里一直在打鼓。", "target_word": "打鼓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子拿着小棍子在桌子上打鼓。", "target_word": "打鼓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时在村里打鼓，声音很大。", "target_word": "打鼓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要见女朋友的爸爸，他心里打鼓。", "target_word": "打鼓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打着鼓", "label": "体标"}, {"form": "打过鼓", "label": "体标"}], "register": "中性", "sense_fingerprint": "敲鼓；比喻心里紧张不安", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e176a57-3f09-4b1b-b4b5-6e20e7f24a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12292, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打鼓", "is_correct": true, "explanation": "正确答案。打鼓（dǎ gǔ）：用手或鼓槌敲击鼓面。"}, {"text": "大鼓", "is_correct": false, "explanation": "dà（第四声）与 dǎ（第三声）声调不同，意思是一种鼓，也指一种说唱艺术。"}, {"text": "大股", "is_correct": false, "explanation": "dà（第四声）与 dǎ（第三声）声调不同，意思是数量很多的一股，如大股资金。"}, {"text": "大骨", "is_correct": false, "explanation": "dà（第四声）与 dǎ（第三声）声调不同，意思是较大的骨头，如大骨汤。"}], "explanations": {"打鼓": "正确答案。打鼓（dǎ gǔ）：用手或鼓槌敲击鼓面。", "大鼓": "dà（第四声）与 dǎ（第三声）声调不同，意思是一种鼓，也指一种说唱艺术。", "大股": "dà（第四声）与 dǎ（第三声）声调不同，意思是数量很多的一股，如大股资金。", "大骨": "dà（第四声）与 dǎ（第三声）声调不同，意思是较大的骨头，如大骨汤。"}, "sentence_index": null, "correct_answer": "打鼓"}, "level_3": {"options": [{"text": "打鼓", "is_correct": true, "explanation": "正确答案。打鼓与跳舞一样，是伴随讲故事的活动。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理是修复器物，与讲故事的伴随活动场景不合。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：讨论也是言语活动，与讲故事重复，不能与跳舞并列为伴随活动。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：翻译一般以文字或语言作宾语，不能直接说翻译讲故事。"}], "explanations": {"打鼓": "正确答案。打鼓与跳舞一样，是伴随讲故事的活动。", "修理": "语义：修理是修复器物，与讲故事的伴随活动场景不合。", "讨论": "语义：讨论也是言语活动，与讲故事重复，不能与跳舞并列为伴随活动。", "翻译": "搭配：翻译一般以文字或语言作宾语，不能直接说翻译讲故事。"}, "sentence_index": 0, "correct_answer": "打鼓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到他考上大学的消息，我心里一直打鼓，高兴得不得了。", "explanation": "这里应该用〈兴奋〉。打鼓的心理义只表示紧张不安，不能用来描写高兴的心情。"}, {"text": "他站在门口，一直在门上打鼓，想让屋里的人开门。", "explanation": "这里应该用〈敲〉。打鼓指击打鼓面让鼓发声，敲门不能说打鼓。"}, {"text": "他坐在电脑前，快速地打鼓，很快就写完了报告。", "explanation": "这里应该用〈打字〉。打鼓指敲击鼓面发声，用键盘输入文字要说打字，不能说打鼓。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12292, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打鼓", "is_correct": true, "explanation": "正确答案。心里一直在打鼓表示紧张不安。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：心里的紧张不安无法游泳，这个说法不成立。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：洗澡是身体的动作，不能用来描述心里的状态。"}, {"text": "织毛衣", "is_correct": false, "explanation": "搭配：心里一直在后面应接表示心理状态的动词，织毛衣是具体动作，搭配不当。"}], "explanations": {"打鼓": "正确答案。心里一直在打鼓表示紧张不安。", "游泳": "语义：心里的紧张不安无法游泳，这个说法不成立。", "洗澡": "语义：洗澡是身体的动作，不能用来描述心里的状态。", "织毛衣": "搭配：心里一直在后面应接表示心理状态的动词，织毛衣是具体动作，搭配不当。"}, "sentence_index": 6, "correct_answer": "打鼓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "跑完三千米，他心里一直在打鼓，喘得很厉害。", "explanation": "打鼓表示紧张不安的心理，这里描写的是运动后的心跳，语义不合。"}, {"text": "他生气地走过去，对弟弟大声打鼓。", "explanation": "这里应该用〈训斥〉。打鼓只指敲击鼓面，不能用来指对人大声责骂。"}, {"text": "她每天早上打鼓，化很久的妆，才肯出门。", "explanation": "这里应该用〈打扮〉。打鼓指敲击鼓面，修饰外貌要说打扮，不能说打鼓。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12292, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小王星期天在操场上打鼓了一个小时。", "corrected_sentence": "小王星期天在操场上打鼓打了一个小时。", "error_description": "离合词：打鼓中“打”后要接“了”，应说「打鼓打了一个小时」，不能说「打鼓了一个小时」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12292, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "考试前，他心里一直打鼓着。", "corrected_sentence": "考试前，他心里一直打着鼓。", "error_description": "着应紧跟动词打，应说打着鼓，不能说打鼓着。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
