INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12295, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指完成某件事并且结果是正确的。", "primary_collocate": null, "pronunciation": "zuò duì", "ipa": "tswo˥˩ twei˥˩", "syllable_count": 2, "sentences": [{"text": "故事可以教人做对的事，也可以让人开心。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这道题我做对了。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你做对了，老师给你一朵小红花。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他十道题都做对了。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有做对事情，别人才会相信你。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得你这次做对了。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子做对了就应该夸他。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜我做对了吗？", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做对了一件大事，大家都谢谢她。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问：谁把这道题做对了？", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "做对了", "label": "体标"}, {"form": "做对过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把事情做得正确", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e176a57-3f09-4b1b-b4b5-6e20e7f24a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12295, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "做对", "is_correct": true, "explanation": "正确答案。做对的事指做得正确的事，与句中“教人”搭配，表示教人正确做事。"}, {"text": "做客", "is_correct": false, "explanation": "语义：做客指到别人家作客，不能用于教人做的事。"}, {"text": "做梦", "is_correct": false, "explanation": "语义：做梦是睡眠中的活动，不能构成教人的内容。"}, {"text": "做完", "is_correct": false, "explanation": "体貌：做完强调动作已经完成，而句子要表示做得对不对，语义不合。"}], "explanations": {"做对": "正确答案。做对的事指做得正确的事，与句中“教人”搭配，表示教人正确做事。", "做客": "语义：做客指到别人家作客，不能用于教人做的事。", "做梦": "语义：做梦是睡眠中的活动，不能构成教人的内容。", "做完": "体貌：做完强调动作已经完成，而句子要表示做得对不对，语义不合。"}, "sentence_index": 0, "correct_answer": "做对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个老人很会讲故事，他说的故事都做对了，大家都很佩服。", "explanation": "这里应该用〈说对〉。做对指把事情做得正确，故事的内容说得对不对要用说对。"}, {"text": "这个谜语很难，他居然做对了谜底。", "explanation": "这里应该用〈猜对〉。谜底是猜出来的，做对用于完成行为，不用于猜测的结果。"}, {"text": "这次比赛的结果很难判断，他做对了比赛的结果，大家都没想到。", "explanation": "这里应该用〈估计对〉。做对指做事正确，对结果的判断要用估计对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12295, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做对", "is_correct": true, "explanation": "正确答案。孩子做对了事，才应该被夸奖。"}, {"text": "做错", "is_correct": false, "explanation": "语义：应该夸奖的是做对的孩子，做错与夸他的道理相反。"}, {"text": "做贼", "is_correct": false, "explanation": "语义：做贼是不正当的行为，不能作为夸奖的前提。"}, {"text": "做噩梦", "is_correct": false, "explanation": "搭配：做噩梦是身不由己发生的状态，不是可以夸奖的行为，搭配不当。"}], "explanations": {"做对": "正确答案。孩子做对了事，才应该被夸奖。", "做错": "语义：应该夸奖的是做对的孩子，做错与夸他的道理相反。", "做贼": "语义：做贼是不正当的行为，不能作为夸奖的前提。", "做噩梦": "搭配：做噩梦是身不由己发生的状态，不是可以夸奖的行为，搭配不当。"}, "sentence_index": 6, "correct_answer": "做对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对这次天气的预报很有把握，他做对了下雨的时间，大家都没想到。", "explanation": "这里应该用〈推测对〉。下雨的时间是推测出来的，做对不用于推测的结果。"}, {"text": "这场比赛很难，他一开场就做对了两局。", "explanation": "这里应该用〈赢〉。做对指做事没有做错，比赛中赢得局数要用赢，不能用做对。"}, {"text": "他躺在床上，很快就做对了一个好梦。", "explanation": "这里不能说做对。做对指把事情做得正确，梦境没有对错，应说「做了一个好梦」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12295, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这道题他已经做对了了。", "corrected_sentence": "这道题他已经做对了。", "error_description": "体标重复：“了”只用一次，应说「这道题他已经做对了」，不能说「做对了了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12295, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前把做对过这道题。", "corrected_sentence": "我以前做对过这道题。", "error_description": "把字句：“把”后要接受事对象，不能直接接动词「做对」，应说「我以前做对过这道题」，去掉“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
