INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12304, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示确实、的确，用来强调所说的话是真实的。", "primary_collocate": null, "pronunciation": "zhēn de", "ipa": "ʈʂən˥ tɤ", "syllable_count": 2, "sentences": [{"text": "虽然这些事没有真的发生，但是人们喜欢讲它们。", "target_word": "真的", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这家饭店的菜真的很好吃。", "target_word": "真的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我真的不知道他去哪儿了。", "target_word": "真的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天真的太冷了，我不想出门。", "target_word": "真的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你真的要一个人去吗？", "target_word": "真的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我真的很感谢你昨天帮我。", "target_word": "真的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他真的喜欢这个工作，每天都很开心。", "target_word": "真的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她唱得真的很好听。", "target_word": "真的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次考试真的很难，我没做完。", "target_word": "真的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我真的忘了带钱，对不起。", "target_word": "真的", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "真的吗", "label": "疑问形式"}, {"form": "真的是", "label": "强调形式"}], "register": "中性", "sense_fingerprint": "副词，强调所说的话确实如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b98e791d-83a1-47e0-a7fc-a2d89d85f752') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12304, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "真的", "is_correct": true, "explanation": "正确：“真的”强调事情确实发生，与“没有真的发生”的语境相符。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示完成，与“没有……发生”的否定语境矛盾。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”通常修饰形容词，不能直接修饰动词“发生”。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示时间刚过去，与“没有……发生”的虚构语境不合。"}], "explanations": {"真的": "正确：“真的”强调事情确实发生，与“没有真的发生”的语境相符。", "已经": "语义：“已经”表示完成，与“没有……发生”的否定语境矛盾。", "非常": "搭配：“非常”通常修饰形容词，不能直接修饰动词“发生”。", "刚刚": "语义：“刚刚”表示时间刚过去，与“没有……发生”的虚构语境不合。"}, "sentence_index": 0, "correct_answer": "真的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天真的的很忙，没空吃饭。", "explanation": "“真的”后面多了一个“的”，属于重复用字，应改为“我今天真的很忙”。"}, {"text": "我不知道真的他去哪儿了。", "explanation": "“真的”放在了另一个主语“他”之前，语序不通；应放在主语“我”之后，即“我真的不知道他去哪儿了”。"}, {"text": "我很真的喜欢这个城市。", "explanation": "“真的”不能紧跟副词“很”，语序不通；应说“我真的很喜欢这个城市”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12304, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真的", "is_correct": true, "explanation": "正确：“真的”表示确实，与“每天都很开心”的状态描述相符。"}, {"text": "正在", "is_correct": false, "explanation": "语法：“正在”表示动作进行，不能与“喜欢”这类心理状态动词搭配，“他正在喜欢这个工作”不通。"}, {"text": "被", "is_correct": false, "explanation": "语法：“被”用于被动句，“他被喜欢这个工作”结构不通。"}, {"text": "把", "is_correct": false, "explanation": "语法：“把”字句须为“把＋宾语＋动词”结构，“他把喜欢这个工作”不通。"}], "explanations": {"真的": "正确：“真的”表示确实，与“每天都很开心”的状态描述相符。", "正在": "语法：“正在”表示动作进行，不能与“喜欢”这类心理状态动词搭配，“他正在喜欢这个工作”不通。", "被": "语法：“被”用于被动句，“他被喜欢这个工作”结构不通。", "把": "语法：“把”字句须为“把＋宾语＋动词”结构，“他把喜欢这个工作”不通。"}, "sentence_index": 6, "correct_answer": "真的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "钱包里真的的一块钱，你借我吧。", "explanation": "“真的”后面多了一个“的”，属于重复用字，应去掉。"}, {"text": "我今天很真的忙，没空吃饭。", "explanation": "“真的”不能紧跟副词“很”，语序不通；应说“今天真的很忙”。"}, {"text": "桌子上真的的书很多。", "explanation": "“真的的”多了一个“的”，属于重复用字；且此处“真的”作副词，不能直接修饰名词“书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我觉得他真的的说对了。", "corrected_sentence": "我觉得他真的说对了。", "error_description": "错误：“真的”后面多了一个“的”，属于重复用字。正确：“我觉得他真的说对了”，“真的”作状语修饰“说对”，表示确实如此。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他真的的喜欢小猫，每天都陪它玩。", "corrected_sentence": "他真的喜欢小猫，每天都陪它玩。", "error_description": "错误：“真的”后面多了一个“的”，属于重复用字。正确：“他真的喜欢小猫”，“真的”作状语修饰“喜欢”，表示确实如此。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
