INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12306, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "使人感到快乐、放松的活动或消遣。", "primary_collocate": null, "pronunciation": "yú lè", "ipa": "y˧˥ lɤ˥˩", "syllable_count": 2, "sentences": [{"text": "叙事不只是为了娱乐，还能教人做人的道理。", "target_word": "娱乐", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "看电影是我最喜欢的娱乐。", "target_word": "娱乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的夜晚有很多娱乐活动。", "target_word": "娱乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们需要学习，也需要一点娱乐。", "target_word": "娱乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作很累时，听音乐是一种很好的娱乐。", "target_word": "娱乐", "complexity_tier": "T3", "furigana": "gōng zuò hěn lèi shí, tīng yīn yuè shì yì zhǒng hěn hǎo de yú lè。", "sentence_source": "generated"}, {"text": "现在手机上的娱乐越来越多。", "target_word": "娱乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人喜欢下棋、聊天这样的娱乐。", "target_word": "娱乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店不仅饭菜好，还能提供娱乐。", "target_word": "娱乐", "complexity_tier": "T3", "furigana": "zhè jiā diàn bù jǐn fàn cài hǎo, hái néng tí gōng yú lè。", "sentence_source": "generated"}, {"text": "他住的地方很安静，没有什么娱乐。", "target_word": "娱乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚会上有唱歌、跳舞等娱乐。", "target_word": "娱乐", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "娱乐活动", "label": "复合词"}, {"form": "娱乐圈", "label": "复合词"}, {"form": "娱乐节目", "label": "复合词"}], "register": "中性", "sense_fingerprint": "使人快乐放松的活动或消遣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b98e791d-83a1-47e0-a7fc-a2d89d85f752') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12306, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "娱乐", "is_correct": true, "explanation": "“娱乐”指让人放松的活动，与“不只是为了……还能教人做人的道理”形成对比。"}, {"text": "食物", "is_correct": false, "explanation": "语义：叙事的目的是教做人，不是用来提供吃的东西，句意不通。"}, {"text": "货物", "is_correct": false, "explanation": "语义：叙事不是用来运输或买卖货物的，句意不通。"}, {"text": "垃圾", "is_correct": false, "explanation": "语域：“垃圾”是口语中的贬义词，与书面的叙事语境不合，也与“教人做人的道理”相悖。"}], "explanations": {"娱乐": "“娱乐”指让人放松的活动，与“不只是为了……还能教人做人的道理”形成对比。", "食物": "语义：叙事的目的是教做人，不是用来提供吃的东西，句意不通。", "货物": "语义：叙事不是用来运输或买卖货物的，句意不通。", "垃圾": "语域：“垃圾”是口语中的贬义词，与书面的叙事语境不合，也与“教人做人的道理”相悖。"}, "sentence_index": 0, "correct_answer": "娱乐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每天早上我去公园娱乐身体。", "explanation": "这里应该用〈锻炼〉。“娱乐”指让人快乐放松的活动，不能说“娱乐身体”，锻炼身体才是习惯说法。"}, {"text": "这台娱乐很精彩，观众都看得很开心。", "explanation": "这里应该用〈节目〉。“娱乐”泛指让人放松的活动，不指某一台具体的节目。"}, {"text": "我们常常娱乐音乐，觉得很放松。", "explanation": "这里应该用〈欣赏〉。作动词时“娱乐”是使人快乐，不能直接带“音乐”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12306, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "娱乐", "is_correct": true, "explanation": "“娱乐”指老人喜欢的下棋、聊天这类消遣活动，与句意相符。"}, {"text": "工具", "is_correct": false, "explanation": "语义：下棋、聊天不是工具，“这样的工具”句意不通。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“这样的”后接消遣性的活动，“作业”是任务，不能与下棋、聊天并列。"}, {"text": "病痛", "is_correct": false, "explanation": "语义：下棋、聊天是老人喜欢的活动，不会是“病痛”，句意相反。"}], "explanations": {"娱乐": "“娱乐”指老人喜欢的下棋、聊天这类消遣活动，与句意相符。", "工具": "语义：下棋、聊天不是工具，“这样的工具”句意不通。", "作业": "搭配：“这样的”后接消遣性的活动，“作业”是任务，不能与下棋、聊天并列。", "病痛": "语义：下棋、聊天是老人喜欢的活动，不会是“病痛”，句意相反。"}, "sentence_index": 6, "correct_answer": "娱乐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶每天都娱乐花草，花草长得很好。", "explanation": "这里应该用〈照顾〉。作动词“娱乐”指使人快乐，不能用于花草。"}, {"text": "这场晚会有一只娱乐。", "explanation": "这里应该用〈项〉。“只”用于动物等，“娱乐”要用“项”或“种”来计量。"}, {"text": "他把娱乐放在了书架上。", "explanation": "这里误把“娱乐”当成〈实物〉来用。“娱乐”指让人快乐放松的活动，是抽象的，不能像物品一样放在书架上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12306, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我最喜欢娱乐是打篮球。", "corrected_sentence": "周末我最喜欢的娱乐是打篮球。", "error_description": "错误：“最喜欢娱乐”漏了“的”。正确：“最喜欢的娱乐”，“的”把修饰语和中心词“娱乐”连接起来。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12306, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一把很健康的娱乐。", "corrected_sentence": "这是一种很健康的娱乐。", "error_description": "错误：量词“把”用于有柄的东西，不能修饰“娱乐”。正确：“一种”，“娱乐”常用“种”或“项”来计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
