INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12308, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物存在或发展的规律、依据或理由。", "primary_collocate": null, "pronunciation": "dào lǐ", "ipa": "tau˥˩ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "叙事不只是为了娱乐，还能教人做人的道理。", "target_word": "道理", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "你说得有道理，我同意你的看法。", "target_word": "道理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个道理很简单，小孩子也懂。", "target_word": "道理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都认同这个道理。", "target_word": "道理", "complexity_tier": "T3", "furigana": "dào lǐ", "sentence_source": "generated"}, {"text": "这件事背后的道理其实很简单。", "target_word": "道理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水往低处流，这是自然的道理。", "target_word": "道理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话听起来很有道理。", "target_word": "道理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我明白了这个道理：努力才有收获。", "target_word": "道理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里讲了许多生活的道理。", "target_word": "道理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样做没有道理，大家都不同意。", "target_word": "道理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "大道理", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物的规律、依据或理由", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b98e791d-83a1-47e0-a7fc-a2d89d85f752') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12308, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "道理", "is_correct": true, "explanation": "正确：此处指做人应遵循的规律，与“教人做人”相合。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”口语随意，与书面的“叙事”语域不合，且不能说“做人的玩意儿”。"}, {"text": "房间", "is_correct": false, "explanation": "语义：“房间”是空间，不能被“教”，与“做人”所指的内容不合。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”不能与“做人”搭配，“做人的价格”不成词组。"}], "explanations": {"道理": "正确：此处指做人应遵循的规律，与“教人做人”相合。", "玩意儿": "语域：“玩意儿”口语随意，与书面的“叙事”语域不合，且不能说“做人的玩意儿”。", "房间": "语义：“房间”是空间，不能被“教”，与“做人”所指的内容不合。", "价格": "搭配：“价格”不能与“做人”搭配，“做人的价格”不成词组。"}, "sentence_index": 0, "correct_answer": "道理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条道理通向山顶。", "explanation": "这里应该用〈道路〉。道理是抽象的，不能指通向山顶的具体道路。"}, {"text": "这场戏的道理很逼真。", "explanation": "这里应该用〈道具〉。道理是抽象概念，不能用“逼真”形容，舞台上的物件要用〈道具〉。"}, {"text": "这个道理在山上修行。", "explanation": "这里应该用〈道士〉。道理不是人，不能在山上修行，修行的人要用〈道士〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12308, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道理", "is_correct": true, "explanation": "正确：“很有道理”指说得合理，修饰“话”。"}, {"text": "钱", "is_correct": false, "explanation": "语义：“钱”指财物，不能用来形容言语“听起来”的感觉。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“很有”后接“房子”不成词组，且与“话”无关。"}, {"text": "相貌", "is_correct": false, "explanation": "体貌：“相貌”指外貌，不能用于评价话语。"}], "explanations": {"道理": "正确：“很有道理”指说得合理，修饰“话”。", "钱": "语义：“钱”指财物，不能用来形容言语“听起来”的感觉。", "房子": "搭配：“很有”后接“房子”不成词组，且与“话”无关。", "相貌": "体貌：“相貌”指外貌，不能用于评价话语。"}, "sentence_index": 6, "correct_answer": "道理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他跟我讲了一本道理。", "explanation": "这里应该用〈个〉。〈本〉用于书册，道理是抽象名词，计量时用〈个〉。"}, {"text": "他说了一座道理。", "explanation": "这里应该用〈个〉。〈座〉用于山、建筑等大型物体，不用于计数道理。"}, {"text": "这颗道理很有用。", "explanation": "这里应该用〈个〉。〈颗〉用于粒状或圆形小物，道理应用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12308, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只道理我早就懂了。", "corrected_sentence": "这个道理我早就懂了。", "error_description": "错误：“道理”的量词应为“个”，此处误用“只”。应改为“这个道理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12308, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你的想法很道理。", "corrected_sentence": "你的想法很有道理。", "error_description": "错误：“很有道理”中缺少动词“有”，应为“很有道理”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
