INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12309, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指家族中辈分较高、年龄较大的人。", "primary_collocate": null, "pronunciation": "zhǎng bèi", "ipa": "ʈʂɑŋ˨˩˦ pei˥˩", "syllable_count": 2, "sentences": [{"text": "在一些地方，长辈晚上坐在火炉边给孩子们讲故事。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "见到长辈，要先问好。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，长辈会给孩子红包。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很尊敬家里的长辈。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要听长辈的话。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭时，长辈先坐下，我们再坐。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶是我们家最老的长辈。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她常常去看望生病的长辈。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日，我给长辈买了礼物。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在长辈面前，不要大声说话。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "长辈们", "label": "复数"}], "register": "中性", "sense_fingerprint": "家族中辈分高、年纪大的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b98e791d-83a1-47e0-a7fc-a2d89d85f752') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12309, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长辈", "is_correct": true, "explanation": "“长辈”指家族中辈分较高、年龄较大的人，与“晚上坐在火炉边给孩子们讲故事”的情境相符。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫是动物，不能坐在火炉边给孩子们讲故事，句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“坐在火炉边”与“桌子”不搭配，桌子不能坐，也不能讲故事。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有生命，不能给孩子们讲故事，句意不通。"}], "explanations": {"长辈": "“长辈”指家族中辈分较高、年龄较大的人，与“晚上坐在火炉边给孩子们讲故事”的情境相符。", "小猫": "语义：小猫是动物，不能坐在火炉边给孩子们讲故事，句意不通。", "桌子": "搭配：“坐在火炉边”与“桌子”不搭配，桌子不能坐，也不能讲故事。", "石头": "语义：石头没有生命，不能给孩子们讲故事，句意不通。"}, "sentence_index": 0, "correct_answer": "长辈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我周末常和长辈一起踢球。", "explanation": "这里应该用〈朋友〉。长辈指辈分较高的家人或长者，不能指同辈的朋友。"}, {"text": "妈妈做的长辈很好吃。", "explanation": "这里应该用〈点心〉。长辈指人，不能指可以吃的食物。"}, {"text": "我的长辈上课时总坐在我旁边。", "explanation": "这里应该用〈同桌〉。长辈指年长的人，不能指同班上课时坐在身边的同学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12309, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长辈", "is_correct": true, "explanation": "“长辈”指年长的家人，与“奶奶是我们家最老的”相符。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是人，“奶奶是我们家最老的汽车”句意不通。"}, {"text": "孩子", "is_correct": false, "explanation": "搭配：“最老的”不能修饰“孩子”，二者搭配不当。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是物件，不能指人，“奶奶是……闹钟”句意不通。"}], "explanations": {"长辈": "“长辈”指年长的家人，与“奶奶是我们家最老的”相符。", "汽车": "语义：汽车不是人，“奶奶是我们家最老的汽车”句意不通。", "孩子": "搭配：“最老的”不能修饰“孩子”，二者搭配不当。", "闹钟": "语义：闹钟是物件，不能指人，“奶奶是……闹钟”句意不通。"}, "sentence_index": 6, "correct_answer": "长辈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家来了一只长辈，很热情。", "explanation": "这里应该用〈位〉。长辈指人，量词应用“位”，“只”多用于动物。"}, {"text": "奶奶家的一本长辈很有趣。", "explanation": "这里应该用〈位〉。长辈指人，不能用“本”来计量。"}, {"text": "我们小区来了一台长辈。", "explanation": "这里应该用〈位〉。长辈指人，不能用“台”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12309, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家有两只长辈住在乡下。", "corrected_sentence": "我家有两位长辈住在乡下。", "error_description": "错误：量词“只”用于动物，指人时用错了量词，“两只长辈”不对。正确：“两位长辈”，指人的量词用“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12309, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家来了很多长辈们，都很热情。", "corrected_sentence": "我家来了很多长辈，都很热情。", "error_description": "错误：复数后缀“们”不能与“很多”这类表示数量多的词连用，“很多长辈们”不规范。正确：“很多长辈”，数量词直接修饰名词即可，不再加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12310, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12310, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12310, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "火炉是一种燃烧燃料（如煤、木柴）产生热量的器具，用于取暖或烹饪。", "primary_collocate": null, "pronunciation": "huǒ lú", "ipa": "xwɔ˨˩˦ lu˧˥", "syllable_count": 2, "sentences": [{"text": "在一些地方，长辈晚上坐在火炉边给孩子们讲故事。", "target_word": "火炉", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "冬天，我们围着火炉取暖。", "target_word": "火炉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶在火炉上烧了一壶水。", "target_word": "火炉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火炉里的木柴烧得很旺。", "target_word": "火炉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他往火炉里放了几块煤。", "target_word": "火炉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人坐在火炉旁边烤红薯。", "target_word": "火炉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里的小屋有一个旧火炉。", "target_word": "火炉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈用火炉做了一锅热汤。", "target_word": "火炉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火炉太热了，别靠得太近。", "target_word": "火炉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以前冬天很冷，很多人家都有火炉。", "target_word": "火炉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "火爐", "label": "繁体"}], "register": "中性", "sense_fingerprint": "烧煤或木柴、可取暖也可做饭的炉具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c071687f-a94f-4252-83c9-21d4428df7fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12310, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "火炉", "is_correct": true, "explanation": "正确：火炉是可以坐在旁边取暖、讲故事的实体，符合句意。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮在天上，人不能坐在它的边上给孩子们讲故事。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”是抽象概念，不能说“坐在天气边”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的，不能作为可以坐在旁边的参照物。"}], "explanations": {"火炉": "正确：火炉是可以坐在旁边取暖、讲故事的实体，符合句意。", "月亮": "语义：月亮在天上，人不能坐在它的边上给孩子们讲故事。", "天气": "搭配：“天气”是抽象概念，不能说“坐在天气边”。", "空气": "语义：空气是无形的，不能作为可以坐在旁边的参照物。"}, "sentence_index": 0, "correct_answer": "火炉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冬天的晚上，全家人围着桌子吃了一个火炉。", "explanation": "这里应该用〈火锅〉。火炉是取暖、烧东西的器具，不能吃；围着桌子吃的是火锅。"}, {"text": "他每天都在火炉里上班。", "explanation": "这里应该用〈办公室〉。火炉是取暖、烧东西的器具，不能在里面上班；上班要去办公室。"}, {"text": "夏天，妈妈把西瓜放进火炉里冷藏。", "explanation": "这里应该用〈冰箱〉。火炉用来取暖、烧东西，不能冷藏食物；冷藏要用冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "火炉", "is_correct": true, "explanation": "正确：山里的小屋里放着旧火炉，符合场景。"}, {"text": "地铁站", "is_correct": false, "explanation": "语义：地铁站是城市交通设施，与“山里的小屋”的场景不合。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“天空”不是可以“有一个旧”的具体物件，不能这样说。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：小屋里一般不会设电梯，与“山里的小屋”的场景不合。"}], "explanations": {"火炉": "正确：山里的小屋里放着旧火炉，符合场景。", "地铁站": "语义：地铁站是城市交通设施，与“山里的小屋”的场景不合。", "天空": "搭配：“天空”不是可以“有一个旧”的具体物件，不能这样说。", "电梯": "语义：小屋里一般不会设电梯，与“山里的小屋”的场景不合。"}, "sentence_index": 6, "correct_answer": "火炉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个火炉突然喷发，喷出了滚烫的岩浆。", "explanation": "这里应该用〈火山〉。喷发是火山的动作，火炉只用来取暖或烧东西，不会喷发。"}, {"text": "夏天的时候，我们打开火炉给屋子降温。", "explanation": "这里应该用〈空调〉。火炉用来取暖，不能降温；给屋子降温要用空调。"}, {"text": "他把火炉戴在手上取暖。", "explanation": "这里应该用〈手套〉。火炉是器具，不能戴在手上；取暖时戴的是手套。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷坐在一条火炉旁边看报纸。", "corrected_sentence": "爷爷坐在一个火炉旁边看报纸。", "error_description": "量词错误：“一条火炉”应为“一个火炉”。“条”多用于细长的东西，火炉用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把火炉上熬了一锅粥。", "corrected_sentence": "妈妈在火炉上熬了一锅粥。", "error_description": "介词误用：“把”后应接受事对象，而“火炉上”表示地点，应使用“在”。“把火炉上熬”不通，应为“在火炉上熬了一锅粥”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
