INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12312, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示两个动作或状态同时进行。", "primary_collocate": null, "pronunciation": "yì biān", "ipa": "i˥˩ pjɛn˥", "syllable_count": 2, "sentences": [{"text": "孩子们一边听，一边学习历史和传统。", "target_word": "一边", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "他一边吃饭，一边看电视。", "target_word": "一边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈一边做饭，一边听音乐。", "target_word": "一边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们一边走，一边聊天儿。", "target_word": "一边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她一边笑，一边说：“谢谢你！”", "target_word": "一边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "不要一边开车，一边打电话。", "target_word": "一边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明一边写作业，一边听着音乐。", "target_word": "一边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷一边喝茶，一边给我们讲故事。", "target_word": "一边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家一边唱歌，一边跳舞，非常高兴。", "target_word": "一边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一边说，一边把门打开了。", "target_word": "一边", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一邊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一边……一边……，两个动作同时进行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c071687f-a94f-4252-83c9-21d4428df7fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12312, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一边", "is_correct": true, "explanation": "正确答案。一边表示两个动作同时进行。"}, {"text": "一遍", "is_correct": false, "explanation": "声调：第二个音节 biàn（第四声）与 biān（第一声）声调不同，意思是一次、一回。"}, {"text": "一片", "is_correct": false, "explanation": "声母：第二个音节 piàn 的声母是 p，与 biān 的 b 不同，意思是一片。"}, {"text": "一天", "is_correct": false, "explanation": "声母：第二个音节 tiān 的声母是 t，与 biān 的 b 不同，意思是一天。"}, {"text": "一班", "is_correct": false, "explanation": "韵母：bān 没有 i 介音，与 biān 不同，意思是一个班级。"}], "explanations": {"一边": "正确答案。一边表示两个动作同时进行。", "一遍": "声调：第二个音节 biàn（第四声）与 biān（第一声）声调不同，意思是一次、一回。", "一片": "声母：第二个音节 piàn 的声母是 p，与 biān 的 b 不同，意思是一片。", "一天": "声母：第二个音节 tiān 的声母是 t，与 biān 的 b 不同，意思是一天。", "一班": "韵母：bān 没有 i 介音，与 biān 不同，意思是一个班级。"}, "sentence_index": null, "correct_answer": "一边"}, "level_3": {"options": [{"text": "一边", "is_correct": true, "explanation": "正确。“一边……一边……”表示两个动作同时进行，符合句意。"}, {"text": "因为", "is_correct": false, "explanation": "语法：“因为”后需接原因分句，不能直接放在“孩子们”和动词“听”之间。"}, {"text": "但是", "is_correct": false, "explanation": "语法：“但是”表示转折，不能直接放在“孩子们”和动词“听”之间。"}, {"text": "而且", "is_correct": false, "explanation": "语法：“而且”表示并列或递进，不能直接放在“孩子们”和动词“听”之间。"}], "explanations": {"一边": "正确。“一边……一边……”表示两个动作同时进行，符合句意。", "因为": "语法：“因为”后需接原因分句，不能直接放在“孩子们”和动词“听”之间。", "但是": "语法：“但是”表示转折，不能直接放在“孩子们”和动词“听”之间。", "而且": "语法：“而且”表示并列或递进，不能直接放在“孩子们”和动词“听”之间。"}, "sentence_index": 0, "correct_answer": "一边"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们一边到达了车站。", "explanation": "这里不能用“一边”。“一边”连接两个能持续进行的动作，表示同时进行；“到达”是一次性的动作，不能与“一边”搭配。"}, {"text": "他一边吃饭，然后看电视。", "explanation": "这里不能用“一边”。“一边”表示两个动作同时进行，而“吃饭”和“看电视”是先后发生的，应说“吃完饭再看电视”。"}, {"text": "他一边吃完了饭，一边去了学校。", "explanation": "这里不能用“一边”。“一边”要求两个能同时持续进行的动作，而“吃完了饭”和“去了学校”都是先后完成的一次性动作，不能同时进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12312, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一边", "is_correct": true, "explanation": "正确答案。一边表示两个动作同时进行。"}, {"text": "以便", "is_correct": false, "explanation": "声调：两个音节的声调都与 yì biān 不同（yǐ 第三声、biàn 第四声），意思是为了便于。"}, {"text": "一篇", "is_correct": false, "explanation": "声母：第二个音节 piān 的声母是 p，与 biān 的 b 不同，意思是一篇（文章）。"}, {"text": "一辩", "is_correct": false, "explanation": "声调：第二个音节 biàn（第四声）与 biān（第一声）声调不同，意思是辩论中的第一位辩手。"}], "explanations": {"一边": "正确答案。一边表示两个动作同时进行。", "以便": "声调：两个音节的声调都与 yì biān 不同（yǐ 第三声、biàn 第四声），意思是为了便于。", "一篇": "声母：第二个音节 piān 的声母是 p，与 biān 的 b 不同，意思是一篇（文章）。", "一辩": "声调：第二个音节 biàn（第四声）与 biān（第一声）声调不同，意思是辩论中的第一位辩手。"}, "sentence_index": null, "correct_answer": "一边"}, "level_3": {"options": [{"text": "一边", "is_correct": true, "explanation": "正确。“一边……一边……”表示两个动作同时进行，符合句意。"}, {"text": "所以", "is_correct": false, "explanation": "语法：“所以”表示结果，前面需有原因分句，不能直接放在“小明”和动词“写”之间。"}, {"text": "如果", "is_correct": false, "explanation": "语法：“如果”引出假设条件，后面需接结果分句，不能直接放在“小明”和动词“写”之间。"}, {"text": "而是", "is_correct": false, "explanation": "语法：“而是”需与前面的否定词配合（如“不是……而是”），此处没有否定，不能使用。"}], "explanations": {"一边": "正确。“一边……一边……”表示两个动作同时进行，符合句意。", "所以": "语法：“所以”表示结果，前面需有原因分句，不能直接放在“小明”和动词“写”之间。", "如果": "语法：“如果”引出假设条件，后面需接结果分句，不能直接放在“小明”和动词“写”之间。", "而是": "语法：“而是”需与前面的否定词配合（如“不是……而是”），此处没有否定，不能使用。"}, "sentence_index": 6, "correct_answer": "一边"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他说完一边把门打开了。", "explanation": "这里应该用〈接着〉。“一边”表示两个动作同时进行，而“说完”之后再“打开门”是先后关系。"}, {"text": "他一边摔倒了。", "explanation": "这里不能用“一边”。“一边”需要两个能同时进行的动作，“摔倒”是一次性的瞬间动作，且句中只有一个动作。"}, {"text": "两台机器一边停止运行。", "explanation": "这里不能用“一边”。“一边”表示两个动作同时持续进行，而“停止运行”是一次性的变化，不能与“一边”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12312, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐一边看书，一边的喝茶。", "corrected_sentence": "姐姐一边看书，一边喝茶。", "error_description": "助词误用：“一边的喝茶”中多余的“的”，应为“一边喝茶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12312, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷一边喝了茶，一边讲故事。", "corrected_sentence": "爷爷一边喝着茶，一边讲故事。", "error_description": "体貌错误：“喝了茶”表示动作已完成，与“一边”所表示的正在同时进行不合；应使用“着”，写作“喝着茶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
