INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12314, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指自己的家庭世代居住的地方，通常与个人有深厚的情感联系。", "primary_collocate": null, "pronunciation": "jiā xiāng", "ipa": "tɕja˥ ɕjɑŋ˥", "syllable_count": 2, "sentences": [{"text": "这些故事帮助他们了解自己的家族和家乡。", "target_word": "家乡", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我的家人几代都住在家乡，我很想念那里的饭菜。", "target_word": "家乡", "complexity_tier": "T3", "furigana": "wǒ de jiā rén jǐ dài dōu zhù zài jiā xiāng, wǒ hěn xiǎng niàn nà lǐ de fàn cài", "sentence_source": "generated"}, {"text": "我们家祖祖辈辈都住在家乡，我离开已经十年了。", "target_word": "家乡", "complexity_tier": "T3", "furigana": "wǒ men jiā zǔ zǔ bèi bèi dōu zhù zài jiā xiāng, wǒ lí kāi yǐ jīng shí nián le", "sentence_source": "generated"}, {"text": "春节我要回家乡看爸爸妈妈。", "target_word": "家乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里几代人都在家乡种茶，那里常常下雨。", "target_word": "家乡", "complexity_tier": "T3", "furigana": "jiā lǐ jǐ dài rén dōu zài jiā xiāng zhòng chá, nà lǐ cháng cháng xià yǔ", "sentence_source": "generated"}, {"text": "她带我们去看了她家几代人住过的家乡。", "target_word": "家乡", "complexity_tier": "T3", "furigana": "tā dài wǒ men qù kàn le tā jiā jǐ dài rén zhù guo de jiā xiāng", "sentence_source": "generated"}, {"text": "我们家世代住在这里，家乡的小吃很有名。", "target_word": "家乡", "complexity_tier": "T3", "furigana": "wǒ men jiā shì dài zhù zài zhè lǐ, jiā xiāng de xiǎo chī hěn yǒu míng", "sentence_source": "generated"}, {"text": "他在国外也常想起祖祖辈辈生活的家乡。", "target_word": "家乡", "complexity_tier": "T3", "furigana": "tā zài guó wài yě cháng xiǎng qǐ zǔ zǔ bèi bèi shēng huó de jiā xiāng", "sentence_source": "generated"}, {"text": "我家三代人都在家乡，春天到处都是花。", "target_word": "家乡", "complexity_tier": "T3", "furigana": "wǒ jiā sān dài rén dōu zài jiā xiāng, chūn tiān dào chù dōu shì huā", "sentence_source": "generated"}, {"text": "老人一直住在家乡，没有搬过家。", "target_word": "家乡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家乡话", "label": "复合"}, {"form": "家乡菜", "label": "复合"}, {"form": "家鄉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "家庭世代居住、带有情感的故乡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c071687f-a94f-4252-83c9-21d4428df7fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12314, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "家乡", "is_correct": true, "explanation": "正确答案。家乡（jiāxiāng）指家族世代居住或自己出生长大的地方。"}, {"text": "假象", "is_correct": false, "explanation": "jiǎxiàng 与 jiāxiāng 两个音节声调都不同，意思是表面上的假象。"}, {"text": "假想", "is_correct": false, "explanation": "两个音节的声调都不同（jiǎxiǎng），意思是假设、想象。"}, {"text": "嘉祥", "is_correct": false, "explanation": "只有第二音节声调不同（xiáng 第二声，xiāng 第一声），意思是吉祥、好兆头。"}], "explanations": {"家乡": "正确答案。家乡（jiāxiāng）指家族世代居住或自己出生长大的地方。", "假象": "jiǎxiàng 与 jiāxiāng 两个音节声调都不同，意思是表面上的假象。", "假想": "两个音节的声调都不同（jiǎxiǎng），意思是假设、想象。", "嘉祥": "只有第二音节声调不同（xiáng 第二声，xiāng 第一声），意思是吉祥、好兆头。"}, "sentence_index": null, "correct_answer": "家乡"}, "level_3": {"options": [{"text": "家乡", "is_correct": true, "explanation": "正确：家乡指家族世代居住的地方，与“家族”并列，语义相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”能被“了解”，但与“家族”并列、作为故事帮助他们了解的内容，句意不合。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”不是人，也不是地方，与“家族”并列作为故事帮助他们了解的内容，句意不通。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学习任务，与家族无关，句子说不通。"}], "explanations": {"家乡": "正确：家乡指家族世代居住的地方，与“家族”并列，语义相合。", "天气": "语义：“天气”能被“了解”，但与“家族”并列、作为故事帮助他们了解的内容，句意不合。", "电脑": "语义：“电脑”不是人，也不是地方，与“家族”并列作为故事帮助他们了解的内容，句意不通。", "作业": "语义：“作业”是学习任务，与家族无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "家乡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套房子的家乡在二楼，客厅很大。", "explanation": "这里的“家乡”指住的房子，不是出生或家族世代居住的地方，这个意思不能用“家乡”。"}, {"text": "我用家乡给他打电话。", "explanation": "这里应该用〈手机〉。家乡是地方，不能作为打电话的工具。"}, {"text": "他穿着家乡去上班。", "explanation": "这里应该用〈衣服〉。“穿”的对象是衣服、鞋等，家乡是地方，不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12314, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家乡", "is_correct": true, "explanation": "正确：家乡指家族世代居住的地方，“家乡的小吃”指当地的特色食品。"}, {"text": "教室", "is_correct": false, "explanation": "语义：“教室”是上课的地方，不出产小吃，“教室的小吃”说不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家电，不是地区，“冰箱的小吃”没有意义。"}, {"text": "脸", "is_correct": false, "explanation": "体貌：“脸”是身体部位，不能说“脸的小吃”，与地方特产无关。"}], "explanations": {"家乡": "正确：家乡指家族世代居住的地方，“家乡的小吃”指当地的特色食品。", "教室": "语义：“教室”是上课的地方，不出产小吃，“教室的小吃”说不通。", "冰箱": "语义：“冰箱”是家电，不是地区，“冰箱的小吃”没有意义。", "脸": "体貌：“脸”是身体部位，不能说“脸的小吃”，与地方特产无关。"}, "sentence_index": 6, "correct_answer": "家乡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把钱存进家乡。", "explanation": "这里应该用〈银行〉。家乡指出生或家族居住的地方，不能用来存钱。"}, {"text": "我在复习家乡。", "explanation": "这里应该用〈课本〉。“复习”的对象是学过的内容，家乡是地方，不能复习。"}, {"text": "我抱着家乡睡觉。", "explanation": "这里应该用〈枕头〉。“抱着”的对象是能拿在手里的东西，家乡是地方，不能抱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12314, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直想念那条家乡。", "corrected_sentence": "他一直想念那个家乡。", "error_description": "错误：“那条家乡”；正确：“那个家乡”。“家乡”指地方，量词用“个”，“条”用于河流、道路等长条形事物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12314, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我去过家乡很多次过。", "corrected_sentence": "我去过家乡很多次。", "error_description": "错误：句末多出一个“过”；正确：“我去过家乡很多次。”。“过”表示经历，紧跟动词“去”，句末不能再加“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
