INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12317, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12317, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "祖先是指一个家族或民族中较早的前辈，通常指已经去世的上几代人。", "primary_collocate": null, "pronunciation": "zǔ xiān", "ipa": "tsu˨˩˦ ɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "这种非文本化的历史表达，在许多原住民社会中体现为“梦世纪”（Dreamtime）式的宇宙观叙述，其中祖先的行动与自然地貌的形成互为映射，时间并非线性推进，而是以神话事件为节点循环重启。", "target_word": "祖先", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "比如，有些部落没有书本，但他们的祖先是谁、从哪里来，都是通过故事记住的。", "target_word": "祖先", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "我们的祖先很早就住在这里。", "target_word": "祖先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每年清明节，我们都去祭拜祖先。", "target_word": "祖先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的祖先是从山东搬来的。", "target_word": "祖先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人想知道自己祖先的故事。", "target_word": "祖先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "祖先留下的老房子还在村口。", "target_word": "祖先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年时，全家人给祖先上香。", "target_word": "祖先", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个民族的祖先以打鱼为生。", "target_word": "祖先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷常给孩子们讲祖先的故事。", "target_word": "祖先", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "祖先们", "label": "复数"}, {"form": "一位祖先", "label": "量词（位）"}], "register": "中性", "sense_fingerprint": "祖先：家族或民族中已去世的较早几代前辈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94fd5d6a-ee47-45b7-8109-ed74731efdc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12317, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "祖先", "is_correct": true, "explanation": "正确：「祖先的行动与自然地貌的形成互为映射」指有行动能力的前辈，与句意相符。"}, {"text": "神话", "is_correct": false, "explanation": "语义：「神话」是故事，没有「行动」，不能与地貌形成互为映射的关系。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：「行动」要求有意志的主体，不能说「时间的行动」。"}, {"text": "节日", "is_correct": false, "explanation": "语义：「节日」不能主动参与地貌的形成，句意不通。"}], "explanations": {"祖先": "正确：「祖先的行动与自然地貌的形成互为映射」指有行动能力的前辈，与句意相符。", "神话": "语义：「神话」是故事，没有「行动」，不能与地貌形成互为映射的关系。", "时间": "搭配：「行动」要求有意志的主体，不能说「时间的行动」。", "节日": "语义：「节日」不能主动参与地貌的形成，句意不通。"}, "sentence_index": 0, "correct_answer": "祖先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公园里的祖先在下棋，很多人在旁边看。", "explanation": "这里应该用〈老人〉。祖先指已去世的前辈，不能指在公园里下棋的活人。"}, {"text": "我的祖先下个月就要结婚了。", "explanation": "这里的「祖先」被误用为「活着的家人」的意思。祖先指已去世的前辈，指活着的亲人应该用〈家人〉。"}, {"text": "我每天给祖先发短信，告诉他们我的近况。", "explanation": "这里的「祖先」被误用为「能收短信的活人」的意思。祖先已经去世，无法收短信，要联系的应该是〈家人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12317, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "祖先", "is_correct": true, "explanation": "正确：「祖先留下的老房子」指前辈留下的房屋，句意通顺。"}, {"text": "天空", "is_correct": false, "explanation": "语义：「天空」不能留下老房子，句意不通。"}, {"text": "风", "is_correct": false, "explanation": "语义：「风」不能留下房子，与「老房子」的语境不合。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：「留下」的主语多为人或事件，「石头留下的老房子」不成立。"}], "explanations": {"祖先": "正确：「祖先留下的老房子」指前辈留下的房屋，句意通顺。", "天空": "语义：「天空」不能留下老房子，句意不通。", "风": "语义：「风」不能留下房子，与「老房子」的语境不合。", "石头": "搭配：「留下」的主语多为人或事件，「石头留下的老房子」不成立。"}, "sentence_index": 6, "correct_answer": "祖先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家有一只祖先在远方生活。", "explanation": "这里有两处问题：指人的「祖先」要用「位」而非「只」；此外祖先指已去世的前辈，指在远方生活的亲人应该用〈家人〉。"}, {"text": "我的祖先坏了，明天要修。", "explanation": "这里的「祖先」被误用为「机器、物品」的意思。祖先只指已去世的前辈，不能指物品，这里应该用〈电脑〉。"}, {"text": "这是我的祖先，他今年五岁。", "explanation": "这里应该用〈后代〉。祖先指已去世的前辈，不能指现在的孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12317, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家的祖先中有一只当过大官。", "corrected_sentence": "我们家的祖先中有一位当过大官。", "error_description": "指人的「祖先」，量词应为「位」，不能用「只」。「一只祖先」错误，正确为「一位祖先」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12317, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每个祖先们都很勇敢。", "corrected_sentence": "每个祖先都很勇敢。", "error_description": "「每个」与「们」不能同用，「每个」修饰的名词后不加「们」。「每个祖先们」错误，正确为「每个祖先」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
