INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12318, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "脸上表现出的喜怒哀乐等神态", "primary_collocate": null, "pronunciation": "biǎo qíng", "ipa": "piɑu˨˩˦ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "讲故事的人用语言、表情和手势让别人理解他的想法。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他看着成绩单，一脸难过的表情。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看她的表情就知道她很生气。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟做了一个很好笑的表情。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的表情慢慢变得轻松了。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们脸上都是高兴的表情。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听完这个笑话，大家的表情都很快乐。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没有说话，但是表情说明了一切。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在门口，表情有点紧张。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的表情告诉我，情况不太好。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "表情包", "label": "复合"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "表情|名词|脸上表现出的喜怒哀乐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30f964d1-cfc8-4ab7-9f81-00f306f69457') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12318, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表情", "is_correct": true, "explanation": "正确：“表情”指脸上的神态，与“语言、手势”并列，都是表达想法的方式。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图不是讲故事时传达想法的方式，与“语言、手势”并列说不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不能用来表达想法，与“语言、手势”并列说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指身体的高矮，不是表达想法的手段。"}], "explanations": {"表情": "正确：“表情”指脸上的神态，与“语言、手势”并列，都是表达想法的方式。", "地图": "语义：地图不是讲故事时传达想法的方式，与“语言、手势”并列说不通。", "价格": "语义：价格不能用来表达想法，与“语言、手势”并列说不通。", "身高": "体貌：“身高”指身体的高矮，不是表达想法的手段。"}, "sentence_index": 0, "correct_answer": "表情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个市场的表情一直很稳定。", "explanation": "这里应该用〈形势〉。市场的局面要说形势；表情指脸上的神态，不能用来形容局面。"}, {"text": "这份表情明天要交给老师，你别忘了。", "explanation": "这里应该用〈文件〉。需要交出去的纸件要说文件；表情指脸上的神态。"}, {"text": "他脸上挂着一把生气的表情。", "explanation": "这里应该用〈种〉。“把”用于有柄的物件，表情应配“种”或“副”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc597bcd-5819-488a-bfc6-a09fdb9ef0d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12318, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表情", "is_correct": true, "explanation": "正确：“表情”指脸上的神态，与“快乐”搭配，说明大家听后露出高兴的样子。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人的情绪，“大家的天气都很快乐”说不通。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：“快乐”不用来形容成绩，句中的对象应是人的神态或心情。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”指身体的分量，不能被“快乐”修饰，也与笑话无关。"}], "explanations": {"表情": "正确：“表情”指脸上的神态，与“快乐”搭配，说明大家听后露出高兴的样子。", "天气": "语义：天气不是人的情绪，“大家的天气都很快乐”说不通。", "成绩": "搭配：“快乐”不用来形容成绩，句中的对象应是人的神态或心情。", "体重": "体貌：“体重”指身体的分量，不能被“快乐”修饰，也与笑话无关。"}, "sentence_index": 6, "correct_answer": "表情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把心里的表情写进了日记里。", "explanation": "这里应该用〈感受〉。心里的体会要说感受；表情指脸上的神态。"}, {"text": "我们把成绩填在一张表情里。", "explanation": "这里应该用〈表格〉。填写成绩的纸要说表格；表情指脸上的神态。"}, {"text": "他对这个班级有很深的表情。", "explanation": "这里应该用〈感情〉。对集体的情意要说感情；表情指脸上的神态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc597bcd-5819-488a-bfc6-a09fdb9ef0d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12318, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他看着我，脸上带着一根开心的表情。", "corrected_sentence": "他看着我，脸上带着一种开心的表情。", "error_description": "量词用错：“表情”应配“种”，不能配“根”。应说“一种开心的表情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc597bcd-5819-488a-bfc6-a09fdb9ef0d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12318, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他看完信，脸上的表情慢慢了变。", "corrected_sentence": "他看完信，脸上的表情慢慢变了。", "error_description": "了的位置错：“了”应放在动词“变”之后，表示变化已经发生，不能放在“变”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc597bcd-5819-488a-bfc6-a09fdb9ef0d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
