INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12319, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用手做出的各种姿势或动作，用来表达意思或情感。", "primary_collocate": null, "pronunciation": "shǒu shì", "ipa": "ʂou˨˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "讲故事的人用语言、表情和手势让别人理解他的想法。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他用手势告诉我，这里不能说话。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师做了一个手势，让我们坐下。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察的手势是让车停下来。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听不懂，但是看懂了他的手势。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说话的时候，她喜欢用很多手势。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手势的意思是“你真棒”。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用手势让孩子别害怕。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同国家的手势，意思可能不一样。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在远处做手势，叫我过去。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "手勢", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用手做的姿势，表达意思或情感", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c071687f-a94f-4252-83c9-21d4428df7fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12319, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手势", "is_correct": true, "explanation": "正确答案。手势（shǒushì）指用手做的动作，用来表达意思或情感。"}, {"text": "收视", "is_correct": false, "explanation": "第一音节声调不同（shōu 第一声，shǒu 第三声），意思是观众收看电视节目的情况。"}, {"text": "首饰", "is_correct": false, "explanation": "第二音节由第四声变为轻声（shǒushi），意思是戴在身上的装饰品。"}, {"text": "收拾", "is_correct": false, "explanation": "两个音节的声调都不同（shōushi），意思是整理、收拾东西。"}, {"text": "收市", "is_correct": false, "explanation": "第一音节声调不同（shōushì），意思是交易市场结束营业。"}], "explanations": {"手势": "正确答案。手势（shǒushì）指用手做的动作，用来表达意思或情感。", "收视": "第一音节声调不同（shōu 第一声，shǒu 第三声），意思是观众收看电视节目的情况。", "首饰": "第二音节由第四声变为轻声（shǒushi），意思是戴在身上的装饰品。", "收拾": "两个音节的声调都不同（shōushi），意思是整理、收拾东西。", "收市": "第一音节声调不同（shōushì），意思是交易市场结束营业。"}, "sentence_index": null, "correct_answer": "手势"}, "level_3": {"options": [{"text": "手势", "is_correct": true, "explanation": "正确：手势是用手做的动作，与“语言、表情”并列，都是表达方式。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是表达想法的方式，与“语言、表情”并列说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指身体的高矮胖瘦，不能用来表达想法。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：“鞋子”与表达想法无关，句子说不通。"}], "explanations": {"手势": "正确：手势是用手做的动作，与“语言、表情”并列，都是表达方式。", "天气": "语义：“天气”不是表达想法的方式，与“语言、表情”并列说不通。", "身材": "体貌：“身材”指身体的高矮胖瘦，不能用来表达想法。", "鞋子": "语义：“鞋子”与表达想法无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "手势"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她露出了开心的手势。", "explanation": "这里应该用〈表情〉。“露出”搭配表情，手势是用手做的动作，不能这样用。"}, {"text": "妈妈戴上一个漂亮的手势，去参加婚礼。", "explanation": "这里应该用〈戒指〉。“戴”搭配戒指、帽子等，手势是用手做的动作，不能戴。"}, {"text": "舞蹈演员转了一圈，穿上了一个手势。", "explanation": "这里应该用〈裙子〉。“穿”搭配衣服、裙子，手势是动作，不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12319, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手势", "is_correct": true, "explanation": "正确：手势能传达意思，“这个手势的意思是……”说得通。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：“饺子”是食物，不能表达“你真棒”的意思。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是通讯工具，本身不表达意思，句子不成立。"}, {"text": "脸", "is_correct": false, "explanation": "体貌：“脸”是身体部位，不能说它的意思是某句话。"}], "explanations": {"手势": "正确：手势能传达意思，“这个手势的意思是……”说得通。", "饺子": "语义：“饺子”是食物，不能表达“你真棒”的意思。", "手机": "语义：“手机”是通讯工具，本身不表达意思，句子不成立。", "脸": "体貌：“脸”是身体部位，不能说它的意思是某句话。"}, "sentence_index": 6, "correct_answer": "手势"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在远处开手势，叫我过去。", "explanation": "这里应该用〈灯〉。“开”搭配灯、门等，手势不能被“开”。"}, {"text": "他在远处按手势，叫我过去。", "explanation": "这里应该用〈门铃〉。“按”搭配门铃、按钮，手势不能被“按”。"}, {"text": "上课的时候，手势响了。", "explanation": "这里应该用〈铃声〉。“响”的主语是声音，手势是用手做的动作，不能发出响声。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12319, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他做了一条手势，我就明白了。", "corrected_sentence": "他做了一个手势，我就明白了。", "error_description": "错误：“一条”；正确：“一个”。手势是动作，量词用“个”，“条”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12319, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我手势跟他打招呼。", "corrected_sentence": "我用手势跟他打招呼。", "error_description": "错误：“手势跟他打招呼”缺少介词“用”；正确：“用手势”。“用”引出工具，手势作为工具时要加“用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12320, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12320, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12320, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "提出疑问。", "primary_collocate": null, "pronunciation": "tí wèn", "ipa": "tʰi˧˥ wən˥˩", "syllable_count": 2, "sentences": [{"text": "听的人也能通过提问和讨论表达自己的看法。", "target_word": "提问", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "老师讲完以后，学生可以提问。", "target_word": "提问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家举手提问，不要直接说话。", "target_word": "提问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很喜欢在课上提问。", "target_word": "提问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议最后有十分钟时间让大家提问。", "target_word": "提问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者向市长提问，市长认真回答。", "target_word": "提问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们对什么都好奇，总爱提问。", "target_word": "提问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有不明白的地方，可以随时提问。", "target_word": "提问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师一提问，大家都不敢说话。", "target_word": "提问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天没有提问，因为都听懂了。", "target_word": "提问", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提问了", "label": "体标"}, {"form": "提问过", "label": "体标"}], "register": "中性", "sense_fingerprint": "提出疑问；请人解答不明白的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ae1b019-e3ac-4d0f-b5df-a846d13cad7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12320, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提问", "is_correct": true, "explanation": "正确。“提问”指提出疑问，填入后“通过提问和讨论表达看法”通顺。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”是清理场地，不能与“讨论”并列作表达看法的方式，句子不通。"}, {"text": "听", "is_correct": false, "explanation": "语义：“听”是接收信息，与“表达自己的看法”相反，且与“听的人”重复。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”指栽培植物，不能与“讨论”并列作表达看法的方式。"}], "explanations": {"提问": "正确。“提问”指提出疑问，填入后“通过提问和讨论表达看法”通顺。", "打扫": "搭配：“打扫”是清理场地，不能与“讨论”并列作表达看法的方式，句子不通。", "听": "语义：“听”是接收信息，与“表达自己的看法”相反，且与“听的人”重复。", "种植": "搭配：“种植”指栽培植物，不能与“讨论”并列作表达看法的方式。"}, "sentence_index": 0, "correct_answer": "提问"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在会上提问了三条建议。", "explanation": "这里应该用〈提出〉。提问指提出疑问，建议要说“提出”，不能说“提问建议”。"}, {"text": "他在杂志上提问了一篇文章。", "explanation": "这里应该用〈发表〉。提问只用于提出疑问，文章要说“发表”。"}, {"text": "政府提问了一部新法律。", "explanation": "这里应该用〈颁布〉。提问不能用于法律，法律要说“颁布”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12320, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提问", "is_correct": true, "explanation": "正确。“总爱提问”表示习惯，与“对什么都好奇”相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“对什么都好奇”的探究心理相冲突。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：“发呆”是不动脑筋，与“对什么都好奇”的主动探究矛盾。"}, {"text": "生病", "is_correct": false, "explanation": "搭配：“总爱生病”不是正常说法，不能表示孩子的习惯。"}], "explanations": {"提问": "正确。“总爱提问”表示习惯，与“对什么都好奇”相符。", "睡觉": "语义：“睡觉”与“对什么都好奇”的探究心理相冲突。", "发呆": "语义：“发呆”是不动脑筋，与“对什么都好奇”的主动探究矛盾。", "生病": "搭配：“总爱生病”不是正常说法，不能表示孩子的习惯。"}, "sentence_index": 6, "correct_answer": "提问"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "记者去年提问了这个村子。", "explanation": "这里应该用〈访问〉。提问指提出疑问，去某地了解情况要说“访问”，地点不能作提问的宾语。"}, {"text": "老师提问了这本好书。", "explanation": "这里应该用〈推荐〉。提问不能用于书籍，推荐好书要说“推荐”。"}, {"text": "这家公司提问了一项新技术。", "explanation": "这里应该用〈研发〉。提问指提出疑问，研制新技术要说“研发”，技术不能作提问的宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12320, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他刚才向老师提问着一个问题。", "corrected_sentence": "他刚才向老师提问了一个问题。", "error_description": "体标错误：“刚才”指刚完成的动作，应用“了”；“着”表示持续状态，不能用于这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12320, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个问题很难，我们可以下课后向老师提问着。", "corrected_sentence": "这个问题很难，我们可以下课后向老师提问。", "error_description": "体标错误：“着”表示动作持续的状态，与“可以”表示的将来可能不相容，应去掉“着”，说“可以向老师提问”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12323, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "动摇", "is_correct": true, "explanation": "正确。“动摇”指立场或意志不稳，与“坚决不改变”相反，是反义词。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”表示随意走走，与“坚持”不构成反义关系。"}, {"text": "支持", "is_correct": false, "explanation": "“支持”表示帮助或赞成，与“坚持”不构成反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”表示探讨钻研，与“坚持”不构成反义关系。"}], "correct_answer": "动摇", "explanations": {"动摇": "正确。“动摇”指立场或意志不稳，与“坚决不改变”相反，是反义词。", "散步": "“散步”表示随意走走，与“坚持”不构成反义关系。", "支持": "“支持”表示帮助或赞成，与“坚持”不构成反义关系。", "研究": "“研究”表示探讨钻研，与“坚持”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12323, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "动摇", "is_correct": true, "explanation": "正确。“动摇”指立场或意志不稳，与“坚决不改变”相反，是反义词。"}, {"text": "观看", "is_correct": false, "explanation": "“观看”表示看，与“坚持”不构成反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”表示用脑子考虑问题，与“坚持”不构成反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "“旅行”表示出游，与“坚持”不构成反义关系。"}], "correct_answer": "动摇", "explanations": {"动摇": "正确。“动摇”指立场或意志不稳，与“坚决不改变”相反，是反义词。", "观看": "“观看”表示看，与“坚持”不构成反义关系。", "思考": "“思考”表示用脑子考虑问题，与“坚持”不构成反义关系。", "旅行": "“旅行”表示出游，与“坚持”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12323, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指坚决保持、维护或进行，不放弃或改变。", "primary_collocate": null, "pronunciation": "jiān chí", "ipa": "tɕjɛn˥ ʈʂʰɨ˧˥", "syllable_count": 2, "sentences": [{"text": "现在，虽然很多人通过电视和手机看故事，但还是有不少地方坚持用口头的方式讲。", "target_word": "坚持", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他坚持自己的看法，不想改变。", "target_word": "坚持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生坚持让病人多休息。", "target_word": "坚持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈坚持要自己做饭。", "target_word": "坚持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坚持这样做，因为它是对的。", "target_word": "坚持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然大家都不同意，他还是坚持原来的计划。", "target_word": "坚持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人坚持不用手机，只写信。", "target_word": "坚持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她坚持说自己没有错。", "target_word": "坚持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司坚持用最好的材料。", "target_word": "坚持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我坚持过这个意见，可是没人听。", "target_word": "坚持", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "坚持了", "label": "体标"}, {"form": "坚持着", "label": "体标"}, {"form": "坚持过", "label": "体标"}], "register": "中性", "sense_fingerprint": "坚决保持自己的看法、做法或要求，不肯改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ae1b019-e3ac-4d0f-b5df-a846d13cad7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12323, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "坚持", "is_correct": true, "explanation": "正确。“还是有不少地方坚持用口头的方式讲”表示仍然保持的意思。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”与“但还是”的延续语义矛盾，不能表示仍然用口头方式讲。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“停止”与“还是”表示延续的意思相反。"}, {"text": "发明", "is_correct": false, "explanation": "搭配：“发明”用于创造事物，不能说“发明用口头的方式讲”。"}], "explanations": {"坚持": "正确。“还是有不少地方坚持用口头的方式讲”表示仍然保持的意思。", "放弃": "语义：“放弃”与“但还是”的延续语义矛盾，不能表示仍然用口头方式讲。", "停止": "语义：“停止”与“还是”表示延续的意思相反。", "发明": "搭配：“发明”用于创造事物，不能说“发明用口头的方式讲”。"}, "sentence_index": 0, "correct_answer": "坚持"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他坚持一个苹果。", "explanation": "这里应该用〈吃〉。坚持表示坚决保持看法或做法，不能带食物作宾语，吃苹果要说“吃”。"}, {"text": "这段时间物价坚持稳定。", "explanation": "这里应该用〈维持〉。坚持表示坚决保持看法或做法，人的态度和立场才能坚持；物价保持平稳要说“维持”。"}, {"text": "他坚持很多书。", "explanation": "这里应该用〈拥有〉。坚持不能表示拥有物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12323, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坚持", "is_correct": true, "explanation": "正确。“老人坚持不用手机，只写信”中，“坚持”表示坚决保持不用手机的做法。"}, {"text": "购买", "is_correct": false, "explanation": "语义：“购买”的对象是可以买的东西，“购买不用手机”自相矛盾。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”针对已坏的东西，与“不用手机”的语境无关。"}, {"text": "生产", "is_correct": false, "explanation": "搭配：“生产”用于制造物品，不能与“不用手机”搭配。"}], "explanations": {"坚持": "正确。“老人坚持不用手机，只写信”中，“坚持”表示坚决保持不用手机的做法。", "购买": "语义：“购买”的对象是可以买的东西，“购买不用手机”自相矛盾。", "修理": "语义：“修理”针对已坏的东西，与“不用手机”的语境无关。", "生产": "搭配：“生产”用于制造物品，不能与“不用手机”搭配。"}, "sentence_index": 6, "correct_answer": "坚持"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我坚持了这张照片。", "explanation": "这里应该用〈保留〉。坚持表示坚决保持看法或做法，不能用于保存物品。"}, {"text": "他坚持了很多邮票。", "explanation": "这里应该用〈收藏〉。坚持不能用于收集物品，收藏邮票要说“收藏”。"}, {"text": "他坚持了一台新电脑。", "explanation": "这里应该用〈购买〉。坚持表示坚决保持看法或做法，不能用于获得物品，买电脑要说“购买”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12323, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "面对大家的反对，她坚持特别好，没有放弃。", "corrected_sentence": "面对大家的反对，她坚持得特别好，没有放弃。", "error_description": "漏掉“得”：“坚持”后接程度补语“特别好”时要用“坚持得”，不能直接说“坚持特别好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12323, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈坚持我早点睡。", "corrected_sentence": "妈妈坚持让我早点睡。", "error_description": "漏掉“让”：“坚持”后接兼语句时要说“坚持让某人做某事”，不能直接说“坚持我早点睡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
