INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12328, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12328, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人类文明是指人类在历史发展过程中创造的物质财富和精神财富的总和，包括文化、科技、社会制度等。", "primary_collocate": null, "pronunciation": "rén lèi wén míng", "ipa": "ɻən˧˥ leɪ˥˩ wən˧˥ miŋ˧˥", "syllable_count": 4, "sentences": [{"text": "在极端干旱的环境中，水资源的稀缺性催生了人类文明最为精妙的生存智慧。", "target_word": "人类文明", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "在人类文明的漫长演进中，叙事作为最古老的认知方式之一，始终承载着超越语言本身的文化重量。", "target_word": "人类文明", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "文字的出现，是人类文明的一大进步。", "target_word": "人类文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类文明的发展离不开交流与合作。", "target_word": "人类文明", "complexity_tier": "T3", "furigana": "rén lèi wén míng", "sentence_source": "generated"}, {"text": "我们要保护人类文明留下来的历史遗产。", "target_word": "人类文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里保存着人类文明的许多宝贵记录。", "target_word": "人类文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火的使用让人类文明向前走了一大步。", "target_word": "人类文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书籍是传播人类文明的重要工具。", "target_word": "人类文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争会毁掉人类文明几千年的成果。", "target_word": "人类文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同国家的人一起推动了人类文明的发展。", "target_word": "人类文明", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人類文明", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人类文明：人类历史上创造的物质与精神财富的总和", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699a7efa-2ffe-43e6-84c2-b247b5d73d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12328, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人类文明", "is_correct": true, "explanation": "正确：人类文明指人类创造的物质与精神财富，能够积累出精妙的生存智慧。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是人造工具，不会自行积累“生存智慧”，与干旱环境中的生存语境不合。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车与“生存智慧”无关，不能被“催生”出来。"}, {"text": "螺丝", "is_correct": false, "explanation": "语义：螺丝是金属零件，不会催生“生存智慧”。"}], "explanations": {"人类文明": "正确：人类文明指人类创造的物质与精神财富，能够积累出精妙的生存智慧。", "电脑": "语义：电脑是人造工具，不会自行积累“生存智慧”，与干旱环境中的生存语境不合。", "汽车": "语义：汽车与“生存智慧”无关，不能被“催生”出来。", "螺丝": "语义：螺丝是金属零件，不会催生“生存智慧”。"}, "sentence_index": 0, "correct_answer": "人类文明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对中国人类文明很熟悉。", "explanation": "这里应该用〈历史〉。人类文明指全人类创造的财富总和，不能用来指一个国家的历史。"}, {"text": "这个国家的人类文明很稳定。", "explanation": "这里应该用〈社会制度〉。社会制度可以稳定或动荡，人类文明是全人类创造的财富总和，不能用“稳定”来描述。"}, {"text": "这座城市的人类文明风格很独特。", "explanation": "这里应该用〈建筑〉。建筑有自己的风格，人类文明是全人类财富的总和，不能用来指某座城市的风格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12328, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人类文明", "is_correct": true, "explanation": "正确：火的使用推动了人类文明的进步，符合“向前走了一大步”的语境。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱与火的使用无关，不能“向前走了一大步”。"}, {"text": "雪", "is_correct": false, "explanation": "语义：雪象征寒冷，与火的使用相反，不能推动进步。"}, {"text": "大海", "is_correct": false, "explanation": "配价：“向前走了一大步”需要有行动能力的主体，大海不能作主语。"}], "explanations": {"人类文明": "正确：火的使用推动了人类文明的进步，符合“向前走了一大步”的语境。", "冰箱": "语义：冰箱与火的使用无关，不能“向前走了一大步”。", "雪": "语义：雪象征寒冷，与火的使用相反，不能推动进步。", "大海": "配价：“向前走了一大步”需要有行动能力的主体，大海不能作主语。"}, "sentence_index": 6, "correct_answer": "人类文明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们应该尊重不同民族的人类文明。", "explanation": "这里应该用〈文化〉。人类文明指全人类的财富总和，是一个整体，不说“不同民族的人类文明”。"}, {"text": "这位画家的人类文明风格很独特。", "explanation": "这里应该用〈艺术〉。艺术风格属于个人作品，人类文明是全人类财富的总和，不能用来描述某位画家的风格。"}, {"text": "博物馆里陈列着很多古代人类文明。", "explanation": "这里应该用〈文物〉。文物是具体的器物，人类文明是抽象的财富总和，不能像文物一样陈列。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12328, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人类文明们在过去几百年里发展得很快。", "corrected_sentence": "人类文明在过去几百年里发展得很快。", "error_description": "错误在“们”：“人类文明”是抽象的集合概念，不能加复数词尾“们”，应去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12328, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该保护人类文明地成果。", "corrected_sentence": "我们应该保护人类文明的成果。", "error_description": "错误在“的”：“人类文明”修饰名词“成果”时应用结构助词“的”，说“人类文明的成果”；用“地”修饰名词不符合规范，不能说“人类文明地成果”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
