INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12330, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12330, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某事物在文化或情感上具有的重要性", "primary_collocate": null, "pronunciation": "zhòng liàng", "ipa": "tʂʊŋ˥˩ ljɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "在人类文明的漫长演进中，叙事作为最古老的认知方式之一，始终承载着超越语言本身的文化重量。", "target_word": "重量", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座老城的历史很有重量。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗的文化重量不能小看。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的这句话在我心里很有重量。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张旧照片对全家人来说很有重量。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里每个故事都带着历史的重量。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日对他们民族有特别的重量。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间让这些老歌有了文化的重量。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的名字在这座城市里很有重量。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传统文化的重量，年轻人也要明白。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "比喻义：事物在文化、历史或情感上的分量与重要性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76ee065-26df-4d6a-b94a-ac532d78a03d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12330, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重量", "is_correct": true, "explanation": "“重量”指事物在文化上的分量，“承载着……的文化重量”语义通顺。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指人或动物身体的轻重，不能承载文化。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是人体的温度，不能用来形容文化的分量。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“文化”不与“体积”搭配，体积指占据空间的大小。"}], "explanations": {"重量": "“重量”指事物在文化上的分量，“承载着……的文化重量”语义通顺。", "体重": "语义：体重指人或动物身体的轻重，不能承载文化。", "体温": "语义：体温是人体的温度，不能用来形容文化的分量。", "体积": "搭配：“文化”不与“体积”搭配，体积指占据空间的大小。"}, "sentence_index": 0, "correct_answer": "重量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座老桥的重量很大，载满货车也不会晃。", "explanation": "这里说的是桥的物理轻重，不是文化或情感上的分量；说桥能承受多少，要用〈承重〉。"}, {"text": "这箱书的重量是五十公斤，搬到楼上要两个人。", "explanation": "这里说的是物体的物理轻重，不是文化或情感上的分量，与此处的意思不同。"}, {"text": "这块铁的重量比那块大，用秤一称就知道。", "explanation": "这里说的是物体的物理轻重，不是文化或情感上的分量，与此处的意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12330, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重量", "is_correct": true, "explanation": "“有特别的重量”指节日对民族有重要的意义，语义通顺。"}, {"text": "数量", "is_correct": false, "explanation": "语义：数量指多少，不能用来说节日对民族的意义。"}, {"text": "体量", "is_correct": false, "explanation": "搭配：“体量”指规模大小，与“有特别的”连用不表示意义。"}, {"text": "重心", "is_correct": false, "explanation": "语义：重心是物体平衡的中心点，与节日的意义无关。"}], "explanations": {"重量": "“有特别的重量”指节日对民族有重要的意义，语义通顺。", "数量": "语义：数量指多少，不能用来说节日对民族的意义。", "体量": "搭配：“体量”指规模大小，与“有特别的”连用不表示意义。", "重心": "语义：重心是物体平衡的中心点，与节日的意义无关。"}, "sentence_index": 6, "correct_answer": "重量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的重量很好，用了五年还没坏。", "explanation": "这里应该用〈质量〉。“重量”指轻重或分量，不用来说东西的好坏。"}, {"text": "他的英语重量很高，老师都夸他。", "explanation": "这里应该用〈水平〉。“重量”不指能力或程度，说语言能力高低要用〈水平〉。"}, {"text": "这位运动员的重量很强，大家都佩服他。", "explanation": "这里应该用〈能力〉。“重量”不指人的能力，说能力强弱要用〈能力〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12330, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位作家的话在文坛很重量。", "corrected_sentence": "这位作家的话在文坛很有重量。", "error_description": "错误：“很重量”，正确：“很有重量”。“重量”作宾语表示分量时要用“有”，去掉“有”句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12330, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位学者的观点在学界有很重量。", "corrected_sentence": "这位学者的观点在学界很有重量。", "error_description": "错误：“有很重量”，正确：“很有重量”。副词“很”应放在“有”前修饰“有重量”，“有很重量”语序不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
