INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12333, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指不同世代（如父母与子女）之间的关系或差异。", "primary_collocate": null, "pronunciation": "dài jì", "ipa": "taɪ˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "此类传统实践往往植根于长期的环境观察与代际传承，其核心在于最大化水分利用效率，同时维持生态系统的可持续性。", "target_word": "代际", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "口头传统并非简单的信息传递，而是一种动态的、仪式性的交流实践，它将民间传说、道德训诫与集体记忆编织进代际传承的经纬之中。", "target_word": "代际", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "父母和孩子之间有时会出现代际矛盾。", "target_word": "代际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人和老人多沟通，才能增进代际理解。", "target_word": "代际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个社区经常办活动，帮助改善代际关系。", "target_word": "代际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代际沟通不好，家里就容易吵架。", "target_word": "代际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的使用习惯有明显的代际差异。", "target_word": "代际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章讨论了代际公平的问题。", "target_word": "代际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请爷爷奶奶来上课，增加代际交流。", "target_word": "代际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代际冲突在很多家庭中都出现过。", "target_word": "代际", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "代際", "label": "繁体"}], "register": "书面", "sense_fingerprint": "代际：不同世代之间的关系或差异", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699a7efa-2ffe-43e6-84c2-b247b5d73d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12333, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "代际", "is_correct": true, "explanation": "正确答案：代际（dài jì），指不同世代之间的关系或差异。"}, {"text": "待机", "is_correct": false, "explanation": "jī（第一声）与 jì（第四声）声调不同，意思是待机，指设备处于待命状态。"}, {"text": "代价", "is_correct": false, "explanation": "jià 与 jì 韵母不同（多一个 a），意思是代价，指付出的成本。"}, {"text": "淡季", "is_correct": false, "explanation": "dàn 与 dài 韵母不同（dàn 为 -an，dài 为 -ai），意思是淡季，指生意清淡的时期。"}, {"text": "带劲", "is_correct": false, "explanation": "jìn 与 jì 韵母不同（多一个 n），意思是带劲，指有劲头、有意思。"}], "explanations": {"代际": "正确答案：代际（dài jì），指不同世代之间的关系或差异。", "待机": "jī（第一声）与 jì（第四声）声调不同，意思是待机，指设备处于待命状态。", "代价": "jià 与 jì 韵母不同（多一个 a），意思是代价，指付出的成本。", "淡季": "dàn 与 dài 韵母不同（dàn 为 -an，dài 为 -ai），意思是淡季，指生意清淡的时期。", "带劲": "jìn 与 jì 韵母不同（多一个 n），意思是带劲，指有劲头、有意思。"}, "sentence_index": null, "correct_answer": "代际"}, "level_3": {"options": [{"text": "市场", "is_correct": false, "explanation": "语义：“传承”传递的是经验、文化或财产，“市场”不能被传承，这里不通。"}, {"text": "代际", "is_correct": true, "explanation": "正确答案：代际，指不同世代之间的关系，这里指前代与后代之间的传承。"}, {"text": "股票", "is_correct": false, "explanation": "搭配：“传承”一般用于技艺、文化、家业，不说“股票传承”。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是工具，不是可以代代相传的东西，与“传承”不合。"}], "explanations": {"市场": "语义：“传承”传递的是经验、文化或财产，“市场”不能被传承，这里不通。", "代际": "正确答案：代际，指不同世代之间的关系，这里指前代与后代之间的传承。", "股票": "搭配：“传承”一般用于技艺、文化、家业，不说“股票传承”。", "电脑": "语义：电脑是工具，不是可以代代相传的东西，与“传承”不合。"}, "sentence_index": 0, "correct_answer": "代际"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父母和孩子之间有代际，所以常常争吵。", "explanation": "这里应该用〈代沟〉。代沟指两代人之间的思想隔阂，可以说“有代沟”；代际是书面词，指世代之间的关系，不说“有代际”。"}, {"text": "父亲和儿子的代际都很喜欢打篮球。", "explanation": "这里应该用〈两代人〉。代际指世代之间的关系，不是具体的人，不能作“喜欢”的主语。"}, {"text": "他的代际遍布世界各地。", "explanation": "这里应该用〈后代〉。后代指子孙，是具体的人；代际指世代之间的关系，不能指一群人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12333, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温度", "is_correct": false, "explanation": "语义：使用习惯不能测量温度，“温度差异”与“手机的使用习惯”不合。"}, {"text": "代际", "is_correct": true, "explanation": "正确答案：代际，指不同世代之间的差异，这里指不同年龄的人对手机的使用差异。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色差异”指外观，与“使用习惯”无关。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”多用于物体或空间，不说“习惯有体积差异”。"}], "explanations": {"温度": "语义：使用习惯不能测量温度，“温度差异”与“手机的使用习惯”不合。", "代际": "正确答案：代际，指不同世代之间的差异，这里指不同年龄的人对手机的使用差异。", "颜色": "语义：“颜色差异”指外观，与“使用习惯”无关。", "体积": "搭配：“体积”多用于物体或空间，不说“习惯有体积差异”。"}, "sentence_index": 6, "correct_answer": "代际"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "在我们家，代际大的人说话最有分量。", "explanation": "这里应该用〈辈分〉。辈分指家族中的世代次序，可以说“辈分大”；代际指世代之间的关系，不指人的辈分高低。"}, {"text": "我和表哥是代际，从小一起长大。", "explanation": "这里应该用〈同辈〉。同辈指同一世代的人，可以说“是同辈”；代际指两代之间的关系，不能用来称呼同一代的人。"}, {"text": "为了这次胜利，他付出了很大的代际。", "explanation": "这里应该用〈代价〉。代价指为达到目的所付出的牺牲，可以说“付出代价”；代际指世代之间的关系，不能表示付出的牺牲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12333, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次活动很代际特色。", "corrected_sentence": "这次活动很有代际特色。", "error_description": "错误在词类：“代际”是名词，不能像形容词一样受“很”修饰；应说“很有代际特色”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12333, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这门手艺需要代际们传承，才能保存下去。", "corrected_sentence": "这门手艺需要代际传承，才能保存下去。", "error_description": "错误在“们”：“代际”指世代之间的关系，是抽象概念，不能加复数词尾“们”；应说“代际传承”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
