INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12335, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "经线和纬线的合称，用于确定地球上某一点的位置。", "primary_collocate": null, "pronunciation": "jīng wěi", "ipa": "tɕiŋ⁵⁵ weɪ̯²¹⁴", "syllable_count": 2, "sentences": [{"text": "古代航海家依靠经纬，才能在茫茫大海上确定船只的位置。", "target_word": "经纬", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "地图上的经纬可以帮我们找位置。", "target_word": "经纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水手用经纬来确定船在哪里。", "target_word": "经纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "借助经纬，我们就能知道城市在哪儿。", "target_word": "经纬", "complexity_tier": "T3", "furigana": "jīng wěi", "sentence_source": "generated"}, {"text": "地理课上，老师教我们看经纬。", "target_word": "经纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用经纬表示城市的位置。", "target_word": "经纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机靠经纬找到正确的方向。", "target_word": "经纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张地图上的经纬画得很清楚。", "target_word": "经纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经纬是地理课里很重要的知识。", "target_word": "经纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在地图上找城市时，要先看清经纬。", "target_word": "经纬", "complexity_tier": "T3", "furigana": "jīng wěi", "sentence_source": "generated"}], "morphological_forms": [{"form": "经纬度", "label": "复合"}, {"form": "经纬线", "label": "复合"}, {"form": "经纬仪", "label": "复合"}, {"form": "經緯", "label": "繁体"}], "register": "书面", "sense_fingerprint": "经线和纬线的合称，用来确定位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76ee065-26df-4d6a-b94a-ac532d78a03d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12335, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经纬", "is_correct": true, "explanation": "经纬：经线和纬线的合称，用来确定船只在大海上的位置，与“确定位置”相合。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜是食物，不能编织进传承的框架之中。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：外貌是外在形象，不能作为编织传承的框架。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是金额，与编织传承无关。"}], "explanations": {"经纬": "经纬：经线和纬线的合称，用来确定船只在大海上的位置，与“确定位置”相合。", "饭菜": "语义：饭菜是食物，不能编织进传承的框架之中。", "外貌": "体貌：外貌是外在形象，不能作为编织传承的框架。", "价格": "语义：价格是金额，与编织传承无关。"}, "sentence_index": 0, "correct_answer": "经纬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个城市的经纬是东经一百二十度。", "explanation": "这里应该用〈经度〉。经纬是经线和纬线的合称，指网格系统，不能说成某个经度的数值。"}, {"text": "这位老人的经纬很亲切。", "explanation": "这里应该用〈态度〉。经纬指经线和纬线的合称，不指人的态度，不能用来形容一个人是否亲切。"}, {"text": "飞机找到了正确的经纬。", "explanation": "这里应该用〈方向〉。经纬指经线和纬线构成的网格，不指方向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12335, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经纬", "is_correct": true, "explanation": "经纬：经线和纬线构成的网格，可用来确定方向，与“飞机”和“找方向”相合。"}, {"text": "外形", "is_correct": false, "explanation": "体貌：外形是外观特征，飞机靠外形找方向不成立。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是嗅觉感受，不能用来找方向。"}, {"text": "发动机", "is_correct": false, "explanation": "语义：发动机提供动力，不用于确定方向。"}], "explanations": {"经纬": "经纬：经线和纬线构成的网格，可用来确定方向，与“飞机”和“找方向”相合。", "外形": "体貌：外形是外观特征，飞机靠外形找方向不成立。", "味道": "语义：味道是嗅觉感受，不能用来找方向。", "发动机": "语义：发动机提供动力，不用于确定方向。"}, "sentence_index": 6, "correct_answer": "经纬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山的经纬很高。", "explanation": "这里应该用〈纬度〉。经纬是网格的合称，不能说高低。"}, {"text": "这条经纬穿过北京。", "explanation": "这里应该用〈纬线〉。经纬指经线和纬线的合称，不指单独一条纬线。"}, {"text": "这个经纬在北方。", "explanation": "这里应该用〈方位〉。经纬是网格，不指所在的方位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12335, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们靠一条经纬确定了城市的位置。", "corrected_sentence": "我们靠经纬确定了城市的位置。", "error_description": "错误：在“经纬”前加了量词“条”。经纬是经线和纬线的合称，不用个体量词计量。正确应说“靠经纬”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12335, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师在地图上画出了一个经纬。", "corrected_sentence": "老师在地图上画出了经纬。", "error_description": "错误：在“经纬”前加了量词“个”。经纬是经线和纬线的合称，不用个体量词计量。正确应说“画出了经纬”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
