INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12336, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用笔等工具在纸上或其他物体上写字。", "primary_collocate": null, "pronunciation": "shū xiě", "ipa": "ʂu⁵⁵ ɕjɛ²¹⁴", "syllable_count": 2, "sentences": [{"text": "与书写文本的固化不同，每一次讲述都是对传统的再创造，讲述者根据当下语境、听众构成与社会需求，对情节进行增删或重构。", "target_word": "书写", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "孩子们在认真地书写自己的名字。", "target_word": "书写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用毛笔书写了一副对联。", "target_word": "书写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种笔很适合在纸上书写。", "target_word": "书写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书写时，请你坐直一点儿。", "target_word": "书写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要求我们书写整齐。", "target_word": "书写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在黑板上书写今天的作业。", "target_word": "书写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用黑色的笔书写，不要用铅笔。", "target_word": "书写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友刚学书写汉字，写得很慢。", "target_word": "书写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她书写的字很漂亮。", "target_word": "书写", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "书写了", "label": "体标（了）"}, {"form": "书写过", "label": "体标（过）"}, {"form": "书写工具", "label": "复合"}, {"form": "書寫", "label": "繁体"}], "register": "书面", "sense_fingerprint": "用笔等工具在物体上写字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76ee065-26df-4d6a-b94a-ac532d78a03d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12336, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书写", "is_correct": true, "explanation": "书写指用笔写字，此处指文本的写定，与“固化”相符，句意通顺。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：烧毁是毁掉，与“固化”的意思不合，句意说不通。"}, {"text": "演唱", "is_correct": false, "explanation": "搭配：“演唱”指唱歌，不能说“演唱文本”。"}, {"text": "表演", "is_correct": false, "explanation": "搭配：“表演”的对象是节目、角色，不能说“表演文本的固化”。"}], "explanations": {"书写": "书写指用笔写字，此处指文本的写定，与“固化”相符，句意通顺。", "烧毁": "语义：烧毁是毁掉，与“固化”的意思不合，句意说不通。", "演唱": "搭配：“演唱”指唱歌，不能说“演唱文本”。", "表演": "搭配：“表演”的对象是节目、角色，不能说“表演文本的固化”。"}, "sentence_index": 0, "correct_answer": "书写"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用针线书写了一个布娃娃。", "explanation": "这里应该用〈缝〉。书写是用笔写字，用针线做布娃娃要用“缝”，不能用“书写”。"}, {"text": "工匠在石头上书写了一朵花。", "explanation": "这里应该用〈雕刻〉。书写是用笔写字，在石头上刻花要用“雕刻”。"}, {"text": "孩子在墙上书写了一只小猫。", "explanation": "这里应该用〈画〉。书写是写字，画小猫要用“画”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12336, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书写", "is_correct": true, "explanation": "书写指用笔写字，黑板上写的是今天的作业，与句意相符。"}, {"text": "擦", "is_correct": false, "explanation": "语义：擦是抹去，与“在黑板上留下今天的作业”的语境相反。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“作业”搭配，不能说吃作业。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕是撕破、扯断，与“在黑板上写作业”的意思不符。"}], "explanations": {"书写": "书写指用笔写字，黑板上写的是今天的作业，与句意相符。", "擦": "语义：擦是抹去，与“在黑板上留下今天的作业”的语境相反。", "吃": "搭配：“吃”不能与“作业”搭配，不能说吃作业。", "撕": "语义：撕是撕破、扯断，与“在黑板上写作业”的意思不符。"}, "sentence_index": 6, "correct_answer": "书写"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用铅笔书写了一遍画的轮廓。", "explanation": "这里应该用〈描〉。书写是用笔写字，描画轮廓要用“描”。"}, {"text": "工人用锯子书写了一块木板。", "explanation": "这里应该用〈切割〉。书写是用笔写字，锯木板要用“切割”。"}, {"text": "她用毛线书写了一条围巾。", "explanation": "这里应该用〈织〉。书写是用笔写字，织围巾要用“织”，不能用“书写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12336, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师让我们作业本上书写答案。", "corrected_sentence": "老师让我们在作业本上书写答案。", "error_description": "介词错误：处所“作业本上”前面要用介词“在”，应说“在作业本上书写答案”，不能省略“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12336, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她书写地很工整。", "corrected_sentence": "她书写得很工整。", "error_description": "补语标记错误：说明“书写”的程度要用“得”，不能用“地”（“地”用于动词前作状语）。应说“书写得很工整”，不能说“书写地很工整”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
