INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12338, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对年长、有经验或地位较高的人的尊称。", "primary_collocate": null, "pronunciation": "zhǎng zhě", "ipa": "ʈʂɑŋ˨˩˦ ʈʂɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "村里的长者受到大家的尊敬。", "target_word": "长者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要尊敬长者。", "target_word": "长者", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一位长者在公园里教孩子们写毛笔字。", "target_word": "长者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人应该给长者让座。", "target_word": "长者", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位长者说话很慢，但是很有道理。", "target_word": "长者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年的时候，我们先向长者问好。", "target_word": "长者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长者坐下以后，大家才开始吃饭。", "target_word": "长者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是我们这里最受欢迎的长者。", "target_word": "长者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遇到困难，可以去请教长者。", "target_word": "长者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师请几位长者来给学生讲故事。", "target_word": "长者", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位长者", "label": "量词"}], "register": "书面", "sense_fingerprint": "对年长、有经验或地位较高的人的尊称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0954f54d-1810-47dd-bdb8-2c3f2e9c6892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12338, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长者", "is_correct": true, "explanation": "「长者」指受人尊敬的年长者，与“受到大家的尊敬”相合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能“受到尊敬”，此处所指的必须是人。"}, {"text": "机器", "is_correct": false, "explanation": "搭配：“受到尊敬”只用于人，不能用于机器。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：“垃圾”不能“受到尊敬”，此处所指的必须是值得尊敬的人。"}], "explanations": {"长者": "「长者」指受人尊敬的年长者，与“受到大家的尊敬”相合。", "石头": "语义：石头不能“受到尊敬”，此处所指的必须是人。", "机器": "搭配：“受到尊敬”只用于人，不能用于机器。", "垃圾": "语义：“垃圾”不能“受到尊敬”，此处所指的必须是值得尊敬的人。"}, "sentence_index": 0, "correct_answer": "长者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他才二十岁，却已经是村里的长者。", "explanation": "这里应该用〈年轻人〉。长者指年纪大、有经验的人，与「才二十岁」的情况不符。"}, {"text": "这位长者跟我同岁，今年都是二十五岁。", "explanation": "这里应该用〈同龄人〉。长者指年纪大的人，不能指与说话人同岁的人。"}, {"text": "这个孩子是我们家的长者。", "explanation": "这里应该用〈晚辈〉。长者指年长、有地位的人，不能指年幼的晚辈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3c7aff5-7054-4b0f-8776-0e760e9f6440') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12338, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长者", "is_correct": true, "explanation": "「长者」指年长的人，与“坐下以后，大家才开始吃饭”的情境相合。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：「坐下」要求有生命的施事，桌子不能坐下。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是物体，不能作为“坐下”的主体来理解。"}, {"text": "树", "is_correct": false, "explanation": "配价：「坐下」要求有生命的主语，树不能坐下。"}], "explanations": {"长者": "「长者」指年长的人，与“坐下以后，大家才开始吃饭”的情境相合。", "桌子": "配价：「坐下」要求有生命的施事，桌子不能坐下。", "椅子": "语义：椅子是物体，不能作为“坐下”的主体来理解。", "树": "配价：「坐下」要求有生命的主语，树不能坐下。"}, "sentence_index": 6, "correct_answer": "长者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班上的长者很多。", "explanation": "这里应该用〈同学〉。长者指年长的人，不能指同龄的同学。"}, {"text": "我们办公室的长者都很年轻。", "explanation": "这里应该用〈同事〉。长者指年纪大的人，与“都很年轻”的语境矛盾。"}, {"text": "这座老房子是个长者，已经住了很多年。", "explanation": "这里应该用〈建筑〉。长者只指年长、有地位的人，不能用于房屋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3c7aff5-7054-4b0f-8776-0e760e9f6440') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12338, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两位长者们在树下聊天，很和气。", "corrected_sentence": "两位长者在树下聊天，很和气。", "error_description": "〈两位〉已表示数量，不能再加〈们〉，应说「两位长者」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3c7aff5-7054-4b0f-8776-0e760e9f6440') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12338, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我碰到一只长者，他正在公园里散步。", "corrected_sentence": "我碰到一位长者，他正在公园里散步。", "error_description": "〈长者〉指人，量词应用「位」，不能用「只」，应说「一位长者」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3c7aff5-7054-4b0f-8776-0e760e9f6440') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
