INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12340, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3c7aff5-7054-4b0f-8776-0e760e9f6440') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12340, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在野外用木柴等可燃物堆集起来燃烧的火堆，常用于露营、聚会等。", "primary_collocate": null, "pronunciation": "gōu huǒ", "ipa": "kou˥ xuɔ˨˩˦", "syllable_count": 2, "sentences": [{"text": "村里的老人常在篝火旁讲古老的传说。", "target_word": "篝火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上，我们围着篝火唱歌。", "target_word": "篝火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们坐在篝火旁听故事。", "target_word": "篝火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "营地中间有一堆篝火。", "target_word": "篝火", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "风很大，篝火很快就灭了。", "target_word": "篝火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸在河边点起了一堆篝火。", "target_word": "篝火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们一边烤肉，一边看着篝火。", "target_word": "篝火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "篝火的光照红了大家的脸。", "target_word": "篝火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天亮以前，篝火慢慢变小了。", "target_word": "篝火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他往篝火里放了几块木头。", "target_word": "篝火", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "堆", "label": "量词"}], "register": "中性", "sense_fingerprint": "野外堆木柴燃烧的火堆，用于露营、聚会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0954f54d-1810-47dd-bdb8-2c3f2e9c6892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12340, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "篝火", "is_correct": true, "explanation": "正确：“在篝火旁”指老人在火堆旁讲传说，符合“篝火”在野外燃烧的场景。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是厨房里的制冷家电，老人不会在冰箱旁讲传说，与场景不合。"}, {"text": "洗衣机", "is_correct": false, "explanation": "语义：洗衣机是洗涤衣物的家电，与讲述古老传说的场景无关。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "语义：垃圾桶是盛放废弃物的容器，与讲述传说的场景不合。"}], "explanations": {"篝火": "正确：“在篝火旁”指老人在火堆旁讲传说，符合“篝火”在野外燃烧的场景。", "冰箱": "语义：冰箱是厨房里的制冷家电，老人不会在冰箱旁讲传说，与场景不合。", "洗衣机": "语义：洗衣机是洗涤衣物的家电，与讲述古老传说的场景无关。", "垃圾桶": "语义：垃圾桶是盛放废弃物的容器，与讲述传说的场景不合。"}, "sentence_index": 0, "correct_answer": "篝火"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "厨房的灶台里烧着篝火，锅里的水很快就开了。", "explanation": "这里应该用〈柴火〉。篝火是在野外堆起来燃烧的火，灶台里烧的是柴火。"}, {"text": "这座城市到了夜里，到处都是篝火的光，一片通明。", "explanation": "这里应该用〈灯火〉。篝火是野外堆起来的火，城市夜里的照明要用灯火。"}, {"text": "夜空中绽放着五彩的篝火。", "explanation": "这里应该用〈烟花〉。篝火是堆在地上燃烧的火，不会在夜空中绽放；五彩绽放的火光说的是烟花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3c7aff5-7054-4b0f-8776-0e760e9f6440') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12340, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "篝火", "is_correct": true, "explanation": "正确：“一边烤肉，一边看着篝火”，烤肉与篝火的场景一致。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：烤肉要用火加热，冰箱是制冷的，与“烤肉”的场景不协调。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块遇热会融化，不能与“烤肉”的场景相配。"}, {"text": "文具", "is_correct": false, "explanation": "搭配：“看着”后接可见的景象或人，“文具”一般不作这样的对象。"}], "explanations": {"篝火": "正确：“一边烤肉，一边看着篝火”，烤肉与篝火的场景一致。", "冰箱": "语义：烤肉要用火加热，冰箱是制冷的，与“烤肉”的场景不协调。", "冰块": "语义：冰块遇热会融化，不能与“烤肉”的场景相配。", "文具": "搭配：“看着”后接可见的景象或人，“文具”一般不作这样的对象。"}, "sentence_index": 6, "correct_answer": "篝火"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋里的篝火很暖和，大家都围在一起。", "explanation": "这里应该用〈炉火〉。篝火是在野外堆木柴燃烧的火，屋里取暖一般用炉火。"}, {"text": "夜里我们举着篝火走路，照亮了山路。", "explanation": "这里应该用〈火把〉。篝火是堆在地上的火，不能举着走路；手持照明要用火把。"}, {"text": "屋顶的篝火很亮。", "explanation": "这里应该用〈电灯〉。篝火是堆在地上燃烧的火，不会装在屋顶；屋顶照明要用电灯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3c7aff5-7054-4b0f-8776-0e760e9f6440') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜深了，村民们在空地上点起了一根篝火。", "corrected_sentence": "夜深了，村民们在空地上点起了一堆篝火。", "error_description": "量词错误：“篝火”的量词应为“堆”，“根”用于细长的东西。正确形式是“一堆篝火”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3c7aff5-7054-4b0f-8776-0e760e9f6440') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜深了，大家都坐篝火旁边。", "corrected_sentence": "夜深了，大家都坐在篝火旁边。", "error_description": "介词错误：“坐”后接处所时要加“在”，应为“坐在篝火旁边”，“坐篝火旁边”缺少“在”，不符合表示位置的格式。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3c7aff5-7054-4b0f-8776-0e760e9f6440') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12342, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12342, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12342, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容声音高低起伏、停顿转折，富有节奏和变化。", "primary_collocate": null, "pronunciation": "yì yáng dùn cuò", "ipa": "i⁵¹ jaŋ³⁵ tuən⁵¹ tsʰuo⁵¹", "syllable_count": 4, "sentences": [{"text": "在书写系统尚未普及的社会里，长者以声音为媒介，在篝火旁、庭院中或节庆仪式上，通过抑扬顿挫的语调重构历史——这种叙事行为本身就是一种社会凝聚的仪式，它不依赖文本的固定性，而是通过每一次讲述的微妙变异，使历史保持活性，成为可被重新诠释的活体经验。", "target_word": "抑扬顿挫", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "老师读诗的声音抑扬顿挫，同学们都听得入神。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲话抑扬顿挫，台下的人听得很认真。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位播音员的朗读抑扬顿挫，非常好听。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她念课文时抑扬顿挫，像在唱歌一样。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷读报纸总是抑扬顿挫的，像在演讲。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员念台词抑扬顿挫，观众听了都鼓掌。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的朗诵抑扬顿挫，让我想起了小时候的老师。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人讲故事抑扬顿挫，孩子们都安静下来。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗要读得抑扬顿挫才好听。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "声音高低起伏、停顿转折而有节奏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c72e6fc1-6a04-4152-89a4-f1736e5d22de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12342, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抑扬顿挫", "is_correct": true, "explanation": "正确。抑扬顿挫形容声音高低起伏、停顿有致，与“以声音为媒介”的讲述相合。"}, {"text": "单调", "is_correct": false, "explanation": "语义：单调指没有变化，与后文的“微妙变异”“使历史保持活性”相矛盾。"}, {"text": "雪白", "is_correct": false, "explanation": "搭配：“雪白”是颜色词，不能修饰语调，“通过雪白的语调”说不通。"}, {"text": "冷漠", "is_correct": false, "explanation": "语义：冷漠指没有感情，与“社会凝聚的仪式”的语境相反。"}], "explanations": {"抑扬顿挫": "正确。抑扬顿挫形容声音高低起伏、停顿有致，与“以声音为媒介”的讲述相合。", "单调": "语义：单调指没有变化，与后文的“微妙变异”“使历史保持活性”相矛盾。", "雪白": "搭配：“雪白”是颜色词，不能修饰语调，“通过雪白的语调”说不通。", "冷漠": "语义：冷漠指没有感情，与“社会凝聚的仪式”的语境相反。"}, "sentence_index": 0, "correct_answer": "抑扬顿挫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位播音员的朗读抑扬顿挫，语调毫无起伏。", "explanation": "这里应该用〈平淡〉。抑扬顿挫指声音有起伏，与“毫无起伏”自相矛盾；形容朗读平板应说〈平淡〉。"}, {"text": "这把椅子抑扬顿挫，坐起来很舒服。", "explanation": "这里应该用〈舒适〉。抑扬顿挫只形容声音的高低起伏，不能用来形容椅子这类物体。"}, {"text": "妈妈默读报纸，字句读得很抑扬顿挫。", "explanation": "这里误把〈抑扬顿挫〉当成了〈仔细〉的意思。该词只指有声朗读时的声音起伏，默读没有声音，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12342, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抑扬顿挫", "is_correct": true, "explanation": "正确。念台词时声音有起伏、有停顿，与后文观众鼓掌相符。"}, {"text": "含糊", "is_correct": false, "explanation": "语义：含糊指发音不清，观众听后鼓掌的反应与之矛盾。"}, {"text": "呆滞", "is_correct": false, "explanation": "体貌：呆滞多形容眼神、表情，不用来描写念台词的声音。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：冷淡指态度不热情，与观众听后热烈鼓掌的反应相矛盾。"}], "explanations": {"抑扬顿挫": "正确。念台词时声音有起伏、有停顿，与后文观众鼓掌相符。", "含糊": "语义：含糊指发音不清，观众听后鼓掌的反应与之矛盾。", "呆滞": "体貌：呆滞多形容眼神、表情，不用来描写念台词的声音。", "冷淡": "语义：冷淡指态度不热情，与观众听后热烈鼓掌的反应相矛盾。"}, "sentence_index": 6, "correct_answer": "抑扬顿挫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他结结巴巴地念诗，每一句都抑扬顿挫。", "explanation": "这里误把〈抑扬顿挫〉当成了〈流利〉的同义词。该词只描写声音的起伏和停顿有致，与断断续续的朗读无关。"}, {"text": "他用手指敲桌子，敲得抑扬顿挫。", "explanation": "抑扬顿挫只用于说话或朗读的声音，敲桌子的节奏应说〈节奏分明〉。"}, {"text": "他的脾气抑扬顿挫，一会儿高一会儿低。", "explanation": "这里应该用〈喜怒无常〉。抑扬顿挫说的是声音的起伏，不能形容脾气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12342, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人用抑扬顿挫地声音讲故事。", "corrected_sentence": "老人用抑扬顿挫的声音讲故事。", "error_description": "“地”应改为“的”。“抑扬顿挫”修饰名词“声音”，作定语须用“的”，不能用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12342, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他抑扬顿挫朗诵了，同学们都很喜欢听。", "corrected_sentence": "他抑扬顿挫地朗诵了，同学们都很喜欢听。", "error_description": "“抑扬顿挫”修饰动词“朗诵”，作状语时须加“地”，应为“抑扬顿挫地朗诵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
