INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12343, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "说话或朗读时，句子里声音高低、轻重、快慢的变化，用来表达不同的意思和感情。", "primary_collocate": null, "pronunciation": "yǔ diào", "ipa": "y²¹⁴ tjɑʊ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "在书写系统尚未普及的社会里，长者以声音为媒介，在篝火旁、庭院中或节庆仪式上，通过抑扬顿挫的语调重构历史——这种叙事行为本身就是一种社会凝聚的仪式，它不依赖文本的固定性，而是通过每一次讲述的微妙变异，使历史保持活性，成为可被重新诠释的活体经验。", "target_word": "语调", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "同一句话，语调不同，意思也不同。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的语调很温柔，孩子慢慢安静了。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学中文时，语调和声调一样重要。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听她的语调，我知道她有点生气。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疑问句的语调通常往上走。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我的语调太平，没有感情。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说话的语调让我觉得很亲切。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用开心的语调回答了我的问题。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朗读时要注意语调的变化。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "語調", "label": "繁体"}], "register": "中性", "sense_fingerprint": "句子里声音高低轻重快慢的变化，表达意思和感情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c72e6fc1-6a04-4152-89a4-f1736e5d22de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12343, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "语调", "is_correct": true, "explanation": "正确。讲述以声音为媒介，“抑扬顿挫的语调”指声音高低起伏的变化。"}, {"text": "香味", "is_correct": false, "explanation": "搭配：“香味”是气味，不能用“抑扬顿挫的”修饰，句中说不通。"}, {"text": "音量", "is_correct": false, "explanation": "搭配：音量指声音的大小，不能用“抑扬顿挫”修饰，也与句中的高低变化不符。"}, {"text": "字形", "is_correct": false, "explanation": "语义：字形是书写的形态，与“以声音为媒介”的语境冲突。"}], "explanations": {"语调": "正确。讲述以声音为媒介，“抑扬顿挫的语调”指声音高低起伏的变化。", "香味": "搭配：“香味”是气味，不能用“抑扬顿挫的”修饰，句中说不通。", "音量": "搭配：音量指声音的大小，不能用“抑扬顿挫”修饰，也与句中的高低变化不符。", "字形": "语义：字形是书写的形态，与“以声音为媒介”的语境冲突。"}, "sentence_index": 0, "correct_answer": "语调"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学中文时，每个字的语调都要写准。", "explanation": "这里应该用〈笔画〉。语调指说话时声音的变化，不指书写；写字要说〈笔画〉。"}, {"text": "这张桌子的语调很结实。", "explanation": "这里误把〈语调〉当成了〈质地〉。语调只指说话时声音的变化，形容桌子应说〈牢固〉。"}, {"text": "他一句话也没说，语调却很激动。", "explanation": "这里误把〈语调〉当成了〈神情〉。语调只指说话时声音的变化，没有说话时谈不上语调。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12343, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "语调", "is_correct": true, "explanation": "正确。“语调太平”指说话时声音的高低变化不足，与“没有感情”相合。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话是通话设备，不能用“太平”形容，也与语调无关。"}, {"text": "发音", "is_correct": false, "explanation": "搭配：发音指字音是否准确，不用“太平”形容，也与“没有感情”的语境不合。"}, {"text": "笔迹", "is_correct": false, "explanation": "语义：笔迹是书写的痕迹，不能用来形容说话的声音。"}], "explanations": {"语调": "正确。“语调太平”指说话时声音的高低变化不足，与“没有感情”相合。", "电话": "语义：电话是通话设备，不能用“太平”形容，也与语调无关。", "发音": "搭配：发音指字音是否准确，不用“太平”形容，也与“没有感情”的语境不合。", "笔迹": "语义：笔迹是书写的痕迹，不能用来形容说话的声音。"}, "sentence_index": 6, "correct_answer": "语调"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很快学会了新语调，能和外国人交谈。", "explanation": "这里误把〈语调〉当成了〈语言〉。语调只指说话时声音的变化，不是一门语言，应说〈语言〉。"}, {"text": "他的朗读有一块好语调，很动听。", "explanation": "这里应该用〈一种〉。语调无形，不用“块”计量，应说“一种”。"}, {"text": "这台电视的语调很清楚，画面也很好。", "explanation": "这里误把〈语调〉当成了〈音质〉。语调只指说话时声音的变化，形容电视的声音清楚应说〈音质〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12343, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的语调很温和得，我一下子放松了。", "corrected_sentence": "他的语调很温和，我一下子放松了。", "error_description": "“得”后面缺少补语，不能直接用在形容词“温和”之后；应删去“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12343, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朗读时要注意语调地起伏。", "corrected_sentence": "朗读时要注意语调的起伏。", "error_description": "“地”应改为“的”。“语调”修饰名词“起伏”，作定语须用“的”，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
