INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12346, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12346, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把事情的经过或道理说出来，让人知道。", "primary_collocate": null, "pronunciation": "jiǎng shù", "ipa": "tɕjɑŋ²¹⁴ ʂu⁵¹", "syllable_count": 2, "sentences": [{"text": "在此类框架下，讲述一则民间传说不仅是在复述往事，更是在执行一种文化实践：说者通过语言激活神圣时空，听者则在沉浸中获得身份认同的再确认。", "target_word": "讲述", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "与书写文本的固化不同，每一次讲述都是对传统的再创造，讲述者根据当下语境、听众构成与社会需求，对情节进行增删或重构。", "target_word": "讲述", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "历史在此不仅是“发生了什么”，更是“如何被讲述”。", "target_word": "讲述", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "正是在这种持续的讲述中，交流超越了工具性功能，升华为一种存在的确认——我们通过叙事回答那个最根本的问题：我们是谁？", "target_word": "讲述", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "爷爷给我们讲述了他年轻时的经历。", "target_word": "讲述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你讲述一下这件事的经过。", "target_word": "讲述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲述了一个小男孩的故事。", "target_word": "讲述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在课上讲述了这个道理。", "target_word": "讲述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她向警察讲述了昨天发生的事情。", "target_word": "讲述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讲述的是一家人的生活。", "target_word": "讲述", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "講述", "label": "繁体"}, {"form": "讲述了", "label": "体标"}, {"form": "讲述着", "label": "体标"}, {"form": "讲述过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把事情经过或道理说出来让人知道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c72e6fc1-6a04-4152-89a4-f1736e5d22de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12346, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讲述", "is_correct": true, "explanation": "讲述：把民间传说说出来，与“复述往事”“说者通过语言”相合。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：“收藏”是保存珍藏，不能表示把传说说出来。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”用于房屋、道路等，不能说修建一则传说。"}, {"text": "雕刻", "is_correct": false, "explanation": "搭配：“雕刻”的对象是石头、木头等实物，传说不能被雕刻。"}], "explanations": {"讲述": "讲述：把民间传说说出来，与“复述往事”“说者通过语言”相合。", "收藏": "语义：“收藏”是保存珍藏，不能表示把传说说出来。", "修建": "搭配：“修建”用于房屋、道路等，不能说修建一则传说。", "雕刻": "搭配：“雕刻”的对象是石头、木头等实物，传说不能被雕刻。"}, "sentence_index": 0, "correct_answer": "讲述"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师在黑板上讲述了一个圆圈。", "explanation": "这里应该用〈画〉。讲述是用语言说出事情或道理，画圆圈要用“画”。"}, {"text": "妈妈在菜市场讲述了今天的菜价。", "explanation": "这里应该用〈报〉。讲述是把事情的经过或道理说出来，报菜价是报出数字，要用报。"}, {"text": "她在台上讲述了一段钢琴曲。", "explanation": "这里应该用〈演奏〉。讲述是用语言说出事情或道理，弹奏钢琴曲要用演奏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12346, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讲述", "is_correct": true, "explanation": "讲述：把一本书的故事说出来，与“一个小男孩的故事”相合。"}, {"text": "复印", "is_correct": false, "explanation": "语义：“复印”是复制文件，不能表示把故事讲出来。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”用于食物，不能说吃故事。"}, {"text": "拆开", "is_correct": false, "explanation": "搭配：“拆开”用于包裹等物品，不能用来拆开一个故事。"}], "explanations": {"讲述": "讲述：把一本书的故事说出来，与“一个小男孩的故事”相合。", "复印": "语义：“复印”是复制文件，不能表示把故事讲出来。", "吃": "搭配：“吃”用于食物，不能说吃故事。", "拆开": "搭配：“拆开”用于包裹等物品，不能用来拆开一个故事。"}, "sentence_index": 6, "correct_answer": "讲述"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在纸上讲述了森林的景色。", "explanation": "这里应该用〈描绘〉。讲述是用语言说出事情或道理，描绘景色要用描绘。"}, {"text": "老师讲述这个学生很聪明。", "explanation": "这里应该用〈夸〉。讲述只是陈述经过或道理，不能用来表示称赞。"}, {"text": "他在会上讲述了一碗热汤。", "explanation": "这里应该用〈端〉。讲述是把事情说出来，端上热汤要用端。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12346, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在讲述了一个故事。", "corrected_sentence": "他正在讲述一个故事。", "error_description": "“正在”表示动作进行，不能与“了”同用。应去掉“了”，说“正在讲述一个故事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12346, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把那件事讲述得一遍。", "corrected_sentence": "她把那件事讲述了一遍。", "error_description": "动词“讲述”后的“了”表示动作完成，不能换成“得”。“得”要接状态补语，不能说“讲述得一遍”，应说“讲述了一遍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12347, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明确", "is_correct": true, "explanation": "反义：“明确”指清楚、确定，与“微妙”的难以说清相对。"}, {"text": "宽敞", "is_correct": false, "explanation": "无关：形容空间大，与关系或情况无关。"}, {"text": "结实", "is_correct": false, "explanation": "无关：形容物体坚固，与此义无关。"}, {"text": "冷静", "is_correct": false, "explanation": "无关：形容人的情绪状态，与事物之间的关系无关。"}], "correct_answer": "明确", "explanations": {"明确": "反义：“明确”指清楚、确定，与“微妙”的难以说清相对。", "宽敞": "无关：形容空间大，与关系或情况无关。", "结实": "无关：形容物体坚固，与此义无关。", "冷静": "无关：形容人的情绪状态，与事物之间的关系无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12347, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "直白", "is_correct": true, "explanation": "反义：“直白”指直接明白，与“微妙”的难以说清相对。"}, {"text": "巨大", "is_correct": false, "explanation": "无关：形容体积或程度大，与感情无关。"}, {"text": "干净", "is_correct": false, "explanation": "无关：形容清洁，与感情无关。"}, {"text": "懒惰", "is_correct": false, "explanation": "无关：形容人的习性，与此义无关。"}], "correct_answer": "直白", "explanations": {"直白": "反义：“直白”指直接明白，与“微妙”的难以说清相对。", "巨大": "无关：形容体积或程度大，与感情无关。", "干净": "无关：形容清洁，与感情无关。", "懒惰": "无关：形容人的习性，与此义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12347, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容事物之间细微、复杂，难以说清楚。", "primary_collocate": null, "pronunciation": "wēi miào", "ipa": "weɪ˥ miɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他们两个人的关系很微妙。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的情况有点微妙，不太好说。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她脸上的表情变得很微妙。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国之间的关系十分微妙。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话的语气很微妙，我听不懂。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，大家的气氛突然变得微妙起来。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题很微妙，回答时要小心。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两种观点之间的差别很微妙，难以用一句话说清楚。", "target_word": "微妙", "complexity_tier": "T3", "furigana": "liǎng zhǒng guān diǎn zhī jiān de chā bié hěn wēi miào, nán yǐ yòng yí jù huà shuō qīng chu.", "sentence_source": "generated"}, {"text": "双方的立场很微妙，谁也不想先开口。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母女之间有一种微妙的感情。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "微妙地", "label": "状语形式"}], "register": "书面", "sense_fingerprint": "关系、气氛、态度等细微复杂、难以说清", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b62a16e-8257-4aad-9b92-a998a7c9c5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12347, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "微妙", "is_correct": true, "explanation": "正确：“微妙”形容关系细微复杂、难以说清，符合句意。"}, {"text": "精致", "is_correct": false, "explanation": "搭配：精致多形容物品和工艺，不说关系很精致。"}, {"text": "迷你", "is_correct": false, "explanation": "语义：迷你指体型很小，与人际关系的复杂程度无关。"}, {"text": "微小", "is_correct": false, "explanation": "语义：微小说体积或数量小，不说关系难以说清。"}], "explanations": {"微妙": "正确：“微妙”形容关系细微复杂、难以说清，符合句意。", "精致": "搭配：精致多形容物品和工艺，不说关系很精致。", "迷你": "语义：迷你指体型很小，与人际关系的复杂程度无关。", "微小": "语义：微小说体积或数量小，不说关系难以说清。"}, "sentence_index": 0, "correct_answer": "微妙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台仪器的测量很微妙，误差只有千分之一。", "explanation": "这里应该用〈精确〉。微妙形容关系、气氛等细微复杂、难以说清的情况，不用来形容仪器的测量。"}, {"text": "这个山洞很微妙，大家都不敢进去。", "explanation": "这里应该用〈神秘〉。微妙用于关系、情况，不形容地点或场所。"}, {"text": "这张桌子很微妙，放上东西也不摇。", "explanation": "这里应该用〈稳固〉。微妙形容关系、情况难以说清，不用来形容家具；桌子应说稳固。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12347, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "微妙", "is_correct": true, "explanation": "正确：“微妙”形容问题难以把握，与“回答时要小心”相符。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：幽默形容风趣，与“回答时要小心”的语境相反。"}, {"text": "轻松", "is_correct": false, "explanation": "语境：「轻松」与后半句「回答时要小心」语气矛盾，句意不通。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：热闹形容场面或活动，不用来形容问题。"}], "explanations": {"微妙": "正确：“微妙”形容问题难以把握，与“回答时要小心”相符。", "幽默": "语义：幽默形容风趣，与“回答时要小心”的语境相反。", "轻松": "语境：「轻松」与后半句「回答时要小心」语气矛盾，句意不通。", "热闹": "搭配：热闹形容场面或活动，不用来形容问题。"}, "sentence_index": 6, "correct_answer": "微妙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子很微妙，坐上去很稳当。", "explanation": "这里应该用〈牢固〉。微妙形容关系、情况难以说清，不用来形容家具；椅子应说牢固。"}, {"text": "这间屋子很微妙，窗户又大。", "explanation": "这里应该用〈明亮〉。微妙只形容难以说清的关系或情况，不用来形容房间。"}, {"text": "路面很微妙，走起来不稳。", "explanation": "这里应该用〈粗糙〉。微妙不用于描述路面的质地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12347, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们俩之间的气氛变很微妙。", "corrected_sentence": "他们俩之间的气氛变得很微妙。", "error_description": "漏掉了补语前的“得”：“变”后面引出“很微妙”要用“得”，应为“变得很微妙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12347, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他微妙的改变了态度。", "corrected_sentence": "他微妙地改变了态度。", "error_description": "的地混用：“微妙”修饰动词“改变”，是状语，应用“地”，不能用“的”。正确为“微妙地改变了态度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
