INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12348, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "基因结构发生改变，导致生物体的性状出现新的特征。", "primary_collocate": null, "pronunciation": "biàn yì", "ipa": "pjɛn˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "细菌在环境压力下不断发生变异，因此逐渐产生了耐药性。", "target_word": "变异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基因发生变异，可能让植物长出新的颜色。", "target_word": "变异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家在这种病毒里发现了一种变异。", "target_word": "变异", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只白色的老虎是基因变异的结果。", "target_word": "变异", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "变异让生物有机会适应新的环境。", "target_word": "变异", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有些变异对身体有害，有些没有影响。", "target_word": "变异", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生正在研究这种变异会不会引起疾病。", "target_word": "变异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水稻的变异让它更耐旱。", "target_word": "变异", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家用仪器检查细胞里有没有变异。", "target_word": "变异", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "射线太强会使基因出现变异。", "target_word": "变异", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "基因变异", "label": "复合"}, {"form": "变异株", "label": "复合"}, {"form": "變異", "label": "繁体"}], "register": "书面", "sense_fingerprint": "名词：生物基因发生改变而出现新的性状，如基因变异", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c72e6fc1-6a04-4152-89a4-f1736e5d22de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12348, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "变异", "is_correct": true, "explanation": "变异 biàn yì：指基因或性状发生改变，与听到的读音相合。"}, {"text": "贬义", "is_correct": false, "explanation": "贬义 biǎn yì 与 biàn yì 第一个音节声调不同（第三声），意思是贬低的含义。"}, {"text": "便宜", "is_correct": false, "explanation": "便宜 biànyi 第二个音节为轻声，与 biàn yì 声调不同，意思是价钱低。"}, {"text": "编译", "is_correct": false, "explanation": "编译 biān yì 第一个音节为第一声，与 biàn 声调不同，意思是编写与翻译。"}], "explanations": {"变异": "变异 biàn yì：指基因或性状发生改变，与听到的读音相合。", "贬义": "贬义 biǎn yì 与 biàn yì 第一个音节声调不同（第三声），意思是贬低的含义。", "便宜": "便宜 biànyi 第二个音节为轻声，与 biàn yì 声调不同，意思是价钱低。", "编译": "编译 biān yì 第一个音节为第一声，与 biàn 声调不同，意思是编写与翻译。"}, "sentence_index": null, "correct_answer": "变异"}, "level_3": {"options": [{"text": "变异", "is_correct": true, "explanation": "变异：指基因改变，与细菌在压力下产生的基因变化相合。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”与细菌的基因变化无关，“发生工资”说不通。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语义：“玩意儿”泛指东西，“发生玩意儿”说不通，且属口语。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：“饭菜”指食物，与细菌发生的变化无关。"}], "explanations": {"变异": "变异：指基因改变，与细菌在压力下产生的基因变化相合。", "工资": "语义：“工资”与细菌的基因变化无关，“发生工资”说不通。", "玩意儿": "语义：“玩意儿”泛指东西，“发生玩意儿”说不通，且属口语。", "饭菜": "语义：“饭菜”指食物，与细菌发生的变化无关。"}, "sentence_index": 0, "correct_answer": "变异"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几年城市的面貌出现了很大的变异。", "explanation": "这里应该用〈变化〉。变异专指生物基因或性状的改变，城市面貌的变动要用变化。"}, {"text": "这台机器的零件变异了，只能换新的。", "explanation": "这里应该用〈损坏〉。变异专指基因或性状的改变，机器零件坏了要用损坏。"}, {"text": "我的成绩这学期突然变异了。", "explanation": "这里应该用〈下降〉。变异专指基因或性状的改变，成绩降低要用下降。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12348, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变异", "is_correct": true, "explanation": "变异：指基因改变，可能引起疾病，与“研究……会不会引起疾病”相合。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：“乐谱”不会引起疾病，与研究的对象不合。"}, {"text": "塑像", "is_correct": false, "explanation": "语义：“塑像”是雕塑品，不会引起疾病。"}, {"text": "棋局", "is_correct": false, "explanation": "语义：“棋局”是下棋的局势，不会引起疾病。"}], "explanations": {"变异": "变异：指基因改变，可能引起疾病，与“研究……会不会引起疾病”相合。", "乐谱": "语义：“乐谱”不会引起疾病，与研究的对象不合。", "塑像": "语义：“塑像”是雕塑品，不会引起疾病。", "棋局": "语义：“棋局”是下棋的局势，不会引起疾病。"}, "sentence_index": 6, "correct_answer": "变异"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的病情这两天突然变异了。", "explanation": "这里应该用〈加重〉。变异指基因或性状的改变，病情恶化要用加重。"}, {"text": "这里发现了古代的变异。", "explanation": "这里应该用〈遗迹〉。变异指性状改变，不能指古代留下的遗迹。"}, {"text": "这次股市的变异让投资者很紧张。", "explanation": "这里应该用〈变动〉。变异专指生物性状的改变，市场的涨跌要用变动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12348, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种水稻出现了一只变异。", "corrected_sentence": "这种水稻出现了一种变异。", "error_description": "“变异”是抽象名词，量词应用“种”，不能用“只”（“只”多用于动物等个体）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12348, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "射线太强会使基因很变异。", "corrected_sentence": "射线太强会使基因发生变异。", "error_description": "“很”是程度副词，不能直接修饰动词“变异”，应说“发生变异”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
