INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12349, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "保持变化并能不断被重新理解的状态", "primary_collocate": null, "pronunciation": "huó xìng", "ipa": "xwo˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "传统文化只有不断变化，才能保持活性。", "target_word": "活性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人重新理解这首老歌，它又有了活性。", "target_word": "活性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语言不变化，就会失去活性。", "target_word": "活性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个时代都会给经典带来新的活性。", "target_word": "活性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座古城保持着文化的活性。", "target_word": "活性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老故事经过新的讲法，重新有了活性。", "target_word": "活性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "博物馆想让历史保持活性，而不是只放在玻璃柜里。", "target_word": "活性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失去活性的传统，慢慢就没人再用了。", "target_word": "活性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "民间节日的活性来自一代代人的新理解。", "target_word": "活性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的作品能让人不断重新理解，所以一直有活性。", "target_word": "活性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "名词：文化、语言、传统等不断变化并被重新理解的生命状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c72e6fc1-6a04-4152-89a4-f1736e5d22de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12349, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活性", "is_correct": true, "explanation": "活性：指文化不断变化、保持生命力的状态，与句中“不断变化”的意思呼应。"}, {"text": "距离", "is_correct": false, "explanation": "语义：“保持距离”指不靠近，与“不断变化”的句意不符，句子不通。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“保持体温”多说人的身体，不用于文化，句中也讲不通。"}, {"text": "秘密", "is_correct": false, "explanation": "语义：文化要靠不断变化才能延续，说“保持秘密”与前半句的意思相反。"}], "explanations": {"活性": "活性：指文化不断变化、保持生命力的状态，与句中“不断变化”的意思呼应。", "距离": "语义：“保持距离”指不靠近，与“不断变化”的句意不符，句子不通。", "体温": "搭配：“保持体温”多说人的身体，不用于文化，句中也讲不通。", "秘密": "语义：文化要靠不断变化才能延续，说“保持秘密”与前半句的意思相反。"}, "sentence_index": 0, "correct_answer": "活性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这群年轻的演员身上充满了活性。", "explanation": "这里应该用〈活力〉。活性多指物质或系统的化学、生物作用，形容人的精神和生机要用活力。"}, {"text": "这把椅子的活性很高，坐上去很舒服。", "explanation": "这里应该用〈弹性〉。活性指事物保持变化、能被不断重新理解的状态，不用来形容椅子的软硬；说椅子有弹性要用弹性。"}, {"text": "这些老人身上还有活性。", "explanation": "这里应该用〈生机〉。活性不用来说人身上的精神状态，说人还有精神和生机要用生机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12349, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活性", "is_correct": true, "explanation": "活性：指历史不被封存、能被人不断重新理解的状态，与“不只放在玻璃柜里”形成对比。"}, {"text": "姿势", "is_correct": false, "explanation": "语义：历史没有姿势，“保持姿势”说的是身体动作，与句意不符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“保持体重”只用于人或动物的身体，不能用于历史。"}, {"text": "名额", "is_correct": false, "explanation": "语义：名额是分配的数量，与博物馆让历史“活起来”的意思不符。"}], "explanations": {"活性": "活性：指历史不被封存、能被人不断重新理解的状态，与“不只放在玻璃柜里”形成对比。", "姿势": "语义：历史没有姿势，“保持姿势”说的是身体动作，与句意不符。", "体重": "搭配：“保持体重”只用于人或动物的身体，不能用于历史。", "名额": "语义：名额是分配的数量，与博物馆让历史“活起来”的意思不符。"}, "sentence_index": 6, "correct_answer": "活性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位作家的活性很大，读者遍布各地。", "explanation": "这里应该用〈影响力〉。活性不用来说作家对读者的作用，这里要用影响力。"}, {"text": "这部电影很有活性，让人感动。", "explanation": "这里应该用〈感染力〉。活性不用来指作品打动人的力量，说作品打动人要用感染力。"}, {"text": "这个孩子的活性很轻，才三十斤。", "explanation": "这里应该用〈体重〉。活性指保持变化、能被不断重新理解的状态，不用来说人的轻重；说人的轻重要用体重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12349, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这门老手艺有一只活性，年轻人也愿意学。", "corrected_sentence": "这门老手艺有一种活性，年轻人也愿意学。", "error_description": "量词错误：“活性”是抽象名词，量词应用“种”，“只”只用于动物等具体事物，不能说“一只活性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12349, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座老城重新有了活性的。", "corrected_sentence": "这座老城重新有了活性。", "error_description": "“的”不能加在抽象名词“活性”后作句末，句子未完。应去掉“的”，说“这座老城重新有了活性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12350, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
