INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12350, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对某事物进行解释、阐明，使人们明白其含义。", "primary_collocate": null, "pronunciation": "quán shì", "ipa": "tɕʰyɛn˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "当某个返乡青年在社交媒体上写道：“我们种下的不只是树，更是对未来的一种承诺”，这句话恰如其分地诠释了本地行动如何在全球生态危机背景下，凝聚起一种具象而坚韧的希望。", "target_word": "诠释", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这位导演用电影诠释了爱的意义。", "target_word": "诠释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用简单的话诠释了这个词。", "target_word": "诠释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画诠释了乡愁这一主题。", "target_word": "诠释", "complexity_tier": "T3", "furigana": "zhè fú huà quán shì le xiāng chóu zhè yī zhǔ tí", "sentence_source": "generated"}, {"text": "每个人都有自己诠释生活的方式。", "target_word": "诠释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用行动诠释了什么是责任。", "target_word": "诠释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌诠释了青春的快乐和烦恼。", "target_word": "诠释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你诠释一下这句话的意思。", "target_word": "诠释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把这个角色诠释得非常好。", "target_word": "诠释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书诠释了中国文化的特点。", "target_word": "诠释", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "诠释了", "label": "体标"}, {"form": "诠释着", "label": "体标"}, {"form": "詮釋", "label": "繁体"}], "register": "书面", "sense_fingerprint": "对事物、理念、作品等作出解释并赋予含义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3370b77-fb49-4e42-b46b-5b0a583e1654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12350, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "诠释", "is_correct": true, "explanation": "诠释（quán shì）：对事物作出解释、阐明含义，即本题目标词。"}, {"text": "拳师", "is_correct": false, "explanation": "拳师（quán shī）与诠释的第二个音节声调不同：shī 为第一声，shì 为第四声，意思是拳击或武术教练。"}, {"text": "前世", "is_correct": false, "explanation": "前世（qián shì）与诠释的第一个音节不同：qián 没有介音 u，意思是前生。"}, {"text": "前事", "is_correct": false, "explanation": "前事（qián shì）与诠释的第一个音节不同：qián 没有介音 u，意思是过去的事情。"}, {"text": "传世", "is_correct": false, "explanation": "传世（chuán shì）与诠释（quán shì）的声母不同：ch 与 q，意思是流传后世。"}], "explanations": {"诠释": "诠释（quán shì）：对事物作出解释、阐明含义，即本题目标词。", "拳师": "拳师（quán shī）与诠释的第二个音节声调不同：shī 为第一声，shì 为第四声，意思是拳击或武术教练。", "前世": "前世（qián shì）与诠释的第一个音节不同：qián 没有介音 u，意思是前生。", "前事": "前事（qián shì）与诠释的第一个音节不同：qián 没有介音 u，意思是过去的事情。", "传世": "传世（chuán shì）与诠释（quán shì）的声母不同：ch 与 q，意思是流传后世。"}, "sentence_index": null, "correct_answer": "诠释"}, "level_3": {"options": [{"text": "诠释", "is_correct": true, "explanation": "诠释：把本地行动的意义说清楚，与“恰如其分地”搭配自然。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“破坏”指毁坏，与“恰如其分”和“凝聚起一种……希望”的正面语义相反。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”接的是生活、待遇等，不能接“本地行动如何……”这类说明意义的从句。"}, {"text": "收获", "is_correct": false, "explanation": "搭配：“收获”的宾语是成果、经验等具体结果，不能直接接“本地行动如何……”的从句。"}], "explanations": {"诠释": "诠释：把本地行动的意义说清楚，与“恰如其分地”搭配自然。", "破坏": "语义：“破坏”指毁坏，与“恰如其分”和“凝聚起一种……希望”的正面语义相反。", "享受": "搭配：“享受”接的是生活、待遇等，不能接“本地行动如何……”这类说明意义的从句。", "收获": "搭配：“收获”的宾语是成果、经验等具体结果，不能直接接“本地行动如何……”的从句。"}, "sentence_index": 0, "correct_answer": "诠释"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他诠释了一瓶矿泉水。", "explanation": "这里应该用〈喝〉。诠释的对象是需要说明含义的内容，矿泉水是实物，不能诠释。"}, {"text": "老师诠释了那个学生。", "explanation": "诠释的对象是需要说明含义的词句、作品或理念，不能是人；这里应该用〈了解〉。"}, {"text": "我把那辆车诠释了一遍。", "explanation": "诠释的对象是需要说明含义的内容，车是实物，不能诠释；这里应该用〈检查〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12350, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "诠释", "is_correct": true, "explanation": "诠释（quán shì）：对事物作出解释、阐明含义，即本题目标词。"}, {"text": "宣誓", "is_correct": false, "explanation": "宣誓（xuān shì）与诠释的第一个音节声母不同：xuān 声母为 x，quán 声母为 q，意思是公开表示誓言。"}, {"text": "劝世", "is_correct": false, "explanation": "劝世（quàn shì）与诠释（quán shì）的第一个音节声调不同：quàn 为第四声，quán 为第二声，意思是劝人向善、警醒世人。"}, {"text": "泉石", "is_correct": false, "explanation": "泉石（quán shí）与诠释的第二个音节声调不同：shí 为第二声，shì 为第四声，指泉水与山石，多用于描写山水。"}], "explanations": {"诠释": "诠释（quán shì）：对事物作出解释、阐明含义，即本题目标词。", "宣誓": "宣誓（xuān shì）与诠释的第一个音节声母不同：xuān 声母为 x，quán 声母为 q，意思是公开表示誓言。", "劝世": "劝世（quàn shì）与诠释（quán shì）的第一个音节声调不同：quàn 为第四声，quán 为第二声，意思是劝人向善、警醒世人。", "泉石": "泉石（quán shí）与诠释的第二个音节声调不同：shí 为第二声，shì 为第四声，指泉水与山石，多用于描写山水。"}, "sentence_index": null, "correct_answer": "诠释"}, "level_3": {"options": [{"text": "诠释", "is_correct": true, "explanation": "诠释：把青春的快乐与烦恼的含义表达出来，与“这首歌”的主语相符。"}, {"text": "购买", "is_correct": false, "explanation": "语义：快乐和烦恼是抽象感受，不是可以购买的物品，与“这首歌”搭配不通。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”需要有意识的主体，歌曲本身不能忘记，与句子的语境冲突。"}, {"text": "撕毁", "is_correct": false, "explanation": "搭配：“撕毁”的宾语是纸张、合同等具体物件，不能接“快乐和烦恼”。"}], "explanations": {"诠释": "诠释：把青春的快乐与烦恼的含义表达出来，与“这首歌”的主语相符。", "购买": "语义：快乐和烦恼是抽象感受，不是可以购买的物品，与“这首歌”搭配不通。", "忘记": "语义：“忘记”需要有意识的主体，歌曲本身不能忘记，与句子的语境冲突。", "撕毁": "搭配：“撕毁”的宾语是纸张、合同等具体物件，不能接“快乐和烦恼”。"}, "sentence_index": 6, "correct_answer": "诠释"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天诠释了一张足球比赛的门票。", "explanation": "这里应该用〈检查〉。诠释的对象是需要说明含义的内容，门票是实物，不能诠释。"}, {"text": "他诠释了这次旅行的费用。", "explanation": "这里应该用〈计算〉。诠释是说明含义，费用需要的是计算数额，而不是解释含义。"}, {"text": "妈妈诠释了这盘红烧肉。", "explanation": "诠释的对象是需要说明含义的内容，红烧肉是食物，这里应该用〈烹饪〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12350, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首诗诠释于作者对家乡的思念。", "corrected_sentence": "这首诗诠释了作者对家乡的思念。", "error_description": "误用介词“于”。“诠释”后直接带宾语，不加“于”，应说“诠释了作者对家乡的思念”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12350, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部纪录片对诠释了人与自然的关系。", "corrected_sentence": "这部纪录片诠释了人与自然的关系。", "error_description": "“诠释”是及物动词，后面直接带宾语，不能在它前面加介词“对”构成“对诠释了”；应说“诠释了人与自然的关系”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12351, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12351, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12351, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "活的生物体，通常指用于实验或移植的活组织或器官。", "primary_collocate": null, "pronunciation": "huó tǐ", "ipa": "xuo̯˧˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "研究团队没有止步于细胞培养皿中的结果，而是在活体上持续观察这种药物对器官组织的长期影响。", "target_word": "活体", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这种药要先在活体上做实验。", "target_word": "活体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里的活体比死的标本更有研究价值。", "target_word": "活体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，这个器官必须来自健康的活体。", "target_word": "活体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家在活体上观察细胞怎么变化。", "target_word": "活体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们没有用死的，而是用活体做了实验。", "target_word": "活体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里放的是标本，不是活体。", "target_word": "活体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究活体的反应，需要很多时间。", "target_word": "活体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个肝脏来自活体，不是来自死者。", "target_word": "活体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些小鼠是活体，不能随便处理。", "target_word": "活体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "活體", "label": "繁体"}, {"form": "活体组织", "label": "复合"}, {"form": "活体检测", "label": "复合"}], "register": "书面", "sense_fingerprint": "活的生物体，用于实验或移植", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c129f6d-1946-456e-a53b-85dab20cb751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12351, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活体", "is_correct": true, "explanation": "正确：「活体」指活的生物身体，句中要在活体上观察药物对器官组织的长期影响。"}, {"text": "文本", "is_correct": false, "explanation": "语义：「文本」是书面材料，不能被持续观察其对器官组织的长期影响。"}, {"text": "文字", "is_correct": false, "explanation": "语义：「文字」是书写的符号，不能被观察其对器官组织的长期影响。"}, {"text": "文献", "is_correct": false, "explanation": "搭配：「文献」只能阅读，不能在其上观察生理变化，「在文献上观察」不成立。"}], "explanations": {"活体": "正确：「活体」指活的生物身体，句中要在活体上观察药物对器官组织的长期影响。", "文本": "语义：「文本」是书面材料，不能被持续观察其对器官组织的长期影响。", "文字": "语义：「文字」是书写的符号，不能被观察其对器官组织的长期影响。", "文献": "搭配：「文献」只能阅读，不能在其上观察生理变化，「在文献上观察」不成立。"}, "sentence_index": 0, "correct_answer": "活体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师把一只蝴蝶活体挂在教室墙上。", "explanation": "这里应该用〈标本〉。活体指活着的生物身体，用于实验或移植；挂在墙上展示的是标本，不是活体。"}, {"text": "葬礼上大家向逝者的活体告别。", "explanation": "这里应该用〈遗体〉。逝者已经去世，「活体」指活着的身体，不能用来指逝者的遗体。"}, {"text": "法医说这个活体已经死了三天。", "explanation": "这里应该用〈尸体〉。「活体」指活着的身体，不能说它已经死了三天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12351, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活体", "is_correct": true, "explanation": "正确：前句说的是标本，后句以「不是」对比出活着的身体。"}, {"text": "水果", "is_correct": false, "explanation": "语义：整句讲的是标本与活体的对比，「不是水果」与语境无关。"}, {"text": "游客", "is_correct": false, "explanation": "搭配：「放」的对象是物品或标本，不能放「游客」。"}, {"text": "博物馆", "is_correct": false, "explanation": "语义：「博物馆里放的是标本，不是博物馆」自相矛盾，语义不通。"}], "explanations": {"活体": "正确：前句说的是标本，后句以「不是」对比出活着的身体。", "水果": "语义：整句讲的是标本与活体的对比，「不是水果」与语境无关。", "游客": "搭配：「放」的对象是物品或标本，不能放「游客」。", "博物馆": "语义：「博物馆里放的是标本，不是博物馆」自相矛盾，语义不通。"}, "sentence_index": 6, "correct_answer": "活体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场事故夺去了他的活体。", "explanation": "这里应该用〈生命〉。「生命」指人的性命，「活体」只指活的身体或活组织，不能用来指生命本身。"}, {"text": "果农在果园里摘下了成熟的活体。", "explanation": "这里应该用〈果实〉。果实是植物结出的果子，「活体」指活的身体或活组织，不能用来指水果。"}, {"text": "研究员下载了大量活体。", "explanation": "这里应该用〈文件〉。「下载」针对电子文件，「活体」指活的身体或活组织，不能下载。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12351, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张活体要定时喂养。", "corrected_sentence": "这只活体要定时喂养。", "error_description": "量词错误：「活体」指活的动物或身体，应用量词「只」。「张」只用于纸、画等平面的东西，应说「这只活体」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12351, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "实验室里有两个的活体。", "corrected_sentence": "实验室里有两个活体。", "error_description": "结构助词错误：数量短语与名词之间不用「的」，应说「两个活体」，「两个的活体」多加了「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
