INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12352, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12352, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指在某个地区世代居住、最早定居的居民，与后来迁入的移民相对。", "primary_collocate": null, "pronunciation": "yuán zhù mín", "ipa": "ɥɛn˧˥ ʈʂu˥˩ min˧˥", "syllable_count": 3, "sentences": [{"text": "这种非文本化的历史表达，在许多原住民社会中体现为“梦世纪”（Dreamtime）式的宇宙观叙述，其中祖先的行动与自然地貌的形成互为映射，时间并非线性推进，而是以神话事件为节点循环重启。", "target_word": "原住民", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个岛上的原住民住了几百年。", "target_word": "原住民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原住民很熟悉这片森林。", "target_word": "原住民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客来了以后，原住民的生活变了。", "target_word": "原住民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原住民和后来的移民常常一起过节。", "target_word": "原住民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想保护原住民的语言。", "target_word": "原住民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老人是山里的原住民。", "target_word": "原住民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原住民会唱很多古老的歌。", "target_word": "原住民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去访问了几位原住民。", "target_word": "原住民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的原住民比移民早到很多年。", "target_word": "原住民", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "原住民族", "label": "复合"}], "register": "中性", "sense_fingerprint": "世代居住的最早居民，与移民相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c129f6d-1946-456e-a53b-85dab20cb751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12352, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原住民", "is_correct": true, "explanation": "正确：句子讨论的是最早居住者的神话式历史表达，「原住民社会」与之相符。"}, {"text": "文字", "is_correct": false, "explanation": "语义：句中的历史表达是「非文本化」的，「文字社会」与之矛盾。"}, {"text": "书面", "is_correct": false, "explanation": "语义：整句强调口头讲述和神话循环，「书面社会」与之相反。"}, {"text": "学院", "is_correct": false, "explanation": "搭配：「社会」前应是人群或文化类型，「学院」不能用来修饰「社会」构成类型。"}], "explanations": {"原住民": "正确：句子讨论的是最早居住者的神话式历史表达，「原住民社会」与之相符。", "文字": "语义：句中的历史表达是「非文本化」的，「文字社会」与之矛盾。", "书面": "语义：整句强调口头讲述和神话循环，「书面社会」与之相反。", "学院": "搭配：「社会」前应是人群或文化类型，「学院」不能用来修饰「社会」构成类型。"}, "sentence_index": 0, "correct_answer": "原住民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新来的原住民在村口登记入住。", "explanation": "这里应该用〈游客〉。原住民是世代居住在当地的人，不会是新来登记入住的人。"}, {"text": "原住民刚到的时候，常常要学习当地的语言。", "explanation": "这里应该用〈移民〉。原住民最早就住在当地，不会是刚到、需要学习当地语言的人。"}, {"text": "原住民为了寻找新大陆，漂洋过海来到这里。", "explanation": "这里应该用〈探险家〉。原住民一直住在这里，不会是为了寻找新大陆而漂洋过海来的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12352, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原住民", "is_correct": true, "explanation": "正确：「那位老人是山里的」后接指人且世代居住的群体，「原住民」符合语境。"}, {"text": "城市", "is_correct": false, "explanation": "语义：整句说的是一位老人，「老人是城市」与语境不合。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：「是……的」后面的名词应指人，「工厂」不能指老人。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：「山里的海洋」与「山里」的地点矛盾，句意不通。"}], "explanations": {"原住民": "正确：「那位老人是山里的」后接指人且世代居住的群体，「原住民」符合语境。", "城市": "语义：整句说的是一位老人，「老人是城市」与语境不合。", "工厂": "搭配：「是……的」后面的名词应指人，「工厂」不能指老人。", "海洋": "语义：「山里的海洋」与「山里」的地点矛盾，句意不通。"}, "sentence_index": 6, "correct_answer": "原住民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一个原住民刚搬到这个村子。", "explanation": "这里应该用〈外国人〉。原住民是最早定居的居民，不会是刚搬来的人。"}, {"text": "这个村子的原住民是两百年前迁来的。", "explanation": "这里应该用〈移民〉。原住民指最早住在这里的人，不是从外地迁来的人。"}, {"text": "原住民直到上个世纪才来到这座岛。", "explanation": "这里应该用〈殖民者〉。原住民最早就住在这里，不会是上个世纪才来到这座岛的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们对原住民学习了编织的方法。", "corrected_sentence": "我们向原住民学习了编织的方法。", "error_description": "介词错误：向人学习应说「向……学习」，「对……学习」不能表示向对方求教，应改为「向原住民学习」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个村子的一只原住民很热情。", "corrected_sentence": "这个村子的一位原住民很热情。", "error_description": "量词错误：「原住民」指人，应用量词「位」或「个」，「只」多用于动物，不能说「一只原住民」，应说「一位原住民」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
