INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12354, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "计算年代的单位，一百年为一个世纪。", "primary_collocate": null, "pronunciation": "shì jì", "ipa": "ʂɻ̩˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "二十一世纪是网络的时代。", "target_word": "世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老桥已经有一个世纪的历史了。", "target_word": "世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上个世纪，很多人住在农村。", "target_word": "世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十九世纪的欧洲有很多著名的画家。", "target_word": "世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个世纪等于一百年。", "target_word": "世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家老店开了大半个世纪。", "target_word": "世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷出生在二十世纪五十年代。", "target_word": "世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市在过去的一个世纪里发展得很快。", "target_word": "世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了一个世纪，这里变化很大。", "target_word": "世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本世纪的科学发展特别快。", "target_word": "世纪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个世纪", "label": "量词"}, {"form": "新世纪", "label": "复合"}, {"form": "上世纪", "label": "复合"}, {"form": "世紀", "label": "繁体"}], "register": "通用", "sense_fingerprint": "计算年代的单位，一百年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c129f6d-1946-456e-a53b-85dab20cb751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12354, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "世纪", "is_correct": true, "explanation": "世纪（shìjì）是本题目标词，指计算年代的单位，一百年。"}, {"text": "四季", "is_correct": false, "explanation": "四季（sìjì）与 shìjì 声母不同（s 与 sh），意思是一年的四个季节。"}, {"text": "时机", "is_correct": false, "explanation": "时机（shíjī）两个音节的声调都与 shìjì 不同，意思是合适的机会。"}, {"text": "诗集", "is_correct": false, "explanation": "诗集（shījí）两个音节的声调都与 shìjì 不同，意思是诗歌的汇编。"}], "explanations": {"世纪": "世纪（shìjì）是本题目标词，指计算年代的单位，一百年。", "四季": "四季（sìjì）与 shìjì 声母不同（s 与 sh），意思是一年的四个季节。", "时机": "时机（shíjī）两个音节的声调都与 shìjì 不同，意思是合适的机会。", "诗集": "诗集（shījí）两个音节的声调都与 shìjì 不同，意思是诗歌的汇编。"}, "sentence_index": null, "correct_answer": "世纪"}, "level_3": {"options": [{"text": "世纪", "is_correct": true, "explanation": "世纪是百年为单位，与“二十一”搭配，指二十一世纪。"}, {"text": "月", "is_correct": false, "explanation": "语义：“二十一月”不是一个时段，“二十一月是网络的时代”说不通。"}, {"text": "天", "is_correct": false, "explanation": "语义：“二十一天”是很短的时段，与“网络的时代”的历史含义不合。"}, {"text": "版本", "is_correct": false, "explanation": "搭配：“二十一版本”是版本号，不能用作时间单位，与“二十一”搭配不当。"}], "explanations": {"世纪": "世纪是百年为单位，与“二十一”搭配，指二十一世纪。", "月": "语义：“二十一月”不是一个时段，“二十一月是网络的时代”说不通。", "天": "语义：“二十一天”是很短的时段，与“网络的时代”的历史含义不合。", "版本": "搭配：“二十一版本”是版本号，不能用作时间单位，与“二十一”搭配不当。"}, "sentence_index": 0, "correct_answer": "世纪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "八十世纪的歌很好听。", "explanation": "这里应该用〈年代〉。“八十年代”指十年左右的时段，世纪是一百年，不能用“八十世纪”表示。"}, {"text": "他今年二十世纪了。", "explanation": "这里应该用〈岁〉。世纪是一百年的时间单位，说人的年龄要用岁。"}, {"text": "那些世纪很难忘。", "explanation": "这里应该用〈岁月〉。世纪是固定的百年单位，指回忆中泛泛的时光要用岁月。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12354, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "世纪", "is_correct": true, "explanation": "世纪（shìjì）是本题目标词，指计算年代的单位，一百年。"}, {"text": "实际", "is_correct": false, "explanation": "实际（shíjì）首音节声调与 shì 不同，意思是真实的情况。"}, {"text": "市集", "is_correct": false, "explanation": "市集（shìjí）末音节声调与 jì 不同，意思是集市。"}, {"text": "十几", "is_correct": false, "explanation": "十几（shíjǐ）两个音节的声调都与 shìjì 不同，意思是十多个。"}], "explanations": {"世纪": "世纪（shìjì）是本题目标词，指计算年代的单位，一百年。", "实际": "实际（shíjì）首音节声调与 shì 不同，意思是真实的情况。", "市集": "市集（shìjí）末音节声调与 jì 不同，意思是集市。", "十几": "十几（shíjǐ）两个音节的声调都与 shìjì 不同，意思是十多个。"}, "sentence_index": null, "correct_answer": "世纪"}, "level_3": {"options": [{"text": "世纪", "is_correct": true, "explanation": "世纪是百年为单位，此处指二十世纪，与“二十”和“五十年代”相连。"}, {"text": "季节", "is_correct": false, "explanation": "语义：“季节”不是百年单位，“二十季节”无法表示时段。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“二十星期”只是很短的时段，与“五十年代”的时间不合。"}, {"text": "年份", "is_correct": false, "explanation": "搭配：“二十年份”不是固定说法，“年份”不与“二十”搭配作时间单位。"}], "explanations": {"世纪": "世纪是百年为单位，此处指二十世纪，与“二十”和“五十年代”相连。", "季节": "语义：“季节”不是百年单位，“二十季节”无法表示时段。", "星期": "语义：“二十星期”只是很短的时段，与“五十年代”的时间不合。", "年份": "搭配：“二十年份”不是固定说法，“年份”不与“二十”搭配作时间单位。"}, "sentence_index": 6, "correct_answer": "世纪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这世纪要在十二月结束。", "explanation": "这里应该用〈学期〉。世纪是百年为单位，不能指几个月的教学时段。"}, {"text": "他的世纪有二十年了。", "explanation": "这里应该用〈工龄〉。世纪是百年为单位，工作的年限不能用世纪表示。"}, {"text": "这棵树的世纪有几百年。", "explanation": "这里应该用〈寿命〉。世纪只是时间单位，不能用来表示树的寿命。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12354, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所老学校已经有两条世纪的历史了。", "corrected_sentence": "这所老学校已经有两个世纪的历史了。", "error_description": "量词错误：“世纪”前应用“个”，“条”用于细长的东西，不能用于世纪。正确说法是“两个世纪的历史”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12354, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二十一的世纪的医学进步很快。", "corrected_sentence": "二十一世纪的医学进步很快。", "error_description": "修饰语错误：“二十一”与“世纪”之间不能加“的”，应说“二十一世纪”。正确说法是“二十一世纪的医学进步很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
