INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12355, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人们对宇宙的整体认识和根本观点，包括对宇宙的起源、结构、演化等问题的看法。", "primary_collocate": null, "pronunciation": "yǔ zhòu guān", "ipa": "y˨˩ ʈʂoʊ˥˩ kwan˥", "syllable_count": 3, "sentences": [{"text": "这种非文本化的历史表达，在许多原住民社会中体现为“梦世纪”（Dreamtime）式的宇宙观叙述，其中祖先的行动与自然地貌的形成互为映射，时间并非线性推进，而是以神话事件为节点循环重启。", "target_word": "宇宙观", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "古人看星星，他们的宇宙观和我们不同。", "target_word": "宇宙观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位天文学家的宇宙观影响了很多人。", "target_word": "宇宙观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习天文以后，他的宇宙观变了。", "target_word": "宇宙观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个民族都有自己的宇宙观。", "target_word": "宇宙观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了中国古代的宇宙观。", "target_word": "宇宙观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认为宇宙很大，这是他的宇宙观。", "target_word": "宇宙观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的宇宙观里，地球只是很小的一部分。", "target_word": "宇宙观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宗教和科学常常有不同的宇宙观。", "target_word": "宇宙观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请我们谈谈各自的宇宙观。", "target_word": "宇宙观", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种宇宙观", "label": "量词"}, {"form": "宇宙觀", "label": "繁体"}], "register": "书面", "sense_fingerprint": "对宇宙起源与结构的整体看法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c129f6d-1946-456e-a53b-85dab20cb751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12355, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宇宙观", "is_correct": true, "explanation": "正确：“宇宙观”指对宇宙起源、结构的整体看法，与“梦世纪”式的叙述相合。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”是人的生理指标，不能修饰“叙述”，与“梦世纪”式的说法不合。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”口语色彩重，与这段学术性的书面表述不合。"}, {"text": "价钱", "is_correct": false, "explanation": "搭配：“价钱”指价格，不能用来修饰“叙述”，这里指的是对宇宙的看法。"}], "explanations": {"宇宙观": "正确：“宇宙观”指对宇宙起源、结构的整体看法，与“梦世纪”式的叙述相合。", "体温": "搭配：“体温”是人的生理指标，不能修饰“叙述”，与“梦世纪”式的说法不合。", "八卦": "语域：“八卦”口语色彩重，与这段学术性的书面表述不合。", "价钱": "搭配：“价钱”指价格，不能用来修饰“叙述”，这里指的是对宇宙的看法。"}, "sentence_index": 0, "correct_answer": "宇宙观"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他有一块宇宙观，很特别。", "explanation": "这里应该用〈种〉。宇宙观是抽象的看法，不能用〈块〉计量，应说“一种宇宙观”。"}, {"text": "周末我们去宇宙观看星星。", "explanation": "这里把宇宙观当成了可以去的地方，但它指对宇宙的根本看法，不是场所或建筑。"}, {"text": "我对这个问题的宇宙观是：应该多听别人的意见。", "explanation": "这里应该用〈观点〉。宇宙观专指对宇宙的根本看法，不能用于一般问题的意见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12355, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宇宙观", "is_correct": true, "explanation": "正确：前句说“宇宙很大”，“宇宙观”正是对宇宙的整体看法。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”指做饭的地方，与前句“认为宇宙很大”的看法无关。"}, {"text": "长相", "is_correct": false, "explanation": "体貌：“长相”指外在容貌，与“认为宇宙很大”所表达的看法不符。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，与前句所说的看法无关。"}], "explanations": {"宇宙观": "正确：前句说“宇宙很大”，“宇宙观”正是对宇宙的整体看法。", "厨房": "语义：“厨房”指做饭的地方，与前句“认为宇宙很大”的看法无关。", "长相": "体貌：“长相”指外在容貌，与“认为宇宙很大”所表达的看法不符。", "体重": "语义：“体重”指身体的重量，与前句所说的看法无关。"}, "sentence_index": 6, "correct_answer": "宇宙观"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的宇宙观是：每个人都要当宇航员。", "explanation": "这里应该用〈理想〉。宇宙观是对宇宙的看法，不指想要实现的目标。"}, {"text": "他的宇宙观是：人生要多行善。", "explanation": "这里应该用〈人生观〉。宇宙观讲对宇宙的看法，谈对人生的态度要说〈人生观〉。"}, {"text": "她有一条宇宙观，很特别。", "explanation": "这里应该用〈种〉。宇宙观是抽象的看法，不能用〈条〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12355, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只宇宙观很特别。", "corrected_sentence": "这种宇宙观很特别。", "error_description": "错误：量词“只”。宇宙观是抽象的看法，应用“种”计量，不能用“只”；正确为“这种宇宙观”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12355, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班每人都有一条宇宙观。", "corrected_sentence": "我们班每人都有一种宇宙观。", "error_description": "错误：量词“条”。宇宙观是抽象的看法，应用“种”计量，不能用“条”；正确为“一种宇宙观”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
