INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12358, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "表示双方彼此互相充当对方的某种角色或关系，常用于“互为＋名词”，如“互为朋友”“互为因果”。", "primary_collocate": null, "pronunciation": "hù wéi", "ipa": "xu˥˩ wei˧˥", "syllable_count": 2, "sentences": [{"text": "这种非文本化的历史表达，在许多原住民社会中体现为“梦世纪”（Dreamtime）式的宇宙观叙述，其中祖先的行动与自然地貌的形成互为映射，时间并非线性推进，而是以神话事件为节点循环重启。", "target_word": "互为", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他们俩互为朋友，常常一起吃饭。", "target_word": "互为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个国家互为邻国，关系很好。", "target_word": "互为", "complexity_tier": "T3", "furigana": "zhè liǎng ge guójiā hùwéi línguó, guānxi hěn hǎo.", "sentence_source": "generated"}, {"text": "我和姐姐互为榜样，一起进步。", "target_word": "互为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原因和结果有时互为因果。", "target_word": "互为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两家店互为对手，生意都很好。", "target_word": "互为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大和小互为反义词。", "target_word": "互为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们互为老师，大家一起学习。", "target_word": "互为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们住在对面，互为邻居已经十年了。", "target_word": "互为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夫妻互为依靠，一起过日子。", "target_word": "互为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "双方彼此互为对方的某种关系或角色（互为＋名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e91bde6c-52b5-4ae7-a420-fee8d81555dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12358, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参与", "is_correct": false, "explanation": "搭配：“参与”后接活动、事务，不说“参与映射”。"}, {"text": "包含", "is_correct": false, "explanation": "语义：“包含”表示其中有某物，与句中两者彼此映射的意思不合。"}, {"text": "互为", "is_correct": true, "explanation": "互为：表示彼此互相充当对方的某种关系，与句中“互为映射”相符。"}, {"text": "承担", "is_correct": false, "explanation": "搭配：“承担”后接责任、任务，不说“承担映射”。"}], "explanations": {"参与": "搭配：“参与”后接活动、事务，不说“参与映射”。", "包含": "语义：“包含”表示其中有某物，与句中两者彼此映射的意思不合。", "互为": "互为：表示彼此互相充当对方的某种关系，与句中“互为映射”相符。", "承担": "搭配：“承担”后接责任、任务，不说“承担映射”。"}, "sentence_index": 0, "correct_answer": "互为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他互为老师，很关心学生。", "explanation": "这里应该用〈作为〉。“互为”表示双方互相充当对方的某种角色，句中只有“他”一方，应说“作为老师”。"}, {"text": "姐姐互为我的老师，只有她教我中文。", "explanation": "这里应该用〈是〉。“互为”表示双方互相充当对方的某种角色，这里只是姐姐教我，应说“是我的老师”。"}, {"text": "我互为姐姐的榜样，一起进步。", "explanation": "这里应该用〈是〉。“互为”需要双方，句中只有“我”一方，应说“是姐姐的榜样”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12358, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃掉", "is_correct": false, "explanation": "语义：“吃掉”需要可吃的对象，不能与“反义词”搭配，句子不通。"}, {"text": "互为", "is_correct": true, "explanation": "互为：表示大与小彼此互为对方的一面，与“大和小”的关系相符。"}, {"text": "包括", "is_correct": false, "explanation": "语义：“包括”表示包含，大和小之间并不是包含关系。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：“打碎”指使物体破裂，不能与“反义词”搭配，句子不通。"}], "explanations": {"吃掉": "语义：“吃掉”需要可吃的对象，不能与“反义词”搭配，句子不通。", "互为": "互为：表示大与小彼此互为对方的一面，与“大和小”的关系相符。", "包括": "语义：“包括”表示包含，大和小之间并不是包含关系。", "打碎": "语义：“打碎”指使物体破裂，不能与“反义词”搭配，句子不通。"}, "sentence_index": 6, "correct_answer": "互为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和老师互为学生，她每天教我中文。", "explanation": "这里应该用〈是〉。“老师”与“学生”是单向的授受关系，老师并不是“我”的学生，故不能用“互为”。"}, {"text": "妈妈互为女儿的依靠，每天接送她上学。", "explanation": "这里应该用〈是〉。“互为”强调双方彼此付出，这里只是妈妈单方面照顾女儿，应说“是女儿的依靠”。"}, {"text": "我互为依靠，一个人过日子很好。", "explanation": "这里应该用〈是〉。“互为”需要双方，句中只有“我”一方，应说“是依靠”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12358, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个人互为了朋友已经很多年了。", "corrected_sentence": "这两个人互为朋友已经很多年了。", "error_description": "“了”误加在“互为”之后。“了”应放在整个短语的末尾，正确句子为“互为朋友已经很多年了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12358, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两位邻居互为了对方的依靠。", "corrected_sentence": "两位邻居互为对方的依靠。", "error_description": "“了”误加在“互为”之后。“互为”后不需要“了”，句中是陈述，正确为“互为对方的依靠”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
