INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12361, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指历史上或生活中发生的有一定影响的事情。", "primary_collocate": null, "pronunciation": "shì jiàn", "ipa": "ʂɻ̩⁵¹ tɕjɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "这个事件改变了很多人的生活。", "target_word": "事件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了一个历史事件。", "target_word": "事件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那起事件发生在十年前。", "target_word": "事件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上每天都有新的事件。", "target_word": "事件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个事件对城市的影响很大。", "target_word": "事件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一篇关于这个事件的文章。", "target_word": "事件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要记住这次重要的事件。", "target_word": "事件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个很有名的历史事件。", "target_word": "事件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察正在调查昨天的事件。", "target_word": "事件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个事件让大家都很吃惊。", "target_word": "事件", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "起", "label": "量词"}, {"form": "突发事件", "label": "复合"}], "register": "中性", "sense_fingerprint": "历史或生活中有影响的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e91bde6c-52b5-4ae7-a420-fee8d81555dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12361, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "事件", "is_correct": true, "explanation": "正确答案，shì jiàn，指历史或生活中有一定影响的事情。"}, {"text": "世界", "is_correct": false, "explanation": "jiè（第四声）与 jiàn（第四声）韵母不同（ie／ian），声调相同，意思是“世界”。"}, {"text": "时间", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，jiān（第一声）与 jiàn（第四声）声调也不同，意思是“时间”。"}, {"text": "实践", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，jiàn 相同，意思是“实践”。"}, {"text": "世间", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）声调不同，shì 相同，意思是“世间”。"}], "explanations": {"事件": "正确答案，shì jiàn，指历史或生活中有一定影响的事情。", "世界": "jiè（第四声）与 jiàn（第四声）韵母不同（ie／ian），声调相同，意思是“世界”。", "时间": "shí（第二声）与 shì（第四声）声调不同，jiān（第一声）与 jiàn（第四声）声调也不同，意思是“时间”。", "实践": "shí（第二声）与 shì（第四声）声调不同，jiàn 相同，意思是“实践”。", "世间": "jiān（第一声）与 jiàn（第四声）声调不同，shì 相同，意思是“世间”。"}, "sentence_index": null, "correct_answer": "事件"}, "level_3": {"options": [{"text": "事件", "is_correct": true, "explanation": "正确。“事件”作主语，与“改变了很多人的生活”的重大影响相符。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘是家具，不能改变很多人的生活，与“改变生活”的重大影响不符。"}, {"text": "扫帚", "is_correct": false, "explanation": "语义：扫帚是清洁工具，与“改变很多人的生活”的影响不相称。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“改变”的主语多为事件、政策等，“颜色”不能与“改变了很多人的生活”搭配。"}], "explanations": {"事件": "正确。“事件”作主语，与“改变了很多人的生活”的重大影响相符。", "窗帘": "语义：窗帘是家具，不能改变很多人的生活，与“改变生活”的重大影响不符。", "扫帚": "语义：扫帚是清洁工具，与“改变很多人的生活”的影响不相称。", "颜色": "搭配：“改变”的主语多为事件、政策等，“颜色”不能与“改变了很多人的生活”搭配。"}, "sentence_index": 0, "correct_answer": "事件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我给弟弟讲了一个睡前事件。", "explanation": "这里应该用〈故事〉。事件指发生过、有影响的大事，给弟弟讲的睡前内容应说“故事”。"}, {"text": "学校这周举办了一场篮球事件。", "explanation": "这里应该用〈比赛〉。事件指发生过的有影响的事，有计划举办的篮球活动应说“比赛”。"}, {"text": "这位作家的新事件很受欢迎。", "explanation": "这里应该用〈作品〉。事件指发生过的有影响的事，不指作家创作的书或文章，应说“作品”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12361, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事件", "is_correct": true, "explanation": "正确。“这次重要的”修饰的是值得铭记的大事，符合语境。"}, {"text": "橡皮", "is_correct": false, "explanation": "语义：橡皮是文具，不是需要铭记的重要事件，与“记住”的语境不符。"}, {"text": "拖鞋", "is_correct": false, "explanation": "语义：拖鞋是日用品，不是值得铭记的重要事件，与“记住”的语境不符。"}, {"text": "水杯", "is_correct": false, "explanation": "语义：水杯是日用器具，不是值得铭记的重要事件，与前文的语境不合。"}], "explanations": {"事件": "正确。“这次重要的”修饰的是值得铭记的大事，符合语境。", "橡皮": "语义：橡皮是文具，不是需要铭记的重要事件，与“记住”的语境不符。", "拖鞋": "语义：拖鞋是日用品，不是值得铭记的重要事件，与“记住”的语境不符。", "水杯": "语义：水杯是日用器具，不是值得铭记的重要事件，与前文的语境不合。"}, "sentence_index": 6, "correct_answer": "事件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校组织了一次事件，同学们都很开心。", "explanation": "这里应该用〈活动〉。组织的是活动，“事件”指已经发生的有影响的事情，不能用来组织。"}, {"text": "晚会上的事件很精彩。", "explanation": "这里应该用〈节目〉。事件指发生过的有影响的事，晚会上表演的内容应说“节目”。"}, {"text": "跑步已经成了他的事件，他每天都坚持。", "explanation": "这里应该用〈习惯〉。“事件”指发生过的有影响的事情，不能指每天重复的习惯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12361, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只事件发生后，大家都很紧张。", "corrected_sentence": "那起事件发生后，大家都很紧张。", "error_description": "“只”用于动物、成对物品等个体，不能修饰事件；事件的量词是“起”，应改为“那起事件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12361, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些事件们都引起了大家的关注。", "corrected_sentence": "这些事件都引起了大家的关注。", "error_description": "“们”一般只加在指人或拟人的名词后面，事件是抽象事物，不能说“事件们”；应去掉“们”，直接说“这些事件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12363, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12363, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12363, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "重新启动，指停止或关闭后再开始运行；也可指中断后重新恢复进行。", "primary_collocate": null, "pronunciation": "chóng qǐ", "ipa": "ʈʂʰʊŋ³⁵ tɕʰi²¹⁴", "syllable_count": 2, "sentences": [{"text": "这种非文本化的历史表达，在许多原住民社会中体现为“梦世纪”（Dreamtime）式的宇宙观叙述，其中祖先的行动与自然地貌的形成互为映射，时间并非线性推进，而是以神话事件为节点循环重启。", "target_word": "重启", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "电脑坏了，你重启一下吧。", "target_word": "重启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没有反应，我只好重启它。", "target_word": "重启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "系统更新后需要重启。", "target_word": "重启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司准备下个月重启这个项目。", "target_word": "重启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想重启自己的生意。", "target_word": "重启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国决定重启谈判。", "target_word": "重启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人重启了停下来的机器。", "target_word": "重启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "重启以后，网页就能打开了。", "target_word": "重启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂明年会重启生产。", "target_word": "重启", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "重启了", "label": "体标"}, {"form": "重启过", "label": "体标"}], "register": "中性", "sense_fingerprint": "停止后重新开始运行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e91bde6c-52b5-4ae7-a420-fee8d81555dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12363, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重启", "is_correct": true, "explanation": "正确：“循环重启”指周而复始地重新开始，符合“循环”的意思。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“循环”意味着周而复始，说“循环停止”与“循环”矛盾，句意不通。"}, {"text": "结束", "is_correct": false, "explanation": "语义：“循环结束”否定了循环的周期性，与“以神话事件为节点”的叙述不符。"}, {"text": "删除", "is_correct": false, "explanation": "搭配：“删除”的对象多为文件、数据，不能与“循环”搭配。"}], "explanations": {"重启": "正确：“循环重启”指周而复始地重新开始，符合“循环”的意思。", "停止": "语义：“循环”意味着周而复始，说“循环停止”与“循环”矛盾，句意不通。", "结束": "语义：“循环结束”否定了循环的周期性，与“以神话事件为节点”的叙述不符。", "删除": "搭配：“删除”的对象多为文件、数据，不能与“循环”搭配。"}, "sentence_index": 0, "correct_answer": "重启"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "手术后他的身体终于重启了。", "explanation": "这里应该用〈恢复〉。身体康复是状态复原，不是重新开始运行，应说恢复。"}, {"text": "我把那杯牛奶重启了。", "explanation": "这里应该用〈加热〉。牛奶不是可以重新启动的对象，要升温应说加热。"}, {"text": "这台电脑一直在运行，我们从没关机，却把它重启了。", "explanation": "这里应该用〈重新运行〉。重启要求先关机，这台电脑从没关机，只能说重新运行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12363, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重启", "is_correct": true, "explanation": "正确：“重启谈判”指中断后重新开始谈判，与“决定”搭配自然。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对机器或物品，不能与“谈判”搭配。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指转换语言，“决定翻译谈判”句意不通。"}, {"text": "拍摄", "is_correct": false, "explanation": "语义：“拍摄”指用摄像设备录下画面，与谈判无关。"}], "explanations": {"重启": "正确：“重启谈判”指中断后重新开始谈判，与“决定”搭配自然。", "修理": "搭配：“修理”针对机器或物品，不能与“谈判”搭配。", "翻译": "语义：“翻译”指转换语言，“决定翻译谈判”句意不通。", "拍摄": "语义：“拍摄”指用摄像设备录下画面，与谈判无关。"}, "sentence_index": 6, "correct_answer": "重启"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他重启了文件的标题。", "explanation": "这里应该用〈修改〉。文件标题要改，应说修改，不说重启。"}, {"text": "这份合同签好了，我们把它重启了。", "explanation": "这里应该用〈续签〉。合同要重新签一次，应说续签，不说重启。"}, {"text": "我把那杯茶重启了一遍，又喝了一口。", "explanation": "这里应该用〈重泡〉。重启不用于茶，茶要再泡一次应说重泡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12363, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你重启了一下路由器。", "corrected_sentence": "请你重启一下路由器。", "error_description": "祈使句（请你……）中“重启”后不应加“了”，应说“重启一下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12363, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台打印机重启了一个。", "corrected_sentence": "这台打印机重启了一次。", "error_description": "“重启”的动量词应为“次”，不能说“一个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
