INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12367, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指时间和空间，即物质运动所经历的不同时刻和不同位置的总和。", "primary_collocate": null, "pronunciation": "shí kōng", "ipa": "ʂɨ˧˥ kʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "在此类框架下，讲述一则民间传说不仅是在复述往事，更是在执行一种文化实践：说者通过语言激活神圣时空，听者则在沉浸中获得身份认同的再确认。", "target_word": "时空", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "虽然古罗马的生活方式和我们今天有很大不同，但孩子们对家庭的爱和对游戏的兴趣，却是跨越时空的。", "target_word": "时空", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这部电影带我们回到另一个时空。", "target_word": "时空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了网络，朋友之间不再受时空限制。", "target_word": "时空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家正在研究时空的秘密。", "target_word": "时空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐能让人跨越时空，感受古人的心情。", "target_word": "时空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱因斯坦认为时空会因重力而弯曲。", "target_word": "时空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说写了不同时空的两个人。", "target_word": "时空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宇宙中的时空可能比我们想象的更复杂。", "target_word": "时空", "complexity_tier": "T3", "furigana": "shí kōng", "sentence_source": "generated"}, {"text": "书信让远方的亲人跨越了时空。", "target_word": "时空", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "时空观", "label": "复合"}], "register": "书面", "sense_fingerprint": "时间与空间的总称，常说跨越时空、受时空限制", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94fd5d6a-ee47-45b7-8109-ed74731efdc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12367, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时空", "is_correct": true, "explanation": "正确：「激活神圣时空」指激活时间与空间构成的神圣语境，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」不能被「激活」，与「神圣」的语境不合。"}, {"text": "体重", "is_correct": false, "explanation": "语义：「体重」不是可以被激活的对象，句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：「激活」多用于功能或感觉，「神圣味道」不成立。"}], "explanations": {"时空": "正确：「激活神圣时空」指激活时间与空间构成的神圣语境，与句意相符。", "颜色": "语义：「颜色」不能被「激活」，与「神圣」的语境不合。", "体重": "语义：「体重」不是可以被激活的对象，句意不通。", "味道": "搭配：「激活」多用于功能或感觉，「神圣味道」不成立。"}, "sentence_index": 0, "correct_answer": "时空"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份作业要在规定时空内完成。", "explanation": "这里应该用〈时间〉。时空指时间和空间的总和，不能只指时间。"}, {"text": "我每天用时空做饭，很方便。", "explanation": "「时空」是抽象概念，不能当作工具使用。"}, {"text": "这个房间的时空很大，可以放一张大床。", "explanation": "这里应该用〈空间〉。时空指时间和空间的总和，形容房间的大小只能说空间，不能说时空。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12367, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时空", "is_correct": true, "explanation": "正确：「时空会因重力而弯曲」指时间与空间构成的整体会受重力影响，符合物理学语境。"}, {"text": "故事", "is_correct": false, "explanation": "语义：「故事」不会因重力弯曲，句意不通。"}, {"text": "心情", "is_correct": false, "explanation": "语义：「心情」不是物体，不能因重力而弯曲。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：「弯曲」多用于物体形状，不能用于「价格」。"}], "explanations": {"时空": "正确：「时空会因重力而弯曲」指时间与空间构成的整体会受重力影响，符合物理学语境。", "故事": "语义：「故事」不会因重力弯曲，句意不通。", "心情": "语义：「心情」不是物体，不能因重力而弯曲。", "价格": "搭配：「弯曲」多用于物体形状，不能用于「价格」。"}, "sentence_index": 6, "correct_answer": "时空"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛是他最好的时空，他一定要抓住。", "explanation": "「时空」不表示「机会」，这里的意思用错了。它只指时间与空间的总和。"}, {"text": "我家有一块时空，就在那个山里。", "explanation": "这里应该用〈地〉。「块」用来计量具体的地块，时空是抽象概念，不能用「块」计量。"}, {"text": "今天的时空很好，我们去公园玩吧。", "explanation": "「时空」不指天气。它只表示时间与空间的总和，这里的意思用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12367, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "科学家在研究过时空。", "corrected_sentence": "科学家研究过时空。", "error_description": "体标与进行体冲突：“过”表示经历，不能与表示进行的“在”同用，应去掉“在”，说“科学家研究过时空”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12367, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里有一只奇妙的时空。", "corrected_sentence": "这里有一个奇妙的时空。", "error_description": "「时空」的量词应为「个」，不能用「只」。「一只奇妙的时空」错误，正确为「一个奇妙的时空」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
