INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12368, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "听者指听别人说话或声音的人。", "primary_collocate": null, "pronunciation": "tīng zhě", "ipa": "tʰiŋ˥ ʈʂɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "在此类框架下，讲述一则民间传说不仅是在复述往事，更是在执行一种文化实践：说者通过语言激活神圣时空，听者则在沉浸中获得身份认同的再确认。", "target_word": "听者", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "好的演讲者会注意听者的反应。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听者安静地坐在台下。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人是一个很好的听者。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事讲完后，听者都鼓起掌来。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说者要看着听者的眼睛。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有时候，听者比说者更累。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是做一个认真的听者。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诗人把心里的话讲给听者。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广播结束后，听者打来了电话。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "聽者", "label": "繁体"}], "register": "书面", "sense_fingerprint": "听别人说话或声音的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f278538-1681-45dd-833e-5419567a1254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12368, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "听者", "is_correct": true, "explanation": "听者（tīng zhě）指听别人说话或声音的人，是本题的正确答案。"}, {"text": "停止", "is_correct": false, "explanation": "停止（tíng zhǐ）与 tīng zhě 两个音节的声调都不同，意思是停下、中止。"}, {"text": "挺直", "is_correct": false, "explanation": "挺直（tǐng zhí）与 tīng zhě 两个音节的声调都不同，意思是笔直、伸直。"}, {"text": "听着", "is_correct": false, "explanation": "听着（tīng zhe）第二音节为轻声，与 zhě（第三声）声调不同，意思是动作正在进行。"}, {"text": "停着", "is_correct": false, "explanation": "停着（tíng zhe）与 tīng zhě 声调不同，意思是停放或停留着。"}, {"text": "挺着", "is_correct": false, "explanation": "挺着（tǐng zhe）与 tīng zhě 声调不同，意思是向前凸出或坚持着。"}], "explanations": {"听者": "听者（tīng zhě）指听别人说话或声音的人，是本题的正确答案。", "停止": "停止（tíng zhǐ）与 tīng zhě 两个音节的声调都不同，意思是停下、中止。", "挺直": "挺直（tǐng zhí）与 tīng zhě 两个音节的声调都不同，意思是笔直、伸直。", "听着": "听着（tīng zhe）第二音节为轻声，与 zhě（第三声）声调不同，意思是动作正在进行。", "停着": "停着（tíng zhe）与 tīng zhě 声调不同，意思是停放或停留着。", "挺着": "挺着（tǐng zhe）与 tīng zhě 声调不同，意思是向前凸出或坚持着。"}, "sentence_index": null, "correct_answer": "听者"}, "level_3": {"options": [{"text": "听者", "is_correct": true, "explanation": "听者指听别人说话或声音的人，与前句的“说者”相对，符合句意。"}, {"text": "说者", "is_correct": false, "explanation": "语义：前一分句已用“说者”作主语，此处“则”要引出与之相对的另一方，再用“说者”则角色重复、句意混乱。"}, {"text": "旁观者", "is_correct": false, "explanation": "语义：“沉浸”要求投入其中，“旁观者”指置身事外的人，与句意相反。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师与讲述、倾听无关，不能与「说者」构成讲述与倾听的相对关系。"}], "explanations": {"听者": "听者指听别人说话或声音的人，与前句的“说者”相对，符合句意。", "说者": "语义：前一分句已用“说者”作主语，此处“则”要引出与之相对的另一方，再用“说者”则角色重复、句意混乱。", "旁观者": "语义：“沉浸”要求投入其中，“旁观者”指置身事外的人，与句意相反。", "厨师": "语义：厨师与讲述、倾听无关，不能与「说者」构成讲述与倾听的相对关系。"}, "sentence_index": 0, "correct_answer": "听者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "舞台剧演完后，听者们都站起来鼓掌。", "explanation": "这里应该用〈观众〉。听者指听别人说话或声音的人，看舞台剧的人应说观众。"}, {"text": "公交车上坐满了听者，大家都在低头看手机。", "explanation": "这里应该用〈乘客〉。听者指听别人说话的人，乘坐车辆的人应说乘客。"}, {"text": "这本杂志的听者很多，每期都卖得很快。", "explanation": "这里应该用〈读者〉。听者指听别人说话的人，阅读杂志的人应说读者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12368, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听者", "is_correct": true, "explanation": "听者指听别人说话的人，与“说者”相对，放在“有时候”的句子里符合句意。"}, {"text": "木偶", "is_correct": false, "explanation": "语义：木偶没有感觉，不会“累”，与句意冲突。"}, {"text": "雕像", "is_correct": false, "explanation": "语义：雕像是静止的物件，不会“累”，与句意冲突。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“累”的主语应是有感觉、能活动的人或动物，不能用“石头”。"}], "explanations": {"听者": "听者指听别人说话的人，与“说者”相对，放在“有时候”的句子里符合句意。", "木偶": "语义：木偶没有感觉，不会“累”，与句意冲突。", "雕像": "语义：雕像是静止的物件，不会“累”，与句意冲突。", "石头": "搭配：“累”的主语应是有感觉、能活动的人或动物，不能用“石头”。"}, "sentence_index": 6, "correct_answer": "听者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "超市里的听者越来越多，大家都在挑东西。", "explanation": "这里应该用〈顾客〉。听者指听别人说话的人，在超市购物的人应说顾客。"}, {"text": "博物馆里的听者很多，大家都在看展品。", "explanation": "这里应该用〈游客〉。听者指听别人说话的人，参观博物馆的人应说游客。"}, {"text": "球场上的听者很热情，一直在为球队加油。", "explanation": "这里应该用〈球迷〉。听者指听别人说话的人，为球队加油的人应说球迷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12368, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天遇到一只很好的听者。", "corrected_sentence": "我昨天遇到一位很好的听者。", "error_description": "量词错误：“听者”指人，应用量词“位”或“个”，不能用“只”（“只”多用于动物或成对的物品）。正确说法是“一位很好的听者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12368, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班来了一位很好听者。", "corrected_sentence": "我们班来了一位很好的听者。", "error_description": "漏掉“的”：“很好的”是修饰“听者”的定语，二者之间要用“的”，应说“很好的听者”，不能说“很好听者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12369, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失去", "is_correct": true, "explanation": "正确答案。“失去”与“获得”构成反义，指不再拥有原先得到的东西。"}, {"text": "寻找", "is_correct": false, "explanation": "“寻找”指去找，与“获得”没有反义关系。"}, {"text": "维持", "is_correct": false, "explanation": "“维持”指保持现状，与“获得”没有反义关系。"}, {"text": "保持", "is_correct": false, "explanation": "“保持”指使某种状态不变，与“获得”没有反义关系。"}], "correct_answer": "失去", "explanations": {"失去": "正确答案。“失去”与“获得”构成反义，指不再拥有原先得到的东西。", "寻找": "“寻找”指去找，与“获得”没有反义关系。", "维持": "“维持”指保持现状，与“获得”没有反义关系。", "保持": "“保持”指使某种状态不变，与“获得”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12369, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失去", "is_correct": true, "explanation": "正确答案。“失去”与“获得”构成反义，指不再拥有原先得到的东西。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”指探究事理，与“获得”没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "“搬运”指把物体从一处运到另一处，与“获得”没有反义关系。"}, {"text": "保护", "is_correct": false, "explanation": "“保护”指使人或物免受伤害，与“获得”没有反义关系。"}], "correct_answer": "失去", "explanations": {"失去": "正确答案。“失去”与“获得”构成反义，指不再拥有原先得到的东西。", "研究": "“研究”指探究事理，与“获得”没有反义关系。", "搬运": "“搬运”指把物体从一处运到另一处，与“获得”没有反义关系。", "保护": "“保护”指使人或物免受伤害，与“获得”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12369, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "取得，得到。", "primary_collocate": null, "pronunciation": "huò dé", "ipa": "xu̯ɔ˥˩ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "我在书里获得了很多知识。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他终于获得了一次好机会。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从朋友那里获得了很大的帮助。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生可以在网上获得新的信息。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她努力工作，获得了成功。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这件事，我获得了不少经验。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想获得更多的自由。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在游戏中获得了快乐。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以在这里获得免费的帮助。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先获得他的同意。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "獲得", "label": "繁体"}, {"form": "获得了", "label": "体标"}, {"form": "获得过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "取得、得到知识、机会、帮助等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5ba59dc-380a-4728-a304-98f8c579d0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12369, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "获得", "is_correct": true, "explanation": "正确答案。获得（huò dé）：取得，得到。"}, {"text": "活得", "is_correct": false, "explanation": "huó（第二声）与 huò（第四声）声调不同，意思是活着、过日子。"}, {"text": "活的", "is_correct": false, "explanation": "huó 与 huò 声调不同，de（轻声）与 dé 声调不同，意思是有生命的。"}, {"text": "豁得", "is_correct": false, "explanation": "huō（第一声）与 huò（第四声）声调不同，意思是豁出去、舍得。"}], "explanations": {"获得": "正确答案。获得（huò dé）：取得，得到。", "活得": "huó（第二声）与 huò（第四声）声调不同，意思是活着、过日子。", "活的": "huó 与 huò 声调不同，de（轻声）与 dé 声调不同，意思是有生命的。", "豁得": "huō（第一声）与 huò（第四声）声调不同，意思是豁出去、舍得。"}, "sentence_index": null, "correct_answer": "获得"}, "level_3": {"options": [{"text": "获得", "is_correct": true, "explanation": "“获得”表示取得知识，此处指在书里取得了很多知识。"}, {"text": "丢失", "is_correct": false, "explanation": "语义：“丢失”是失去，与“在书里”取得知识的语境相反。"}, {"text": "消耗", "is_correct": false, "explanation": "搭配：“消耗”多用于能量、时间，不能接“知识”。"}, {"text": "挥霍", "is_correct": false, "explanation": "搭配：“挥霍”多接钱财、时间，不接“知识”。"}], "explanations": {"获得": "“获得”表示取得知识，此处指在书里取得了很多知识。", "丢失": "语义：“丢失”是失去，与“在书里”取得知识的语境相反。", "消耗": "搭配：“消耗”多用于能量、时间，不能接“知识”。", "挥霍": "搭配：“挥霍”多接钱财、时间，不接“知识”。"}, "sentence_index": 0, "correct_answer": "获得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我获得了一次感冒，只好在家休息。", "explanation": "这里应该用〈染上〉。“获得”指取得好处或帮助，感冒是疾病，不能这样得到，应说“染上感冒”。"}, {"text": "我在路上获得了很多伤害。", "explanation": "这里应该用〈遭受〉。“获得”指得到好处或帮助，伤害要说“遭受”。"}, {"text": "我获得了一场考试。", "explanation": "这里应该用〈参加〉。“获得”的对象是知识、机会、帮助等，考试是活动，应说“参加考试”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12369, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "获得", "is_correct": true, "explanation": "正确答案。获得（huò dé）：取得，得到。"}, {"text": "过得", "is_correct": false, "explanation": "guò（第四声）与 huò 的声母不同（g 与 h），意思是过日子，如“过得很好”。"}, {"text": "握得", "is_correct": false, "explanation": "wò（第四声）与 huò 的声母不同（w 与 h），意思是握，如“握得很紧”。"}, {"text": "扩得", "is_correct": false, "explanation": "kuò（第四声）与 huò 的声母不同（k 与 h），意思是扩大，如“扩得很大”。"}], "explanations": {"获得": "正确答案。获得（huò dé）：取得，得到。", "过得": "guò（第四声）与 huò 的声母不同（g 与 h），意思是过日子，如“过得很好”。", "握得": "wò（第四声）与 huò 的声母不同（w 与 h），意思是握，如“握得很紧”。", "扩得": "kuò（第四声）与 huò 的声母不同（k 与 h），意思是扩大，如“扩得很大”。"}, "sentence_index": null, "correct_answer": "获得"}, "level_3": {"options": [{"text": "获得", "is_correct": true, "explanation": "“获得”表示取得机会或权利，此处指大家想取得更多的自由。"}, {"text": "失去", "is_correct": false, "explanation": "语义：“失去”是丢掉，与“想要更多”的愿望相反。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”是主动舍去，与“都想”的语境相反。"}, {"text": "偿还", "is_correct": false, "explanation": "搭配：“偿还”用于债务，不能接“自由”。"}], "explanations": {"获得": "“获得”表示取得机会或权利，此处指大家想取得更多的自由。", "失去": "语义：“失去”是丢掉，与“想要更多”的愿望相反。", "放弃": "语义：“放弃”是主动舍去，与“都想”的语境相反。", "偿还": "搭配：“偿还”用于债务，不能接“自由”。"}, "sentence_index": 6, "correct_answer": "获得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他获得了那个对手。", "explanation": "这里应该用〈打败〉。“获得”的对象应是能取得的东西，对手不能被“获得”，应说“打败对手”。"}, {"text": "这篇文章获得了一个标题。", "explanation": "这里应该用〈拟定〉。“获得”指取得可得到的东西，标题不能这样得到，应说“拟定标题”。"}, {"text": "会议获得了一场大雨。", "explanation": "这里应该用〈下〉。“获得”指取得某物，雨不能被获得，应说“下了一场大雨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12369, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于获得到一份好工作。", "corrected_sentence": "他终于获得了一份好工作。", "error_description": "“获得”后不能再接补语“到”，“得到”才有这样的用法。此处应说“获得了一份好工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12369, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个学生想获得了一次留学的机会。", "corrected_sentence": "这个学生想获得一次留学的机会。", "error_description": "“想”表示打算，后面不能用“了”表示完成。此处应说“想获得一次留学的机会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
